"""
===========================================================================================
ViTAL-CF : Clock-Field Cold Diffusion with the ViTAL backbone (no VQ)
===========================================================================================

A deterministic ("cold") diffusion model for image restoration (deblurring first, and also
denoising / inpainting / pixelation and an all-in-one "mixed" mode) plus unconditional
generation from a degraded prior.

Layout of this file
-------------------
    SECTION 0  Imports
    SECTION 1  Configuration                      -> class Config
    SECTION 2  Utilities
    SECTION 3  Physics: exact heat operator and cold degradations
    SECTION 4  Datasets                           -> ImageDataset, SyntheticImageDataset
    SECTION 5  Model                              -> ViTAL backbone, SpectralClockEstimator,
                                                     ClockAwareSpectralGate, ColdDiffusionModel
    SECTION 6  Losses                             -> ColdDiffusionLoss
    SECTION 7  Metrics
    SECTION 8  Trainer                            -> Trainer (+ EMA)
    SECTION 9  Inferencer                         -> Inferencer
    SECTION 10 Main                               -> main(), deblur_image_pipeline()

What is new compared to cold diffusion (Bansal et al., 2022) and the rest of the literature
-------------------------------------------------------------------------------------------
Two headline contributions:

 [N1] SPECTRAL CLOCK FIELD (SCF): blind, spatially varying cold diffusion.
      The scalar diffusion time t becomes a per-pixel field tau(x) in [0, 1]. The forward
      operator is a spatially varying heat dissipation, built from an exact DCT-domain heat
      kernel bank that is interpolated per pixel. The network is conditioned on the field
      through Clock-Modulated Normalisation, a spatial FiLM computed from a per-pixel clock
      embedding.
      A Spectral Clock Estimator (SCE) reads the degradation level straight from the
      observation. Gaussian blur multiplies the spectrum by exp(-sigma^2 w^2 / 2), so the
      log-ratio of neighbouring band energies is linear in sigma^2, and the SCE uses those
      log-ratios as physics features. It predicts tau(x) together with an aleatoric
      confidence. The confidence drives a normalised-convolution smoothing of the field,
      which propagates the clock from textured areas into flat areas where blur cannot be
      identified.
      Sampling uses Synchronised Field Descent, tau_k(x) = tau_obs(x) * u_k, so every pixel
      reaches tau = 0 on the same step. By contrast, SVNR (Kawar et al. 2023) uses noise-only,
      asynchronous per-pixel times, and DynFaceRestore / SuperSharpen estimate a single
      global blur level.

 [N2] SPECTRAL RANGE-NULL COLD SAMPLER (SRN-CS).
      Bansal's improved update  x_s = x_t - D(x0_hat, t) + D(x0_hat, s)  is combined with an
      exact Fourier-domain range/null-space anchoring of x0_hat to the observation y:
          x0_hat <- x0_hat + eta * K/(K^2 + lambda) * (y - D(x0_hat, tau_obs))
      Here K is the analytic heat transfer function, with local anchors for clock fields.
      Frequencies the operator keeps (the range space) are taken from the data. Frequencies
      the operator annihilated (the null space) are generated by the network. This is the
      DDNM idea (Wang et al. 2023), moved from Gaussian diffusion to deterministic
      heat-dissipation trajectories and to spatially varying operators.

Supporting contributions (model / losses / training):
 [N3] Clock-Aware Spectral Gate (CASG): a feature-space inverse-heat filter. Its gain
      exp(c_c * tanh(a_c * sigma_f^2 |w|^2 / (2 c_c))) follows the physics of the estimated
      clock and saturates smoothly at a learned ceiling c_c. A learned residual spectral
      response is added on top, and the result is gated
      spatially by the clock field.
 [N4] Sampler-Consistent Rollout (SCR) loss: the network is also trained on the exact
      Algorithm-2 states that its own detached prediction produces. This closes the
      train/test exposure gap of cold sampling, and it supplies self-conditioning inputs for
      free (no teacher, no extra EMA network; compare the EPCT of ReCo-Diff 2026).
 [N5] Null-Space Spectral (NSS) loss: an L1 loss in the Fourier domain weighted by the
      annihilation spectrum (1 - |K_tau(w)|^2)^gamma of the actual degradation, so capacity
      goes to the frequencies the operator destroyed.
 [N6] Mean-decoupled beta-Laplace uncertainty. The uncertainty head never biases the mean.
      Its output drives the uncertainty maps, the calibration plots, and an
      uncertainty-gated stochastic refinement ("churn") in the sampler.
 [N7] Exact continuous-time Neumann heat operator (a DCT-equivalent even extension plus FFT),
      with sigma(0) = 0 exactly. This replaces the truncated 31-tap kernel, which saturated
      at large sigma and darkened the image borders.
 [N8] Degraded-prior bank for generation: a Gaussian fitted to thumbnails of maximally
      degraded images, replacing the incorrect "start from white noise" of a blur model.

Extensions for real blur, motion blur and noise (no new network parameters):
 [N9]  MOMENT-MATCHED BLUR FAMILY. The blur kind now contains defocus (the isotropic heat kernel,
       bit-identical to the pretrained operator), anisotropic heat kernels and linear motion
       streaks (exact transfer sinc(L w.d/2)). The clock keeps ONE physical meaning for every shape:
       trace(Cov)/2 = sigma(tau)^2 (motion: L = sqrt(24) sigma), so the spectral clock estimator,
       the clock embedding and the spectral gate need no change.
 [N10] CLOCK-TIED NOISE. Blur samples may carry noise eta * tau * eps that vanishes at tau = 0, so
       blur + noise stays a proper cold-diffusion path; the sampler re-estimates eps from the
       current state (DDIM-like) and never reads it from the ground truth.
 [N11] PHYSICS-FITTED CLOCK LABELS FOR REAL PAIRS. For a real blurred/sharp pair, the blur
       covariance is read from the log spectral ratio |Y|^2/|X|^2 (the image content cancels), then
       a per-tile least-squares clock gives a confidence-weighted clock field. Real GoPro pairs are
       mixed into training with these labels (network AND clock estimator learn real blur).
 [N12] BLIND OPERATOR ROBUSTNESS. (a) Blur direction / axis ratio of a single photo from the
       deviator of its directional spectral decay (trace from the learned clock). (b) Residual
       annealing: whatever the operator does not explain (real noise, kernel mismatch) shrinks by
       s/t per step instead of being added back to the output as in plain Algorithm 2.
       (c) Operator-uncertainty Wiener K/(K^2 + lam + Var[dK]) driven by the estimator's own
       clock uncertainty. (d) Blind SRN anchors once at the last step: repeated anchoring converges
       to the unregularised inverse y/K. (e) For rotated kernels with mirror boundaries, a
       residual-optimal step keeps the anchoring monotone (it diverged when iterated).
 [N13] RESIDUAL SPECTRAL GATE. The Algorithm-2 residual r = x_t - K_t x0_hat is the sum of two
       things with different spectra: the network error seen through the blur, -K_t e (coloured,
       band-limited by K_t, which Algorithm 2 must keep so that errors cancel to (K_s - K_t) e), and
       the observation noise n (white, which Algorithm 2 keeps forever and which cost up to 9 dB
       against one-shot prediction in the controlled study). A per-frequency Wiener gain
       G = max(0, 1 - s^2 / P_r(w)) on the DCT (even-extended) spectrum, with s^2 measured on the
       residual itself (MAD of its finest diagonal Haar band, where -K_t e has no energy), keeps
       G r and anneals (1 - G) r by s/t. s = 0 gives back Algorithm 2 exactly; pure noise gives
       residual annealing. The same gate cleans the range-null residual before Wiener anchoring.
       Known operators only: a mis-estimated blind operator leaves a coloured mismatch residual
       that the gate would keep, so blind photos keep residual annealing [N12b].

Dataset roles (enforced by a start-up audit)
--------------------------------------------
  CLEAN images only as ground truth for synthetic degradations: train_data_dir + the SHARP frames of
  the real TRAIN pairs (GoPro, HIDE, RealBlur-J/-R, TextOCR; at most real_sharp_max_per_subset each),
  val_data_dir, test_data_dir = GoPro test SHARP. Real pairs for TRAINING: the train splits of
  real_train_subsets, balanced per dataset (real_subset_balance); real pairs for VALIDATION /
  BENCHMARKS: the test splits of real_test_subsets (never trained on). Real blurred photos:
  real_images_dir = HIDE test BLUR (ground truth read from the sibling sharp/gt folder). Layouts:
  DBlur <subset>/<split>/{blur,sharp} or <subset>/<split>/<scene>/{blur,sharp}; subset names match
  case- and separator-insensitively ('RealBlur' -> RealBlur_J + RealBlur_R). The previous config used
  Gopro/test/BLUR as clean ground truth and HIDE/test/SHARP as the photos to deblur; the audit stops
  on such a configuration, and reports every requested real dataset it could not find.

Bugs of the previous version that are fixed here (the main ones)
-----------------------------------------------------------------
  * `dataclass`, `field` and `asdict` were used without being imported. The SR/GAN Config
    was never used.
  * The time was normalised twice (t/T/T), so the network received t ~ 1e-6. The
    sinusoidal embedding was also fed t in [0, 1] without scaling. Both are fixed.
  * "Importance" timestep sampling drew almost only tiny-blur steps (weights 1/sigma),
    contradicting its own comment.
  * The random mask was re-drawn on every call, so it was not a deterministic cold
    degradation and Algorithm 2 was meaningless. It now uses a fixed per-sample rank field
    with nested masks.
  * Blur kernels were truncated to 31 taps (sigma up to 30) with zero padding.
  * U-Net skips were misaligned by one resolution level (and bicubically resized). The
    full-resolution stem features were never used.
  * BatchNorm with batch size 3 inside a diffusion denoiser is replaced by GroupNorm.
  * Swin: the image is now padded before it is rolled, and masks are cached instead of
    re-registering buffers on every forward pass. The shift order now follows Swin.
  * Training metrics were overwritten after the checkpoint was loaded, so resuming lost
    the curves.
  * Validation used random timesteps, so the curves were noisy. It is now deterministic.
  * The naive (Algorithm 1) sampler was used even though the degradation is smooth.
    `sample()` started a blur model from Gaussian noise. Real-image deblurring always
    started at maximum blur and injected noise with a standard deviation of up to 1.5.
  * cv2 and glob were imported but not used; the per-sample Python loop in the forward
    degradation is removed; plt.show() is gone.

Running on Kaggle "GPU T4 x2" (Settings -> Accelerator -> GPU T4 x2)
--------------------------------------------------------------------
  Both T4s are used for training. The mode is selected automatically:
    * Run this file directly in a notebook cell -> nn.DataParallel over both GPUs.
    * Faster: put `%%writefile vital_cf.py` as the first line of the cell, run it, then run
          !torchrun --nproc_per_node=2 vital_cf.py
      -> DistributedDataParallel, one process per T4 (rank 0 validates, saves and runs inference).
      NCCL peer-to-peer (which can block forever on the two PCIe T4s) is disabled automatically on Kaggle / T4
      (Config.nccl_safe_mode); setting NCCL_P2P_DISABLE yourself overrides it.
  In both modes the *whole* training objective (degradation, both network passes of the SCR
  rollout, clock estimator, every loss) runs on each GPU for its share of the batch.
  `batch_size` is per GPU, so the global batch is 2 x batch_size on T4 x2.
  T4 (sm_75) has fp16 tensor cores and no native bf16, so AMP uses fp16 + GradScaler there.
  (torch.cuda.is_bf16_supported() returns True on T4 through emulation, which silently made
  the previous version train in slow emulated bf16.) Inference and interpretability run on
  cuda:0. Checkpoints hold the plain (unwrapped) state_dict, so they load anywhere.

Continuing a pretrained model safely (Kaggle 12 h sessions)
----------------------------------------------------------
  * The start-up checkpoints are copied once to <checkpoint_dir>/pretrained_backup/ (never
    overwritten, never pruned). An architecture mismatch now stops with an error instead of
    moving the checkpoint away and silently training from scratch, and `require_pretrained`
    refuses to start from scratch when no checkpoint is found.
  * resume_from='auto' also finds checkpoint_latest.pt in a previous notebook version attached
    under /kaggle/input (read-only, therefore safe); the working copy in checkpoint_dir wins.
  * A time budget (11 h on Kaggle) stops training cleanly, and a mid-epoch checkpoint is written
    every 30 min; both resume *exactly* at the sample where training stopped.
  * The sampler validation ("sampler" in the epoch line) runs every epoch on realistic
    observations (sensor noise + 8-bit), in fp32, on 2 batches, known-clock and blind. The old
    line printed 'nan' on every epoch where it was not scheduled, and the one value it did
    compute (~53 dB) was inflated by a noiseless observation (inverse crime).
  * Config.epochs is the TOTAL number of epochs. A checkpoint already at epoch >= epochs has
    nothing to train: this is now announced (it used to print "Training completed successfully!"
    after training nothing). Config.extra_epochs = N trains N epochs beyond the checkpoint with a
    restarted LR schedule (warm-up + cosine, peak finetune_lr); the request is stored in the
    checkpoint so an interrupted run continues it in the next session.

What the last log showed and what changed
-----------------------------------------
  * No epoch was trained (epochs=5 < resumed epoch 9) -> banner + extra_epochs (above).
  * Known-operator SRN/Algorithm 2 kept the observation noise forever (SRN at tau 0.2 was 3.5 dB
    below one-shot 'direct') -> Residual Spectral Gate [N13] + noise-aware anchoring.
  * Blind clock was a lower confidence bound (systematic under-estimation, residual blur) ->
    posterior mean (blind_clock_margin = 0); photos are restored at up to 1280 px, not 768 px,
    so the blur scale the estimator sees matches the real one.
  * Real pairs: the network was conditioned on the oracle (fitted) clock during training but on
    the ESTIMATED clock at test time -> estimator-in-the-loop conditioning for part of the steps.
  * Blurry photos could be routed to the NOISE branch -> blur unless the type head is >= 70 % sure.
  * Evaluation took ~1 h in fp32 with 50 steps and the naive sampler -> fp16 autocast, 20 steps,
    naive dropped, blind 'direct' added (the realistic use case), the chosen kind is logged.

Fixed in this revision
----------------------
  * THE START-UP HANG after "Creating trainer (auto-resumes ...)": with an empty checkpoint_dir (every new
    Kaggle session) resume_from='auto' ran Path('/kaggle/input').rglob(...) twice, i.e. it walked EVERY
    attached dataset file by file (ImageNet-10k + Unsplash + the whole DBlur collection: hundreds of
    thousands of files on a network-backed mount) before printing anything. The search is now a bounded,
    shallow-first walk (find_checkpoints) that skips the configured data folders and image folders, has a
    depth and time limit, prints what it does, runs on rank 0 only and broadcasts the result under DDP.
  * DDP on T4 x2 could also block in the first NCCL collective (inside the DDP constructor, i.e. at the same
    spot): NCCL peer-to-peer is disabled by default on Kaggle / T4 (Config.nccl_safe_mode).
  * Checkpoints are loaded to the CPU (optimiser state no longer takes GPU memory twice at start-up).
  * Under DDP every rank drew its own rollout / real-pair decision (one GPU idled while the other ran two
    network passes); the decisions now come from a generator seeded by (seed, epoch, batch) - identical on
    every rank and reproducible after a mid-epoch resume.
  * An epoch with drop_last was never recognised as finished when the time budget hit its last batch.
  * The fine-tuning LR restart used Config.learning_rate instead of the optimiser's base LR.
  * A checkpoint already BEYOND Config.epochs counted as "not complete" (no inference, no prior fit).
  * The time budget was measured from the module import, so re-running the notebook cell reset it and the
    11 h budget could overrun Kaggle's 12 h limit; it is now measured from the process start.
  * Swin windows attended to zero-padded tokens for inputs whose latent size is not a multiple of the window
    (every real 1280x720 photo); padded tokens are now masked (training at 256 px is unchanged).
  * Generation applied the maximal blur a second time to a sample that was already drawn from the prior of
    maximally blurred images (the sampler started at sigma_max * sqrt(2)).
  * The real benchmark mixed resolutions after an out-of-memory fallback (crash in the example grid,
    inconsistent metrics); the dataset audit compared blur/sharp pairs by file NAME only (wrong files or a
    crash for nested folders); the heat-kernel spectrum cache grew without bound with the image size;
    invalid Config strings (sampler, schedule, ...) silently fell back to other code paths.

Second round (log of the first Kaggle run with the fixes above)
---------------------------------------------------------------
  * The search finished (3081 folders, 77 s) but found no checkpoint, and require_pretrained=True then
    stopped the run. The search now (a) also accepts checkpoint_epoch_*.pt and, if nothing else fits, other
    *.pt / *.pth / *.ckpt files whose tensors match the model exactly, (b) visits notebook outputs / models
    first, '<input>/datasets/...' next and the trees of the configured data sets (and their aliases under
    the other Kaggle layout) last - not at all once a checkpoint is found, (c) probes the checkpoint names in
    image folders it does not crawl, and (d) also looks in /kaggle/working. With no checkpoint at all, the run
    now trains from scratch behind a banner that lists where it looked (require_pretrained=True restores the
    error); a found checkpoint of this pipeline that does not fit the architecture still stops the run.
  * Training data: real pairs from GoPro, HIDE, RealBlur (J and R) and TextOCR train splits, balanced per
    dataset; their sharp frames also feed the synthetic degradations; per-epoch real validation covers every
    real test set (with per-dataset PSNR), and the best-model score is reset when that set changes.
  * Real-pair folders: fuzzy subset names, blur/sharp synonyms (input/target, lq/gt, ...), per-scene layouts,
    differently named sides (blur_12 / gt_12), mirror padding of images smaller than the crop (the batch could
    not be collated), and folder listings cached for the whole run (each listing is slow on /kaggle/input).

Everything runs without argparse/sys: edit `Config` (or pass one to `main(cfg)`).
"""

