KINDS: Tuple[str, ...] = ("blur", "noise", "mask", "downsample")
BLUR, NOISE, MASK, DOWNSAMPLE = 0, 1, 2, 3
# Shapes of the blur family inside the BLUR kind (no new network parameters: the kind embedding
# and the clock-estimator type head keep their 4 classes, so pretrained checkpoints load unchanged).
BLUR_SHAPES: Tuple[str, ...] = ("iso", "aniso", "motion")
ISO, ANISO, MOTION = 0, 1, 2
DBLUR_ROOT = "/kaggle/input/datasets/jishnuparayilshibu/a-curated-list-of-image-deblurring-datasets/DBlur"


@dataclass
class Config:
    """All hyper-parameters and paths of the pipeline (training + inference)."""

    # ----------------------------- Paths -----------------------------
    # CLEAN (sharp) images only -> degraded on the fly by the cold-diffusion operators.
    train_data_dir: str = "/kaggle/input/imagenet1kmediumtest-10k/test_10000/test_10000"
    extra_clean_dirs: Tuple[str, ...] = ()  # more CLEAN training folders (sharp only!). The sharp frames of the real
    #                                         training pairs are added automatically (real_sharp_as_clean)
    val_data_dir: str = "/kaggle/input/unsplash/1k/1k"
    # Clean held-out set for the synthetic evaluation. The previous config pointed at .../Gopro/test/BLUR,
    # i.e. blurred images were used as ground truth.
    test_data_dir: str = f"{DBLUR_ROOT}/Gopro/test/sharp"
    # REAL blurred photos for blind restoration (ground truth found automatically in the sibling 'sharp'
    # folder). The previous config pointed at .../HIDE/test/SHARP, i.e. sharp photos were 'deblurred'.
    real_images_dir: str = f"{DBLUR_ROOT}/HIDE/test/blur"
    # Real paired data (DBlur layout <root>/<subset>/<split>/{blur,sharp}, identical file names).
    paired_root: str = DBLUR_ROOT
    # Real blur->sharp datasets under paired_root. Names are matched case- and separator-insensitively, and a name
    # that is not an exact folder matches every folder starting with it: 'RealBlur' -> RealBlur_J + RealBlur_R.
    # The audit prints what was found, what is missing and the folders that exist.
    real_train_subsets: Tuple[str, ...] = ("Gopro", "HIDE", "RealBlur", "TextOCR")  # real pairs mixed into training
    real_test_subsets: Tuple[str, ...] = ("Gopro", "HIDE", "RealBlur", "TextOCR")  # real benchmarks (held-out test splits)
    real_subset_balance: str = "equal"  # share of each requested dataset in the real steps: 'equal' | 'sqrt' | 'size'
    real_sharp_as_clean: bool = True  # sharp frames of the real TRAIN pairs are also clean images for synthetic blur
    real_sharp_max_per_subset: int = 3000  # (evenly thinned, so a huge set such as TextOCR does not dominate; 0 = all)
    strict_dataset_audit: bool = True  # stop if a blurred folder is used as ground truth / pairs look swapped
    output_dir: str = "./results"
    checkpoint_dir: str = "./runnings"
    visualization_dir: str = "./vizs"

    # ----------------------------- Data -----------------------------
    image_size: Tuple[int, int] = (256, 256)
    augment: bool = True
    max_train_images: int = 0  # 0 = use all
    max_val_images: int = 0
    synthetic_fallback: bool = True  # procedural images if the folders do not exist
    synthetic_num_train: int = 512
    synthetic_num_val: int = 64

    # ----------------------------- ViTAL backbone -----------------------------
    in_channels: int = 3
    dim: int = 48  # base channels (Stem output)
    num_heads: int = 8
    window_size: int = 8  # 256/8 = 32 latent -> 4x4 windows, no padding waste
    num_features: int = 128  # conditioning width == bottleneck width
    swin_blocks: int = 2
    swin_drop_path: float = 0.1
    swin_drop: float = 0.1
    clock_embed_dim: int = 32  # per-pixel clock embedding channels  [N1]
    use_spectral_gate: bool = True  # [N3]
    self_condition: bool = True
    predict_uncertainty: bool = True  # [N6]
    with_residual: bool = True  # x0 = x_t + residual

    # ----------------------------- Cold diffusion -----------------------------
    # 'allinone': blur family (defocus / anisotropic / motion, optionally + noise) and pure noise.
    degradation_type: str = "allinone"  # 'allinone' | 'blur' | 'noise' | 'mask' | 'downsample' | 'mixed'
    allinone_kinds: Tuple[str, ...] = ("blur", "noise")  # add 'downsample' / 'mask' for more degradations
    allinone_probs: Tuple[float, ...] = (0.75, 0.25)
    num_timesteps: int = 1000  # continuous time is used; T only scales embeddings / reports
    schedule_type: str = "log"  # 'linear' | 'cosine' | 'sqrt' | 'log'
    min_sigma: float = 0.3  # shape parameter of the 'log' schedule (sigma(0)=0 always)
    max_sigma: float = 30.0  # RMS blur radius (pixels) at tau = 1 (moment-matched for every blur shape)
    noise_max: float = 0.4  # pure-noise std at tau = 1 (images in [-1, 1]; 0.4 = 51/255)
    min_downsample_scale: float = 0.1
    field_anchors: int = 12  # heat-kernel bank size for spatially varying fields  [N1]

    # ----------------------------- Blur family + clock-tied noise  [N9, N10] -----------------------------
    blur_shape_probs: Tuple[float, float, float] = (0.35, 0.2, 0.45)  # iso (defocus; pretrained domain) | aniso | motion
    motion_max_len: float = 64.0  # longest motion streak (px); motion clocks saturate there
    aniso_min_ratio: float = 0.1  # minor/major axis ratio of anisotropic blur
    compound_noise_prob: float = 0.5  # blur samples that also carry noise n(tau) = eta * tau (vanishes at tau=0)
    compound_noise_max: float = 0.1  # max eta (0.1 = std 12.75/255 at tau = 1)

    # ----------------------------- Clock-field training  [N1] -----------------------------
    tau_sampling: str = "mixed"  # 'uniform' | 'logit_normal' | 'mixed'
    logit_mean: float = 0.0
    logit_std: float = 1.0
    field_prob: float = 0.5  # fraction of samples with a spatially varying clock
    field_spread: float = 0.45
    field_grid: Tuple[int, int] = (2, 6)  # random low-res grid used to draw smooth fields

    # ----------------------------- Clock estimator  [N1] -----------------------------
    clock_hidden: int = 32
    clock_bands: Tuple[float, ...] = (0.5, 1.0, 2.0, 4.0, 8.0)
    clock_window: int = 15
    clock_smooth_sigma: float = 6.0
    blind_clock_margin: float = 0.0  # blind clock = posterior mean - m * scale. 0: the network gets the unbiased
    #                                   estimate (0.5 under-stated real blur); caution is in the uncertainty Wiener
    blind_kind_min_prob: float = 0.7  # blind kind: blur unless the type head is this confident about another kind
    est_cond_prob_real: float = 0.5  # real pairs conditioned on the ESTIMATED clock (as at test time)
    est_cond_prob_syn: float = 0.15  # synthetic samples conditioned on the estimated clock
    blind_aniso_snap: float = 0.8  # estimated axis ratio above this -> treated as isotropic blur   [N12]
    blind_tau_unc_floor: float = 0.05  # minimum clock uncertainty of an estimated operator (damped anchoring) [N12]
    blind_anchor: str = "final"  # blind SRN anchoring: 'final' (one regularised correction) | 'every' | 'distributed'
    # Controlled sampler study with an emulated restorer and the EXACT operator (24 conditions: 2 restorer
    # qualities x 2 sensor-noise levels x iso/motion x 3 clocks). Same sampler with vs. without the Residual
    # Spectral Gate [N13]: improved +5.2 dB, SRN-every +8.0 dB, SRN-every + noise-aware +8.4 dB (mean PSNR).
    # With a small TRAINED network (8 images x 8 conditions, 20 steps): +0.75 dB mean, never worse (+0.05..+1.9 dB).
    # With a MIS-ESTIMATED clock (x0.7 / x1.3) the gate keeps the coloured mismatch residual and loses ~6-16 dB,
    # so it is used for known operators only (residual_gate='known'); blind photos keep residual annealing.
    anchor_schedule: str = "every"  # known-operator SRN anchoring: 'every' | 'final' | 'distributed'
    rn_noise_aware: bool = True  # noise-aware Wiener anchoring (gradient prior from the MAD noise estimate)
    residual_gate: str = "known"  # Residual Spectral Gate [N13] for Algorithm 2 / SRN: 'off' | 'known' (known
    #                               operator: synthetic evaluation, validation) | 'all' (also blind photos - NOT
    #                               recommended: an estimated operator leaves a coloured residual the gate keeps)
    residual_anneal_floor: float = 1e-3  # blind mode: unexplained residual (noise, kernel mismatch) is
    #                                      annealed to zero along the clock instead of being added back [N12]

    # ----------------------------- Real paired data  [N11] -----------------------------
    real_pair_prob: float = 0.5  # fraction of optimiser steps trained on real blur->sharp pairs (0 = off)
    real_val_images: int = 24  # real pairs (fixed 256 crops) validated every epoch
    real_eval_max_images: int = 10  # per real benchmark in the final evaluation (0 = all; ~30 s/image at 1280x720)
    infer_amp: bool = True  # fp16 autocast for the real benchmark at native resolution (T4; NaN-guarded)
    real_eval_max_side: int = 0  # 0 = native resolution (falls back to 768 px on out-of-memory)
    real_eval_samplers: Tuple[str, ...] = ("direct", "srn")
    real_sampler: str = "auto"  # sampler for real photos: 'auto' = the better one on the real validation pairs
    #                             (read from the checkpoint history) | 'direct' | 'improved' | 'srn'
    select_best_by: str = "real"  # 'real' (EMA PSNR on the real validation pairs) | 'synthetic'

    # ----------------------------- Optimisation -----------------------------
    batch_size: int = 3  # per GPU (value of the pretrained run; changing it changes the LR schedule length)
    grad_accum_steps: int = 1
    epochs: int = 50  # TOTAL number of epochs (a resumed checkpoint at epoch >= epochs has nothing left to train)
    extra_epochs: int = 0  # > 0: train this many epochs BEYOND the resumed checkpoint (fine-tuning)
    finetune_lr_restart: bool = True  # with extra_epochs: restart the LR schedule (warm-up + cosine)
    finetune_lr: float = 5e-5  # peak LR of the restarted schedule
    finetune_warmup_steps: int = 200  # (capped at 10% of the extra steps)
    new_extra_request: bool = False  # True: once the saved extra_epochs request is complete, start a new one
    learning_rate: float = 1e-4
    min_lr_ratio: float = 0.01
    weight_decay: float = 1e-4
    betas: Tuple[float, float] = (0.9, 0.999)
    warmup_steps: int = 1000
    grad_clip: float = 1.0
    use_amp: bool = True
    use_ema: bool = True
    ema_decay: float = 0.999
    num_workers: int = 4
    seed: int = 42
    deterministic: bool = False

    # ----------------------------- Loss weights -----------------------------
    lambda_rec: float = 1.0  # Charbonnier on x0
    lambda_unc: float = 0.05  # beta-Laplace NLL (scale head only)          [N6]
    lambda_freq: float = 0.1  # Null-Space Spectral loss                    [N5]
    lambda_cycle: float = 0.1  # re-degradation (semigroup) consistency
    lambda_rollout: float = 0.5  # Sampler-Consistent Rollout                 [N4]
    lambda_clock: float = 0.1  # clock estimator (NLL + L1 + TV)            [N1]
    lambda_type: float = 0.05  # degradation-type classification (mixed)
    lambda_perceptual: float = 0.0  # optional VGG perceptual loss (downloads weights)
    nss_gamma: float = 1.0
    nss_floor: float = 0.05
    rollout_prob: float = 0.5
    rollout_delta: Tuple[float, float] = (0.02, 0.6)
    clock_tv_weight: float = 0.05

    # ----------------------------- Sampling -----------------------------
    sampler: str = "srn"  # 'direct' | 'naive' | 'improved' | 'srn'
    sample_steps: int = 50
    min_steps: int = 8
    adaptive_steps: bool = True  # fewer steps for lightly degraded inputs
    step_rho: float = 1.5  # u_k = (1 - k/K)^rho
    rn_eta: float = 1.0  # range-null anchoring strength             [N2]
    rn_lambda: float = 2e-2  # Wiener regulariser, known clock (match it to the observation noise;
    #                          ~5e-3 only for noiseless float observations)
    rn_lambda_real: float = 5e-2  # blind mode / real photos (estimated operator, noise, JPEG)
    churn: float = 0.0  # uncertainty-gated stochasticity for restoration
    gen_churn: float = 0.3  # ... and for generation
    prior_res: int = 8  # degraded-prior thumbnail size             [N8]
    prior_max_images: int = 2048

    # ----------------------------- Logging / checkpoints -----------------------------
    val_every: int = 1
    val_max_batches: int = 50  # cap on validation batches per epoch (0 = whole validation set)
    val_taus: Tuple[float, ...] = (0.25, 0.5, 0.75)
    val_sampler_every: int = 1  # multi-step SRN sampler validation (cheap: a few val batches, every epoch)
    val_sampler_steps: int = 20
    val_sampler_batches: int = 2  # val batches for the sampler metric (was one batch)
    val_sampler_blind: bool = True  # also report the blind (estimated-clock) SRN PSNR
    viz_every: int = 200
    keep_last_k: int = 3

    # ----------------------------- Inference -----------------------------
    infer_num_images: int = 8
    eval_max_batches: int = 4
    eval_steps: int = 20  # sampler steps of the synthetic evaluation (as validation / real benchmark; 50 took ~1 h)
    eval_taus: Tuple[float, ...] = (0.2, 0.4, 0.6, 0.8)
    eval_blur_shapes: Tuple[str, ...] = ("iso", "motion")  # synthetic evaluation per blur shape
    eval_samplers: Tuple[str, ...] = ("direct", "improved", "srn")  # known operator ('naive' = Alg. 1 also available)
    eval_blind_samplers: Tuple[str, ...] = ("direct", "srn")  # estimated operator (the real-photo use case)
    strength_sweep: Tuple[float, ...] = (0.5, 0.75, 1.0, 1.25)
    generate_num: int = 8
    generate_steps: int = 100
    real_max_side: int = 1280  # real photos at native resolution up to this side (blur scale preserved)
    eval_obs_noise: float = 0.01  # sensor noise added to synthetic observations (avoids the "inverse crime")
    eval_quantize: bool = True  # 8-bit quantisation of synthetic observations
    compute_lpips: bool = True
    save_gif: bool = True

    # ----------------------------- Hardware (Kaggle GPU T4 x2) -----------------------------
    device: str = "cuda" if torch.cuda.is_available() else "cpu"
    multi_gpu: bool = True  # DDP when launched with torchrun, otherwise nn.DataParallel over every visible GPU
    batch_size_per_gpu: bool = True  # batch_size is per GPU -> global batch = batch_size * n_gpus
    amp_dtype: str = "auto"  # 'auto' (fp16 on T4 / pre-Ampere, bf16 on Ampere+) | 'fp16' | 'bf16'
    expected_gpus: int = 2  # a warning is printed if fewer GPUs are visible (Kaggle accelerator not set)
    ddp_timeout_min: int = 60  # collective timeout (rank 0 validates / checkpoints while the others wait)
    nccl_safe_mode: bool = True  # DDP on Kaggle / T4: NCCL_P2P_DISABLE=1, NCCL_IB_DISABLE=1 unless already set

    # ----------------------------- Pretrained-model safety / Kaggle sessions -----------------------------
    resume_from: str = "auto"  # 'auto': checkpoint_dir, then the newest checkpoint_latest/best.pt under /kaggle/input
    #                            (e.g. a previous notebook version attached as input) | explicit file or folder | ''
    #                            An explicit path skips the search below entirely (fastest start-up).
    resume_search_roots: Tuple[str, ...] = ("/kaggle/input", "/kaggle/working")  # where resume_from='auto' looks
    resume_search_depth: int = 6  # folder levels below each root (notebook outputs / models sit 1-5 levels deep)
    resume_search_timeout_s: float = 120.0  # the search stops after this long and uses what it found
    require_pretrained: bool = False  # True: stop with an error when no checkpoint is found. False: train from scratch
    #                                   behind a loud banner that says where it looked (a found checkpoint that does
    #                                   not match the architecture always stops the run - it is never replaced)
    protect_pretrained: bool = True  # one-time copy of the start-up checkpoints to <checkpoint_dir>/pretrained_backup
    checkpoint_every_min: float = 30.0  # mid-epoch checkpoint (a Kaggle session can end without warning); 0 = off
    time_budget_hours: float = -1.0  # stop training cleanly after this long: -1 = auto (11 h on Kaggle, else off), 0 = off
    run_inference: str = "when_done"  # 'when_done' (all epochs trained) | 'always' | 'never'

    def __post_init__(self):
        for path in [self.output_dir, self.checkpoint_dir, self.visualization_dir]:
            os.makedirs(path, exist_ok=True)
        if self.degradation_type not in KINDS + ("mixed", "allinone"):
            raise ValueError(f"Unknown degradation_type: {self.degradation_type}")
        bad = [k for k in self.allinone_kinds if k not in KINDS]
        if bad or len(self.allinone_kinds) != len(self.allinone_probs):
            raise ValueError(f"allinone_kinds {self.allinone_kinds} / allinone_probs {self.allinone_probs} are inconsistent")
        if self.select_best_by not in ("real", "synthetic"):
            raise ValueError(f"Unknown select_best_by: {self.select_best_by}")
        # The Swin bottleneck runs at `num_features` channels -> must be divisible by heads.
        if self.num_features % self.num_heads != 0:
            self.num_features = int(math.ceil(self.num_features / self.num_heads) * self.num_heads)
            print(f"Adjusted num_features to {self.num_features} (divisible by num_heads={self.num_heads})")
        if self.image_size[0] % 8 or self.image_size[1] % 8:
            raise ValueError("image_size must be divisible by 8 (three stride-2 stages).")
        if self.run_inference not in ("when_done", "always", "never"):
            raise ValueError(f"Unknown run_inference: {self.run_inference}")
        # String options used to fall through to another code path when misspelled (e.g. an unknown sampler ran
        # Algorithm 2, an unknown anchor schedule anchored at every step) -> fail at construction instead.
        samplers = ("direct", "naive", "improved", "srn")
        choices = {"schedule_type": ("linear", "cosine", "sqrt", "log"), "tau_sampling": ("uniform", "logit_normal", "mixed"),
                   "sampler": samplers, "real_sampler": samplers + ("auto",), "residual_gate": ("off", "known", "all"),
                   "anchor_schedule": ("every", "final", "distributed"), "blind_anchor": ("every", "final", "distributed"),
                   "amp_dtype": ("auto", "fp16", "bf16")}
        for name, ok in choices.items():
            if getattr(self, name) not in ok:
                raise ValueError(f"Unknown {name}={getattr(self, name)!r}; expected one of {ok}")
        for name in ("eval_samplers", "eval_blind_samplers", "real_eval_samplers"):
            bad = [s for s in getattr(self, name) if s not in samplers]
            if bad:
                raise ValueError(f"{name} contains unknown samplers {bad}; expected {samplers}")
        bad = [s for s in self.eval_blur_shapes if s not in BLUR_SHAPES]
        if bad or len(self.blur_shape_probs) != len(BLUR_SHAPES) or sum(self.blur_shape_probs) <= 0:
            raise ValueError(f"eval_blur_shapes {self.eval_blur_shapes} / blur_shape_probs {self.blur_shape_probs} are invalid")
        lo, hi = self.rollout_delta
        if not 0 < lo <= hi <= 1:
            raise ValueError(f"rollout_delta {self.rollout_delta} must satisfy 0 < lo <= hi <= 1 (log-uniform sampling)")
        if self.real_subset_balance not in ("equal", "sqrt", "size"):
            raise ValueError(f"Unknown real_subset_balance={self.real_subset_balance!r}; expected 'equal' | 'sqrt' | 'size'")
        if self.grad_accum_steps < 1 or self.batch_size < 1:
            raise ValueError("batch_size and grad_accum_steps must be >= 1")

    # ---- (de)serialisation -------------------------------------------------------------
    def to_dict(self) -> Dict[str, Any]:
        return asdict(self)

    def save(self, path: Union[str, Path]):
        with open(path, "w") as f:
            json.dump(self.to_dict(), f, indent=4)

    @classmethod
    def from_dict(cls, data: Dict[str, Any], **overrides) -> "Config":
        valid = {f.name: f for f in fields(cls)}
        kwargs = {}
        for k, v in {**data, **overrides}.items():
            if k not in valid:
                continue
            default = cls.__dataclass_fields__[k].default
            if isinstance(default, tuple) and isinstance(v, list):
                v = tuple(v)
            kwargs[k] = v
        return cls(**kwargs)

    @classmethod
    def load(cls, path: Union[str, Path], **overrides) -> "Config":
        with open(path, "r") as f:
            return cls.from_dict(json.load(f), **overrides)


# =======================================================================================
# SECTION 2: UTILITIES
# =======================================================================================


def seed_everything(seed: int, deterministic: bool = False):
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed_all(seed)
    torch.backends.cudnn.deterministic = deterministic
    torch.backends.cudnn.benchmark = not deterministic


def to_2tuple(x):
    """Convert input to a tuple of length 2."""
    if isinstance(x, (tuple, list)) and len(x) == 2:
        return tuple(x)
    return (x, x)


def ndgrid(*tensors):
    """Create n-dimensional grid."""
    return torch.meshgrid(*tensors, indexing="ij")


def num_groups(channels: int, max_groups: int = 8) -> int:
    g = min(max_groups, channels)
    while channels % g:
        g -= 1
    return g


def to01(x: torch.Tensor) -> torch.Tensor:
    """[-1, 1] -> [0, 1]."""
    return (x.clamp(-1, 1) + 1) / 2


def count_parameters(module: nn.Module) -> int:
    return sum(p.numel() for p in module.parameters())


def autocast_off(device_type: str):
    """FFTs are run in fp32 (half-precision FFT is inaccurate and size-restricted)."""
    return torch.autocast(device_type=device_type, enabled=False)


def _rand(shape, device, generator=None):
    if generator is None:
        return torch.rand(*shape, device=device)
    return torch.rand(*shape, generator=generator).to(device)


def _randn(shape, device, generator=None):
    if generator is None:
        return torch.randn(*shape, device=device)
    return torch.randn(*shape, generator=generator).to(device)


def colorize(t: Union[torch.Tensor, np.ndarray], cmap: str = "magma",
             vmin: Optional[float] = None, vmax: Optional[float] = None) -> torch.Tensor:
    """(H, W) map -> (3, H, W) RGB tensor in [0, 1] using a matplotlib colormap."""
    a = t.detach().float().cpu().numpy() if isinstance(t, torch.Tensor) else np.asarray(t, dtype=np.float32)
    a = np.squeeze(a)
    lo = float(np.nanmin(a)) if vmin is None else vmin
    hi = float(np.nanmax(a)) if vmax is None else vmax
    a = np.clip((a - lo) / max(hi - lo, 1e-8), 0, 1)
    try:  # matplotlib >= 3.5 (cm.get_cmap was removed in 3.9)
        cmap_fn = matplotlib.colormaps[cmap]
    except AttributeError:
        cmap_fn = cm.get_cmap(cmap)
    rgb = cmap_fn(a)[..., :3]
    return torch.from_numpy(rgb).permute(2, 0, 1).float()


def tensor_to_pil(x: torch.Tensor) -> Image.Image:
    """(3, H, W) or (1, 3, H, W) in [-1, 1] -> PIL."""
    if x.dim() == 4:
        x = x[0]
    arr = (to01(x).permute(1, 2, 0).cpu().numpy() * 255).round().astype(np.uint8)
    return Image.fromarray(arr)


def save_gif(frames: Sequence[torch.Tensor], path: Union[str, Path], duration: int = 80):
    """frames: (3, H, W) tensors in [0, 1]."""
    imgs = [Image.fromarray((f.clamp(0, 1).permute(1, 2, 0).cpu().numpy() * 255).astype(np.uint8)) for f in frames]
    if imgs:
        imgs[0].save(path, save_all=True, append_images=imgs[1:], duration=duration, loop=0)


def save_json(obj: Any, path: Union[str, Path]):
    def _default(o):
        if isinstance(o, (np.floating, np.integer)):
            return o.item()
        if isinstance(o, torch.Tensor):
            return o.detach().cpu().tolist()
        if isinstance(o, Path):
            return str(o)
        return str(o)

    with open(path, "w") as f:
        json.dump(obj, f, indent=2, default=_default)


CHECKPOINT_NAMES: Tuple[str, ...] = ("checkpoint_latest.pt", "checkpoint_best.pt", "final_model.pt")
WEIGHT_EXTENSIONS: Tuple[str, ...] = (".pt", ".pth", ".ckpt")


def _checkpoint_rank(name: str) -> Optional[int]:
    """Priority of a checkpoint file name: latest, best, checkpoint_epoch_*, final_model (None = not a checkpoint)."""
    if name == "checkpoint_latest.pt":
        return 0
    if name == "checkpoint_best.pt":
        return 1
    if name.startswith("checkpoint_epoch_") and name.endswith(".pt"):
        return 2
    if name == "final_model.pt":
        return 3
    return None


def _dataset_trees(paths: Sequence[Union[str, Path]], roots: Sequence[str]) -> Tuple[set, set]:
    """Dataset root folders (and their names) of the configured DATA folders: <root>/<slug> or
    <root>/datasets/<owner>/<slug> (both Kaggle input layouts). The same dataset is often visible under both
    layouts, so its name marks an alias wherever it appears near the top."""
    trees, slugs = set(), set()
    for p in paths:
        if not p:
            continue
        ap = os.path.abspath(str(p))
        for r in roots:
            if ap.startswith(r.rstrip(os.sep) + os.sep):
                parts = Path(ap).relative_to(r).parts
                k = 3 if (parts and parts[0] == "datasets" and len(parts) >= 3) else 1
                if len(parts) >= k:
                    trees.add(os.path.join(r, *parts[:k]))
                    if len(parts[k - 1]) >= 5:
                        slugs.add(parts[k - 1])
    return trees, slugs


def find_checkpoints(roots: Sequence[Union[str, Path]], max_depth: int = 6, timeout_s: float = 120.0,
                     skip: Sequence[Union[str, Path]] = (), data_dirs: Sequence[Union[str, Path]] = (),
                     max_images_per_dir: int = 64, verbose: bool = True) -> Tuple[List[Path], List[Path]]:
    """
    Bounded, shallow-first search for checkpoints under `roots` (e.g. /kaggle/input, /kaggle/working).

    The first version ran Path('/kaggle/input').rglob(name) once per file name, i.e. it read every file of every
    attached dataset (ImageNet-10k, Unsplash, all of DBlur, ...) on a network-backed mount and looked frozen after
    "Creating trainer ...". This search
      * never enters the exact data / output folders (`skip`), never descends into folders full of images (the
        checkpoint names are still probed there, so a checkpoint saved next to images is not missed),
      * visits folders in three tiers: (0) everything else - notebook outputs, models, uploads; (1) the
        '<root>/datasets/...' subtree; (2) the dataset trees of the configured data folders (and aliases of them),
        only their top two levels, and not at all once a checkpoint was found,
      * stops at `max_depth` levels and after `timeout_s` seconds with what it found, follows symlinks once.
    Returns (checkpoints, other weight files): checkpoints = checkpoint_latest / best / epoch_* / final_model,
    ordered by that priority and newest first; other weight files = *.pt / *.pth / *.ckpt under other names
    (tried last, and only if their tensors match the model exactly).
    """
    skip_set = set()
    for s in skip:
        if s:
            skip_set.add(os.path.normpath(os.path.abspath(str(s))))
            skip_set.add(os.path.realpath(str(s)))
    roots = [os.path.abspath(str(r)) for r in roots if r and os.path.isdir(str(r))]
    trees, slugs = _dataset_trees(data_dirs, roots)
    t0 = time.time()
    tiers: List[deque] = [deque(), deque(), deque()]  # items: (folder, depth, depth at which tier 2 was entered)
    for r in roots:
        tiers[0].append((r, 0, -1))
    seen = {os.path.realpath(r) for r in roots}
    found: List[Path] = []
    weights: List[Path] = []
    n_dirs, timed_out, skipped_tier2 = 0, False, 0

    def tier_of(path: str, name: str, depth: int, parent_tier: int) -> int:
        if parent_tier == 2 or os.path.normpath(path) in trees or (depth <= 3 and name in slugs):
            return 2
        if parent_tier == 1 or (depth == 1 and name == "datasets"):
            return 1
        return 0

    while True:
        t = next((i for i in range(3) if tiers[i]), None)
        if t is None:
            break
        if t == 2 and found:  # a checkpoint exists outside the data trees -> do not crawl the datasets
            skipped_tier2 = len(tiers[2])
            break
        if time.time() - t0 > timeout_s:
            timed_out = True
            break
        d, depth, t2_depth = tiers[t].popleft()
        subdirs, n_img = [], 0
        try:
            with os.scandir(d) as it:  # read lazily: an image folder is abandoned after a few entries
                for e in it:
                    try:
                        name = e.name
                        if _checkpoint_rank(name) is not None:
                            found.append(Path(e.path))
                        elif name.lower().endswith(IMAGE_EXTENSIONS):
                            n_img += 1
                            if n_img >= max_images_per_dir:
                                break
                        elif name.lower().endswith(WEIGHT_EXTENSIONS):
                            if len(weights) < 50:
                                weights.append(Path(e.path))
                        elif e.is_dir():
                            subdirs.append(e)
                    except OSError:
                        continue
        except OSError:
            continue
        n_dirs += 1
        if n_img >= max_images_per_dir:  # image folder: never descend, but probe the checkpoint names directly
            for name in CHECKPOINT_NAMES:
                q = os.path.join(d, name)
                if os.path.isfile(q):
                    found.append(Path(q))
            continue
        if depth >= max_depth or (t == 2 and depth - t2_depth >= 2):  # data-set trees: top 2 levels only
            continue
        for e in sorted(subdirs, key=lambda e: e.name):
            if e.name.startswith(".") or e.name in ("pretrained_backup", "pretrained_backup.partial", "__pycache__"):
                continue
            if os.path.normpath(e.path) in skip_set:
                continue
            if e.is_symlink():
                real = os.path.realpath(e.path)
                if real in seen or real in skip_set:
                    continue
                seen.add(real)
            child_tier = tier_of(e.path, e.name, depth + 1, t)
            tiers[child_tier].append((e.path, depth + 1, t2_depth if t == 2 else (depth + 1 if child_tier == 2 else -1)))

    def _mtime(p: Path) -> float:
        try:
            return p.stat().st_mtime
        except OSError:
            return 0.0

    found = sorted(set(found), key=lambda p: (_checkpoint_rank(p.name), -_mtime(p)))
    weights = sorted(set(weights), key=lambda p: -_mtime(p))
    if verbose:
        print(f"  searched {n_dirs} folders in {time.time() - t0:.1f} s"
              + (f" - stopped at the {timeout_s:g} s limit (set Config.resume_from to the checkpoint path to skip the "
                 f"search)" if timed_out else "")
              + (f" - {skipped_tier2} data-set folders not searched (a checkpoint was found)" if skipped_tier2 else "")
              + f": {len(found)} checkpoint(s), {len(weights)} other weight file(s)")
    return found, weights


def is_multi_kind(cfg: Config) -> bool:
    """Several degradation kinds are trained -> the clock estimator's type head decides in blind mode."""
    return cfg.degradation_type in ("mixed", "allinone")


def allowed_kinds(cfg: Config) -> List[int]:
    if cfg.degradation_type == "mixed":
        return list(range(len(KINDS)))
    if cfg.degradation_type == "allinone":
        return [KINDS.index(k) for k in cfg.allinone_kinds]
    return [KINDS.index(cfg.degradation_type)]


def realistic_observation(y: torch.Tensor, noise: float, quantize: bool,
                          generator: Optional[torch.Generator] = None) -> torch.Tensor:
    """Sensor noise + 8-bit quantisation (same protocol as Inferencer._observe). Without it, an exact,
    noiseless, known operator is inverted almost perfectly by the range-null step (the 'inverse
    crime'): the validation sampler reported ~53 dB for lightly blurred images."""
    if noise > 0:
        y = y + noise * _randn(tuple(y.shape), y.device, generator)
    if quantize:
        y = torch.round(to01(y) * 255.0) / 255.0 * 2 - 1
    return y.clamp(-1, 1)


class EpochSampler(Sampler):
    """
    Seeded per-epoch permutation (sharded like DistributedSampler under DDP) that can skip the
    samples an interrupted epoch already consumed -> a mid-epoch checkpoint resumes *exactly*
    where it stopped (no image seen twice, none skipped), even in a new Kaggle session.
    """

    def __init__(self, n: int, seed: int, rank: int = 0, world_size: int = 1):
        self.n, self.seed, self.rank, self.world = n, seed, rank, world_size
        self.num_samples = int(math.ceil(n / world_size))
        self.epoch, self.skip = 0, 0

    def set_epoch(self, epoch: int, skip_samples: int = 0):
        self.epoch, self.skip = int(epoch), max(0, int(skip_samples))

    def __iter__(self):
        g = torch.Generator().manual_seed(self.seed + 7919 * self.epoch)
        idx = torch.randperm(self.n, generator=g).tolist()
        total = self.num_samples * self.world
        idx = (idx * (1 + total // max(len(idx), 1)))[:total]  # pad like DistributedSampler
        return iter(idx[self.rank:total:self.world][self.skip:])

    def __len__(self):
        return max(0, self.num_samples - self.skip)


class BalancedEpochSampler(Sampler):
    """
    Seeded sampler over a ConcatDataset of real pair sets that balances the requested DATASETS (groups) instead of
    letting the largest one dominate (TextOCR alone can be larger than GoPro + HIDE + RealBlur together). Every
    draw picks a group with probability ~ its weight ('equal' | 'sqrt' | 'size' of the group), a member subset
    proportionally to its size ('RealBlur' -> RealBlur_J / RealBlur_R) and an image without replacement within
    the subset until it is exhausted. One "epoch" = as many draws as there are pairs; sharded like
    DistributedSampler (identical draws on every rank, each rank takes its slice).
    """

    def __init__(self, sizes: Sequence[int], groups: Sequence[str], mode: str = "equal", seed: int = 0,
                 rank: int = 0, world_size: int = 1):
        self.sizes = [int(s) for s in sizes]
        self.offsets = [int(o) for o in np.cumsum([0] + self.sizes[:-1])]
        self.seed, self.rank, self.world = seed, rank, world_size
        self.num_samples = int(math.ceil(sum(self.sizes) / world_size))
        self.epoch = 0
        group_size: Dict[str, int] = {}
        for s, g in zip(self.sizes, groups):
            group_size[g] = group_size.get(g, 0) + s
        weight = {g: 1.0 if mode == "equal" else (math.sqrt(n) if mode == "sqrt" else float(n)) for g, n in group_size.items()}
        total = sum(weight.values())
        self.probs = torch.tensor([weight[g] / total * s / max(group_size[g], 1) for s, g in zip(self.sizes, groups)],
                                  dtype=torch.float64)

    def set_epoch(self, epoch: int, skip_samples: int = 0):
        self.epoch = int(epoch)

    def __iter__(self):
        g = torch.Generator().manual_seed(self.seed + 7919 * self.epoch)
        total = self.num_samples * self.world
        which = torch.multinomial(self.probs, total, replacement=True, generator=g).tolist()
        perms: Dict[int, List[int]] = {}
        ptr: Dict[int, int] = {}
        idx = []
        for k in which:
            if ptr.get(k, self.sizes[k]) >= self.sizes[k]:  # (re)shuffle this subset when it is exhausted
                perms[k] = torch.randperm(self.sizes[k], generator=g).tolist()
                ptr[k] = 0
            idx.append(self.offsets[k] + perms[k][ptr[k]])
            ptr[k] += 1
        return iter(idx[self.rank:total:self.world])

    def __len__(self):
        return self.num_samples


# ---------------------------------- multi-GPU (Kaggle T4 x2) ----------------------------------


def dist_is_on() -> bool:
    return dist.is_available() and dist.is_initialized()


def get_rank() -> int:
    return dist.get_rank() if dist_is_on() else 0


def get_world_size() -> int:
    return dist.get_world_size() if dist_is_on() else 1


def is_main_process() -> bool:
    return get_rank() == 0


def barrier():
    if dist_is_on() and get_world_size() > 1:
        if dist.get_backend() == "nccl":
            dist.barrier(device_ids=[torch.cuda.current_device()])
        else:
            dist.barrier()


def unwrap(module: nn.Module) -> nn.Module:
    """Strips nn.DataParallel / DistributedDataParallel."""
    return module.module if isinstance(module, (nn.DataParallel, DDP)) else module


def _silence_non_main_ranks():
    """Only rank 0 prints (use print(..., force=True) to print from every rank)."""
    import builtins

    builtin_print = builtins.print

    def _print(*args, **kwargs):
        force = kwargs.pop("force", False)
        if force or is_main_process():
            builtin_print(*args, **kwargs)

    builtins.print = _print


def setup_distributed(cfg: Config) -> bool:
    """Initialises DDP when the script was launched with torchrun (WORLD_SIZE > 1)."""
    if dist_is_on():
        return get_world_size() > 1
    world = int(os.environ.get("WORLD_SIZE", "1"))
    if world <= 1:
        return False
    if not cfg.multi_gpu:
        # Launched by torchrun but multi-GPU disabled: every process would train the same model and write the same
        # checkpoint files concurrently. main() lets rank 0 run alone and the other processes exit.
        return False
    local_rank = int(os.environ.get("LOCAL_RANK", "0"))
    if torch.cuda.is_available():
        torch.cuda.set_device(local_rank)  # before any CUDA work: keeps rank 1 (and its pin-memory thread) off cuda:0
        backend = "nccl"
        cfg.device = f"cuda:{local_rank}"
        if cfg.nccl_safe_mode:
            # NCCL peer-to-peer between the two PCIe T4s of a Kaggle VM can block forever in the first collective,
            # which is issued inside the DDP constructor -> the run froze right after "Creating trainer ...".
            # Shared-memory transport is what those GPUs use anyway (no NVLink). User settings are kept.
            name = torch.cuda.get_device_name(local_rank)
            if Path("/kaggle").is_dir() or "T4" in name:
                os.environ.setdefault("NCCL_P2P_DISABLE", "1")
                os.environ.setdefault("NCCL_IB_DISABLE", "1")
    else:  # CPU fallback (smoke tests)
        backend = "gloo"
        cfg.device = "cpu"
    dist.init_process_group(backend=backend, timeout=timedelta(minutes=cfg.ddp_timeout_min))
    _silence_non_main_ranks()
    return True


def cleanup_distributed():
    if dist_is_on():
        dist.destroy_process_group()


def parallel_mode(cfg: Config) -> str:
    """'ddp' (torchrun), 'dp' (DataParallel, >1 visible GPU), 'single' (one GPU) or 'cpu'."""
    if dist_is_on() and get_world_size() > 1:
        return "ddp"
    if torch.device(cfg.device).type != "cuda":
        return "cpu"
    if cfg.multi_gpu and torch.cuda.device_count() > 1:
        return "dp"
    return "single"


def select_amp_dtype(device: torch.device, pref: str = "auto") -> torch.dtype:
    """fp16 on T4 (sm_75: fp16 tensor cores, no native bf16), bf16 on Ampere and newer.
    torch.cuda.is_bf16_supported() is *not* used: it returns True on T4 through emulation."""
    if pref == "fp16":
        return torch.float16
    if pref == "bf16":
        return torch.bfloat16
    if device.type == "cuda" and torch.cuda.get_device_capability(device)[0] >= 8:
        return torch.bfloat16
    return torch.float16


def describe_hardware(cfg: Config) -> str:
    mode = parallel_mode(cfg)
    lines = []
    if torch.cuda.is_available():
        n = torch.cuda.device_count()
        for i in range(n):
            p = torch.cuda.get_device_properties(i)
            lines.append(f"  cuda:{i}  {p.name}  sm_{p.major}{p.minor}  {p.total_memory / 1024 ** 3:.1f} GiB")
        if n < cfg.expected_gpus:
            lines.append(f"  WARNING: {n} GPU(s) visible, {cfg.expected_gpus} expected. On Kaggle select "
                         f"Settings -> Accelerator -> 'GPU T4 x2'.")
    else:
        lines.append("  WARNING: no CUDA GPU visible - running on CPU. On Kaggle select Settings -> Accelerator -> 'GPU T4 x2'.")
    desc = {"ddp": f"DistributedDataParallel ({get_world_size()} processes, one GPU each)",
            "dp": f"nn.DataParallel over cuda:0..{torch.cuda.device_count() - 1}",
            "single": "single GPU", "cpu": "CPU"}[mode]
    lines.append(f"  training mode: {desc}")
    return "\n".join(lines)


# =======================================================================================
# SECTION 3: PHYSICS - EXACT HEAT OPERATOR AND COLD DEGRADATIONS
# =======================================================================================


class HeatKernel:
    """
    Exact isotropic heat-kernel (Gaussian) blur with reflective (Neumann) boundaries.   [N7]

    The image is even-symmetrically extended to 2H x 2W and filtered in the Fourier domain
    with the analytic transfer function K_sigma(w) = exp(-sigma^2 |w|^2 / 2). This is exactly
    the DCT-II diagonalisation of the heat equation used in inverse heat dissipation, so it is
    valid for *any* continuous sigma (no kernel truncation, no dark zero-padded borders)
    and it is cheap even for sigma = 30 px.
    """

    _cache: Dict[tuple, Any] = {}
    _cache_max = 64  # real photos come in many sizes: the cache used to grow without bound (GPU memory)
    _cache_lock = threading.Lock()  # nn.DataParallel runs its replicas in threads

    @staticmethod
    def _cached(key: tuple, make):
        with HeatKernel._cache_lock:
            value = HeatKernel._cache.get(key)
            if value is None:
                if len(HeatKernel._cache) >= HeatKernel._cache_max:  # drop the oldest entry
                    HeatKernel._cache.pop(next(iter(HeatKernel._cache)))
                value = HeatKernel._cache[key] = make()
            return value

    @staticmethod
    def omega_sq(h: int, w: int, device) -> torch.Tensor:
        def make():
            wy = torch.fft.fftfreq(2 * h, device=device) * (2 * math.pi)
            wx = torch.fft.rfftfreq(2 * w, device=device) * (2 * math.pi)
            return (wy[:, None] ** 2 + wx[None, :] ** 2).float()

        return HeatKernel._cached((h, w, str(device)), make)

    @staticmethod
    def spectrum(x: torch.Tensor) -> torch.Tensor:
        x = x.float()
        x = torch.cat([x, x.flip(-1)], dim=-1)
        x = torch.cat([x, x.flip(-2)], dim=-2)
        return torch.fft.rfft2(x)

    @staticmethod
    def inverse(X: torch.Tensor, h: int, w: int) -> torch.Tensor:
        return torch.fft.irfft2(X, s=(2 * h, 2 * w))[..., :h, :w]

    @staticmethod
    def transfer(sigma, h: int, w: int, device) -> torch.Tensor:
        """sigma: scalar or (B,) -> (B, 1, 2h, w+1) real transfer function."""
        sigma = torch.as_tensor(sigma, device=device, dtype=torch.float32).reshape(-1, 1, 1, 1)
        return torch.exp(-0.5 * sigma ** 2 * HeatKernel.omega_sq(h, w, device))

    @staticmethod
    def blur(x: torch.Tensor, sigma) -> torch.Tensor:
        with autocast_off(x.device.type):
            h, w = x.shape[-2:]
            out = HeatKernel.inverse(HeatKernel.spectrum(x) * HeatKernel.transfer(sigma, h, w, x.device), h, w)
        return out

    @staticmethod
    def freq_xy(h: int, w: int, device) -> Tuple[torch.Tensor, torch.Tensor]:
        """(wy (2h, 1), wx (1, w+1)) angular frequencies of the even-extended rfft grid."""
        def make():
            wy = (torch.fft.fftfreq(2 * h, device=device) * (2 * math.pi)).float()[:, None]
            wx = (torch.fft.rfftfreq(2 * w, device=device) * (2 * math.pi)).float()[None, :]
            return wy, wx

        return HeatKernel._cached((h, w, str(device), "xy"), make)

    @staticmethod
    def white_floor(h: int, w: int, device) -> torch.Tensor:
        """E|spectrum(n)|^2 of unit white noise on the even-extended rfft grid, (2h, w+1).
        Per axis of length N: 2N (1 + [k = 0] - [k = N]) (the Nyquist row is identically zero)."""
        def make():
            ky = torch.arange(2 * h, device=device)
            kx = torch.arange(w + 1, device=device)
            a = 2 * h * (1.0 + (ky == 0).float() - (ky == h).float())
            b = 2 * w * (1.0 + (kx == 0).float() - (kx == w).float())
            return (a[:, None] * b[None, :]).float()

        return HeatKernel._cached((h, w, str(device), "floor"), make)


def residual_spectral_gate(r: torch.Tensor, win: int = 5) -> torch.Tensor:
    """Residual Spectral Gate [N13]: the part of a residual (B, C, H, W) that is NOT white noise.
    G(w) = max(0, 1 - s^2 / P(w)), P = locally averaged (win x win, channel-mean) power of the DCT
    spectrum normalised by the white-noise floor, s^2 = MAD noise variance of the residual itself."""
    with autocast_off(r.device.type):
        r = r.float()
        h, w = r.shape[-2:]
        s2 = estimate_noise_sigma(r).pow(2).view(-1, 1, 1, 1)
        R = HeatKernel.spectrum(r)
        floor = HeatKernel.white_floor(h, w, r.device)
        P = (R.real.pow(2) + R.imag.pow(2)).mean(1, keepdim=True) / floor.clamp_min(1.0)
        p = win // 2
        if p > 0:  # the ky axis is periodic, kx (rfft half-axis) is not
            P = F.pad(P, (0, 0, p, p), mode="circular")
            P = F.pad(P, (p, p, 0, 0), mode="replicate")
            P = F.avg_pool2d(P, win, stride=1)
        G = (1.0 - s2 / P.clamp_min(1e-12)).clamp(0, 1)
        return HeatKernel.inverse(R * G, h, w)


# ------------------------- spectral moment analysis (parameter-free)  [N11, N12] -------------------------


def _hann_power(x: torch.Tensor) -> torch.Tensor:
    """Power spectrum |FFT(hann * luminance)|^2, (B, H, W)."""
    lum = x.float().mean(1)
    H, W = lum.shape[-2:]
    win = torch.hann_window(H, device=x.device)[:, None] * torch.hann_window(W, device=x.device)[None, :]
    lum = (lum - lum.mean((-2, -1), keepdim=True)) * win
    return torch.fft.fft2(lum).abs() ** 2


def _polar(H: int, W: int, device) -> Tuple[torch.Tensor, torch.Tensor]:
    wy = torch.fft.fftfreq(H, device=device) * (2 * math.pi)
    wx = torch.fft.fftfreq(W, device=device) * (2 * math.pi)
    WY, WX = torch.meshgrid(wy, wx, indexing="ij")
    return torch.sqrt(WY ** 2 + WX ** 2), torch.remainder(torch.atan2(WY, WX), math.pi)


def directional_decay(power: torch.Tensor, band: torch.Tensor, n_ang: int = 24, n_rad: int = 8,
                      reference: Optional[torch.Tensor] = None) -> Tuple[torch.Tensor, torch.Tensor]:
    """
    Decay rate s(phi) = -d log E / d(|w|^2) of the sector-averaged power in n_ang orientation sectors,
    fitted over n_rad radial bins inside band = (B, 2) [r_min, r_max] (rad/px). Under a blur with
    covariance S, log|K(w)|^2 ~ -w^T S w, so s(phi) = u^T S u (+ an isotropic content term). With a
    `reference` (the sharp image of a pair) the content cancels exactly: s(phi) = u^T S u.
    Averaging the *power* inside a sector before the log makes the fit robust to the spectral zeros
    of motion blur. Returns s (B, n_ang) and the sector angles (n_ang,).
    """
    B, H, W = power.shape
    r, phi = _polar(H, W, power.device)
    a_idx = (phi / math.pi * n_ang).long().clamp(max=n_ang - 1).flatten()
    r2 = r.flatten() ** 2
    lo, hi = band[:, 0:1] ** 2, band[:, 1:2] ** 2  # (B, 1)
    rb = ((r2[None] - lo) / (hi - lo).clamp_min(1e-8) * n_rad).floor()  # (B, HW)
    inside = (rb >= 0) & (rb < n_rad)
    bins = (a_idx[None] * n_rad + rb.clamp(0, n_rad - 1).long())  # (B, HW)
    nb = n_ang * n_rad

    def sector_log(p):
        s = torch.zeros(B, nb, device=p.device).scatter_add_(1, bins, p.flatten(1) * inside)
        c = torch.zeros(B, nb, device=p.device).scatter_add_(1, bins, inside.float())
        return torch.log(s / c.clamp_min(1) + 1e-12).view(B, n_ang, n_rad), (c > 0).view(B, n_ang, n_rad)

    logE, ok = sector_log(power)
    if reference is not None:
        logR, ok2 = sector_log(reference)
        logE, ok = logE - logR, ok & ok2
    x = (torch.arange(n_rad, device=power.device).float() + 0.5) / n_rad
    x = lo + (hi - lo) * x[None]  # (B, n_rad) bin centres in |w|^2
    x = x[:, None, :].expand(B, n_ang, n_rad)
    wgt = ok.float()
    n = wgt.sum(-1).clamp_min(1)
    mx = (wgt * x).sum(-1) / n
    my = (wgt * logE).sum(-1) / n
    cov = (wgt * (x - mx[..., None]) * (logE - my[..., None])).sum(-1)
    var = (wgt * (x - mx[..., None]) ** 2).sum(-1).clamp_min(1e-12)
    centres = (torch.arange(n_ang, device=power.device).float() + 0.5) / n_ang * math.pi
    return -cov / var, centres


def orientation_from_decay(s: torch.Tensor, centres: torch.Tensor) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """s(phi) = m + dev * cos(2 (phi - theta)): mean m (= trace(S)/2 + content), deviator amplitude
    dev = (l1 - l2)/2 and the major-axis (blur / motion) direction theta."""
    m = s.mean(-1)
    A = 2 * (s * torch.cos(2 * centres)).mean(-1)
    Bc = 2 * (s * torch.sin(2 * centres)).mean(-1)
    theta = torch.remainder(0.5 * torch.atan2(Bc, A), math.pi)
    return m, torch.sqrt(A ** 2 + Bc ** 2), theta


def estimate_noise_sigma(y: torch.Tensor) -> torch.Tensor:
    """Robust (MAD) per-channel noise std from the finest diagonal Haar band (Donoho), (B,)."""
    x = y.float()
    hh = (x[..., :-1:2, :-1:2] - x[..., 1::2, :-1:2] - x[..., :-1:2, 1::2] + x[..., 1::2, 1::2]) / 2
    return hh.flatten(1).abs().median(1).values / 0.6745


class ColdDegradation(nn.Module):
    """
    Deterministic degradation operators D(x, tau) with a *continuous* clock tau in [0, 1],
    either a scalar per image or a per-pixel clock field tau(x) (B, 1, H, W).          [N1]

        blur        moment-matched blur family                                      [N9]
                    iso    : exact Neumann heat dissipation (defocus), sigma(tau) from the schedule
                    aniso  : anisotropic heat kernel, covariance R(theta) diag(s1^2, s2^2) R^T
                    motion : linear motion streak (box of length L along theta), K = sinc(L w.d / 2)
                    all with trace(Cov)/2 = sigma(tau)^2, so tau means the same RMS blur radius for
                    every shape; + clock-tied noise eta * tau * eps that vanishes at tau = 0   [N10]
        noise       x + n(tau) * eps     (eps is part of the per-sample state)
        mask        x * [rank(x) >= tau] (a fixed rank field -> nested masks, as Algorithm 2 needs)
        downsample  area-down / bilinear-up with scale s(tau)

    Spatially varying fields use exact per-pixel formulas (noise, mask) or a bank of anchor
    levels interpolated per pixel (blur, downsample). Shape, direction, axis ratio and noise
    share are per-sample state (fixed along a trajectory, like the noise realisation).
    """

    def __init__(self, cfg: Config):
        super().__init__()
        self.schedule_type = cfg.schedule_type
        self.min_sigma = cfg.min_sigma
        self.max_sigma = cfg.max_sigma
        self.noise_max = cfg.noise_max
        self.min_scale = cfg.min_downsample_scale
        self.n_anchors = max(2, cfg.field_anchors)
        self.register_buffer("anchors", torch.linspace(0, 1, self.n_anchors), persistent=False)
        p = torch.tensor(cfg.blur_shape_probs, dtype=torch.float32).clamp_min(0)
        self.shape_cdf = (p.cumsum(0) / p.sum().clamp_min(1e-8)).tolist()
        self.motion_max_len = float(cfg.motion_max_len)
        self.aniso_min_ratio = float(cfg.aniso_min_ratio)
        self.compound_noise_prob = float(cfg.compound_noise_prob)
        self.compound_noise_max = float(cfg.compound_noise_max)
        # clock at which a motion streak reaches motion_max_len (sqrt(24) * sigma = L): motion saturates there
        lo, hi = 0.0, 1.0
        if float(self.sigma(torch.tensor(1.0))) * math.sqrt(24) <= self.motion_max_len:
            self.motion_tau_cap = 1.0
        else:
            for _ in range(60):
                mid = 0.5 * (lo + hi)
                lo, hi = (mid, hi) if float(self.sigma(torch.tensor(mid))) * math.sqrt(24) < self.motion_max_len else (lo, mid)
            self.motion_tau_cap = 0.5 * (lo + hi)

    # ---- schedules (all exactly the identity at tau = 0) --------------------------------
    def sigma(self, tau: torch.Tensor) -> torch.Tensor:
        tau = tau.clamp(0, 1)
        if self.schedule_type == "linear":
            return self.max_sigma * tau
        if self.schedule_type == "sqrt":  # heat time (sigma^2) linear in tau
            return self.max_sigma * tau.sqrt()
        if self.schedule_type == "cosine":
            return self.max_sigma * (1 - torch.cos(0.5 * math.pi * tau))
        if self.schedule_type == "log":  # perceptually uniform, sigma(0) = 0, sigma(1) = max
            r = 1.0 + self.max_sigma / self.min_sigma
            return self.min_sigma * (torch.pow(torch.as_tensor(r, device=tau.device), tau) - 1.0)
        raise ValueError(f"Unknown schedule type: {self.schedule_type}")

    def noise_level(self, tau):
        return self.noise_max * tau.clamp(0, 1)

    def mask_ratio(self, tau):
        return tau.clamp(0, 1)

    def scale(self, tau):
        return 1.0 - tau.clamp(0, 1) * (1.0 - self.min_scale)

    # ---- per-sample deterministic randomness -------------------------------------------
    def new_state(self, x: torch.Tensor, generator=None, shape: Optional[str] = None) -> Dict[str, torch.Tensor]:
        """Noise realisation, mask order and blur-family parameters of each sample.
        shape=None draws iso/aniso/motion from blur_shape_probs; 'iso' | 'aniso' | 'motion' forces one."""
        B, C, H, W = x.shape
        dev = x.device
        st = {"noise": _randn((B, C, H, W), dev, generator), "rank": self.rank_field(B, H, W, dev, generator)}
        u = _rand((B,), dev, generator)
        if shape is None:
            sh = torch.zeros(B, dtype=torch.long, device=dev)
            for c in self.shape_cdf[:-1]:
                sh = sh + (u > c).long()
        else:
            sh = torch.full((B,), BLUR_SHAPES.index(shape), dtype=torch.long, device=dev)
        st["shape"] = sh
        st["theta"] = _rand((B,), dev, generator) * math.pi
        st["rho"] = self.aniso_min_ratio + (1 - self.aniso_min_ratio) * _rand((B,), dev, generator)
        noisy = _rand((B,), dev, generator) < self.compound_noise_prob
        st["eta"] = torch.where(noisy, self.compound_noise_max * _rand((B,), dev, generator), torch.zeros(B, device=dev))
        if shape is not None:  # a forced shape is a clean benchmark condition (no extra noise)
            st["eta"] = torch.zeros(B, device=dev)
        return st

    @staticmethod
    def blur_only(state: Dict[str, torch.Tensor]) -> Dict[str, torch.Tensor]:
        """Same operator without the clock-tied noise (range-null anchoring, noise re-estimation)."""
        st = dict(state)
        if "eta" in st:
            st["eta"] = torch.zeros_like(st["eta"])
        return st

    def effective_tau(self, tau: torch.Tensor, kind: torch.Tensor, state: Optional[Dict[str, torch.Tensor]]) -> torch.Tensor:
        """Motion streaks saturate at motion_max_len: clamp their clock (labels / conditioning stay exact)."""
        if state is None or "shape" not in state:
            return tau
        sel = (kind == BLUR) & (state["shape"] == MOTION)
        if not bool(sel.any()):
            return tau
        cap = torch.where(sel, torch.full_like(sel, self.motion_tau_cap, dtype=tau.dtype),
                          torch.ones_like(sel, dtype=tau.dtype))
        return torch.minimum(tau, cap.view(-1, *([1] * (tau.dim() - 1))))

    def blur_transfer(self, sigma: torch.Tensor, state: Optional[Dict[str, torch.Tensor]], h: int, w: int,
                      device) -> torch.Tensor:
        """Real, point-symmetric transfer functions of the blur family, (B, 1, 2h, w+1).   [N9]
        sigma: (B,) RMS blur radius. iso: exp(-s^2|w|^2/2); aniso: exp(-(s1^2 u^2 + s2^2 v^2)/2) with
        s1^2 = 2 s^2/(1+rho^2), s2 = rho s1; motion: sinc(L u / 2), L = sqrt(24) s (<= motion_max_len)."""
        sigma = torch.as_tensor(sigma, device=device, dtype=torch.float32).reshape(-1, 1, 1, 1)
        K_iso = torch.exp(-0.5 * sigma ** 2 * HeatKernel.omega_sq(h, w, device))
        if state is None or "shape" not in state or not bool((state["shape"] != ISO).any()):
            return K_iso
        shape = state["shape"].view(-1, 1, 1, 1)
        wy, wx = HeatKernel.freq_xy(h, w, device)
        th = state["theta"].float().view(-1, 1, 1, 1)
        c, s = torch.cos(th), torch.sin(th)
        u = wx * c + wy * s  # frequency along the blur direction
        v = -wx * s + wy * c
        rho = state["rho"].float().view(-1, 1, 1, 1)
        s1sq = 2 * sigma ** 2 / (1 + rho ** 2)
        K_an = torch.exp(-0.5 * (s1sq * u ** 2 + (rho ** 2) * s1sq * v ** 2))
        L = (sigma * math.sqrt(24)).clamp(max=self.motion_max_len)
        a = 0.5 * L * u
        K_mo = torch.where(a.abs() < 1e-6, torch.ones_like(a), torch.sin(a) / a.masked_fill(a.abs() < 1e-6, 1.0))
        return torch.where(shape == MOTION, K_mo, torch.where(shape == ANISO, K_an, K_iso.expand_as(K_an)))

    def blur_family(self, x: torch.Tensor, sigma: torch.Tensor, state: Optional[Dict[str, torch.Tensor]]) -> torch.Tensor:
        """Blur (no noise) with per-sample RMS radius sigma (B,)."""
        with autocast_off(x.device.type):
            h, w = x.shape[-2:]
            return HeatKernel.inverse(HeatKernel.spectrum(x) * self.blur_transfer(sigma, state, h, w, x.device), h, w)

    @staticmethod
    def rank_field(B, H, W, device, generator=None) -> torch.Tensor:
        """Blobby random order with an exactly uniform marginal: mask ratio == tau."""
        r = int(_rand((1,), "cpu", generator).item() * 12) + 4
        low = _rand((B, 1, r, r), device, generator)
        f = F.interpolate(low, size=(H, W), mode="bicubic", align_corners=False)
        f = f + 0.25 * _rand((B, 1, H, W), device, generator)
        order = f.flatten(1).argsort(1).argsort(1).float() / max(H * W - 1, 1)
        return order.view(B, 1, H, W)

    def infer_rank(self, y, tau_obs, observed=None, generator=None) -> torch.Tensor:
        """Rank field consistent with an observed masked image (the true order is unknown)."""
        if observed is None:
            observed = y.abs().sum(1, keepdim=True) > 1e-6
        m = self.mask_ratio(tau_obs)
        u = _rand(tau_obs.shape, y.device, generator)
        return torch.where(observed, m + (1 - m) * u, m * u)

    @staticmethod
    def is_uniform(tau: torch.Tensor) -> torch.Tensor:
        flat = tau.flatten(1)
        return (flat.amax(1) - flat.amin(1)) < 1e-6

    # ---- operators -----------------------------------------------------------------------
    def _downsample(self, x, s: float):
        H, W = x.shape[-2:]
        h2, w2 = max(1, int(round(H * s))), max(1, int(round(W * s)))
        if h2 == H and w2 == W:
            return x
        return F.interpolate(F.interpolate(x, size=(h2, w2), mode="area"), size=(H, W), mode="bilinear", align_corners=False)

    def _uniform(self, x, t: torch.Tensor, name: str, state) -> torch.Tensor:
        """Exact operator, one scalar t per sample (t: (B,))."""
        if name == "blur":
            y = self.blur_family(x, self.sigma(t), state)
            eta = state.get("eta") if state else None
            if eta is not None and bool((eta > 0).any()):  # clock-tied noise [N10]
                y = y + (eta * t.clamp(0, 1)).view(-1, 1, 1, 1) * state["noise"]
            return y
        if name == "noise":
            return x + self.noise_level(t).view(-1, 1, 1, 1) * state["noise"]
        if name == "mask":
            return x * (state["rank"] >= self.mask_ratio(t).view(-1, 1, 1, 1)).to(x.dtype)
        if name == "downsample":
            s = self.scale(t)
            return torch.cat([self._downsample(x[i:i + 1], float(s[i])) for i in range(x.shape[0])], 0)
        raise ValueError(name)

    def _anchor_weights(self, tau):
        pos = tau.clamp(0, 1) * (self.n_anchors - 1)
        lo = pos.floor().clamp(max=self.n_anchors - 2)
        frac = pos - lo
        used = torch.unique(torch.cat([lo.flatten(), lo.flatten() + 1])).long().tolist()
        for a in used:
            w = (lo == a).to(tau.dtype) * (1 - frac) + (lo + 1 == a).to(tau.dtype) * frac
            yield a, w

    def _field(self, x, tau, name: str, state) -> torch.Tensor:
        """Spatially varying operator (tau: (B, 1, H, W))."""
        if name == "noise":
            return x + self.noise_level(tau) * state["noise"]
        if name == "mask":
            return x * (state["rank"] >= self.mask_ratio(tau)).to(x.dtype)
        B = x.shape[0]
        out = torch.zeros_like(x)
        if name == "blur":
            with autocast_off(x.device.type):
                h, w = x.shape[-2:]
                X = HeatKernel.spectrum(x)
                for a, wa in self._anchor_weights(tau):
                    sig = self.sigma(self.anchors[a:a + 1]).expand(B)
                    out = out + wa * HeatKernel.inverse(X * self.blur_transfer(sig, state, h, w, x.device), h, w)
                eta = state.get("eta") if state else None
                if eta is not None and bool((eta > 0).any()):  # clock-tied noise, per pixel [N10]
                    out = out + eta.view(-1, 1, 1, 1) * tau.clamp(0, 1) * state["noise"]
            return out
        for a, wa in self._anchor_weights(tau):  # downsample
            t = self.anchors[a].expand(B)
            out = out + wa * self._uniform(x, t, name, state)
        return out

    def apply(self, x: torch.Tensor, tau: torch.Tensor, kind: torch.Tensor,
              state: Optional[Dict[str, torch.Tensor]] = None, generator=None):
        """
        x: (B, C, H, W) clean-ish image; tau: (B,) or (B, 1, H, W); kind: (B,) long.
        Returns (D(x, tau), state). Differentiable w.r.t. x.
        """
        x = x.float()
        B, C, H, W = x.shape
        if tau.dim() == 1:
            tau = tau.view(B, 1, 1, 1).expand(B, 1, H, W)
        tau = tau.float()
        if state is None:
            state = self.new_state(x, generator)
        uni = self.is_uniform(tau)
        out = torch.zeros_like(x)
        for k_idx, name in enumerate(KINDS):
            sel_k = kind == k_idx
            if not bool(sel_k.any()):
                continue
            for uniform in (True, False):
                sel = sel_k & (uni if uniform else ~uni)
                if not bool(sel.any()):
                    continue
                idx = sel.nonzero(as_tuple=True)[0]
                st = {k: v[idx] for k, v in state.items()}
                if uniform:
                    ys = self._uniform(x[idx], tau[idx, 0, 0, 0], name, st)
                else:
                    ys = self._field(x[idx], tau[idx], name, st)
                out = out.index_copy(0, idx, ys.float())
        return out, state

    def wiener_backproject(self, resid: torch.Tensor, tau: torch.Tensor, lam: float,
                           state: Optional[Dict[str, torch.Tensor]] = None,
                           tau_unc: Optional[torch.Tensor] = None, mu: Optional[torch.Tensor] = None) -> torch.Tensor:
        """
        Range-space pseudo-inverse of the blur operator applied to a residual:   [N2]
            F^-1[ K/(K^2 + lam + Var[dK]) * F(resid) ]
        (local anchors for clock fields). Frequencies with K^2 >> lam are recovered from the
        data, frequencies in the numerical null space (K^2 << lam) are left to the network.
        K is the family transfer function (real, possibly signed for motion: the formula holds).
        Operator-uncertainty Wiener [N12]: with an *estimated* clock (uncertainty tau_unc, (B,)),
        Var[dK] = ((K(tau+u) - K(tau-u))/2)^2 removes the frequencies where a small clock error
        changes the operator a lot, so a wrong kernel is never 'deconvolved' into ringing.
        Noise-aware term mu |w|^2 (mu (B,) = noise var / gradient var of the estimate): a gradient prior that
        stops the anchoring from pushing observation noise back in at high frequencies.
        """
        with autocast_off(resid.device.type):
            B, C, h, w = resid.shape
            R = HeatKernel.spectrum(resid)
            out = torch.zeros_like(resid, dtype=torch.float32)
            uni = self.is_uniform(tau)

            def sub(idx):
                return {k: v[idx] for k, v in state.items()} if state is not None else None

            def gain(t, st, n):  # t: (n,) clocks -> Wiener gain (n, 1, 2h, w+1)
                K = self.blur_transfer(self.sigma(t), st, h, w, resid.device)
                den = K ** 2 + lam
                if mu_sub is not None:
                    den = den + mu_sub.view(-1, 1, 1, 1) * HeatKernel.omega_sq(h, w, resid.device)
                if tau_unc is not None:
                    u = tau_unc_sub
                    Kp = self.blur_transfer(self.sigma((t + u).clamp(0, 1)), st, h, w, resid.device)
                    Km = self.blur_transfer(self.sigma((t - u).clamp(0, 1)), st, h, w, resid.device)
                    den = den + (0.5 * (Kp - Km)) ** 2
                return K / den

            if bool(uni.any()):
                idx = uni.nonzero(as_tuple=True)[0]
                tau_unc_sub = tau_unc[idx].float() if tau_unc is not None else None
                mu_sub = mu[idx].float() if mu is not None else None
                Wg = gain(tau[idx, 0, 0, 0], sub(idx), len(idx))
                out = out.index_copy(0, idx, HeatKernel.inverse(R[idx] * Wg, h, w))
            if bool((~uni).any()):
                idx = (~uni).nonzero(as_tuple=True)[0]
                tau_unc_sub = tau_unc[idx].float() if tau_unc is not None else None
                mu_sub = mu[idx].float() if mu is not None else None
                acc = torch.zeros_like(resid[idx], dtype=torch.float32)
                for a, wa in self._anchor_weights(tau[idx]):
                    Wg = gain(self.anchors[a:a + 1].expand(len(idx)), sub(idx), len(idx))
                    acc = acc + wa * HeatKernel.inverse(R[idx] * Wg, h, w)
                out = out.index_copy(0, idx, acc)
        return out

    def annihilation_weight(self, tau: torch.Tensor, kind: torch.Tensor, h: int, w: int,
                            gamma: float, floor: float, state: Optional[Dict[str, torch.Tensor]] = None) -> torch.Tensor:
        """
        W(w) = (1 - |K_tau(w)|^2)^gamma + floor on the (2h, w+1) spectrum grid:   [N5]
        how much of each frequency the degradation destroyed (blur family aware).
        """
        w2 = HeatKernel.omega_sq(h, w, tau.device)
        B = tau.shape[0]
        flat = tau.reshape(B, -1).float()
        sig_eff = self.sigma(flat).pow(2).mean(1).sqrt()  # RMS blur of the field
        K2 = self.blur_transfer(sig_eff, state, h, w, tau.device) ** 2
        s = self.scale(flat.mean(1)).view(-1, 1, 1, 1)
        K2_ds = torch.sigmoid((s * math.pi - w2.sqrt()) / (0.05 * math.pi)) ** 2
        K2 = torch.where((kind == DOWNSAMPLE).view(-1, 1, 1, 1), K2_ds, K2)
        Wt = (1 - K2).clamp_min(0) ** gamma + floor
        flatW = torch.ones_like(Wt)
        use = ((kind == BLUR) | (kind == DOWNSAMPLE)).view(-1, 1, 1, 1)
        return torch.where(use, Wt, flatW)

    # ---- real pairs: physics-fitted clock labels  [N11] ------------------------------------------
    def _tile_fit(self, sharp, blur, state, n_grid: int, tile: int):
        """Least-squares clock per overlapping tile over a tau grid (blur-only operator of `state`).
        Returns the tile clocks (B,1,h',w'), their confidence (error contrast) and the grid errors."""
        B = sharp.shape[0]
        grid = torch.linspace(0, 1, n_grid, device=sharp.device)
        st = self.blur_only(state)
        with autocast_off(sharp.device.type):
            h, w = sharp.shape[-2:]
            X = HeatKernel.spectrum(sharp)
            errs = []
            for g in grid:
                D = HeatKernel.inverse(X * self.blur_transfer(self.sigma(g.view(1)).expand(B), st, h, w, sharp.device), h, w)
                e = ((D - blur.float()) ** 2).mean(1, keepdim=True)
                errs.append(F.avg_pool2d(e, tile, max(1, tile // 2), padding=0))
            E = torch.stack(errs, 1)[:, :, 0]  # (B, G, h', w')
        i = E.argmin(1, keepdim=True)
        e0 = E.gather(1, i)
        em = E.gather(1, (i - 1).clamp(min=0))
        ep = E.gather(1, (i + 1).clamp(max=n_grid - 1))
        den = em - 2 * e0 + ep
        off = torch.where(den > 1e-12, 0.5 * (em - ep) / den.clamp_min(1e-12), torch.zeros_like(den)).clamp(-0.5, 0.5)
        tau = ((i.float() + off) / (n_grid - 1)).clamp(0, 1)
        conf = (E.amax(1, keepdim=True) - e0) / (E.amax(1, keepdim=True) + 1e-8)  # flat tiles -> ~0
        return tau, conf

    @torch.no_grad()
    def fit_real_pair(self, sharp: torch.Tensor, blur: torch.Tensor, n_grid: int = 25, tile: int = 32,
                      smooth: float = 8.0, anneal_floor: float = 1e-3) -> Tuple[torch.Tensor, Dict[str, torch.Tensor]]:
        """
        Physics-fitted clock field for a REAL blur/sharp pair (no network, no parameters):     [N11]
          1) global blur covariance from the log spectral RATIO |Y|^2/|X|^2 = |K|^2 ~ exp(-w^T S w):
             the image content cancels, so the directional decay rates give S exactly
             (direction theta, axis ratio rho; nearly isotropic -> iso);
          2) per-tile least-squares clock over a tau grid with that shape;
          3) confidence-weighted normalised-convolution smoothing (flat tiles carry no evidence).
        Returns tau (B,1,H,W) and the operator state (moment-matched anisotropic Gaussian).
        """
        sharp, blur = sharp.float(), blur.float()
        B, C, H, W = sharp.shape
        dev = sharp.device
        iso = {"shape": torch.zeros(B, dtype=torch.long, device=dev), "theta": torch.zeros(B, device=dev),
               "rho": torch.ones(B, device=dev), "eta": torch.zeros(B, device=dev)}
        t0, c0 = self._tile_fit(sharp, blur, iso, n_grid, tile)  # isotropic first pass -> blur scale
        s_bar = (self.sigma(t0) * c0).flatten(1).sum(1) / c0.flatten(1).sum(1).clamp_min(1e-8)
        r_max = (math.sqrt(3.0) / s_bar.clamp_min(0.3)).clamp(0.05 * math.pi, 0.7 * math.pi)  # ~3 nepers of decay
        band = torch.stack([0.2 * r_max, r_max], 1)
        s, ctr = directional_decay(_hann_power(blur), band, reference=_hann_power(sharp))
        m, dev_amp, theta = orientation_from_decay(s, ctr)
        l1 = (m + dev_amp).clamp_min(1e-6)
        l2 = (m - dev_amp).clamp_min(0.0)
        rho = torch.sqrt(l2 / l1).clamp(self.aniso_min_ratio, 1.0)
        state = {"shape": torch.where(rho < 0.85, torch.full_like(iso["shape"], ANISO), iso["shape"]),
                 "theta": theta, "rho": rho,
                 # rollout on real pairs anneals the unexplained residual exactly like blind sampling [N12]
                 "eta": torch.full((B,), anneal_floor, device=dev),
                 "noise": torch.zeros_like(sharp), "rank": torch.ones(B, 1, H, W, device=dev)}
        t1, c1 = self._tile_fit(sharp, blur, state, n_grid, tile)
        t1 = F.interpolate(t1, size=(H, W), mode="bilinear", align_corners=False)
        c1 = F.interpolate(c1, size=(H, W), mode="bilinear", align_corners=False).clamp_min(1e-4)
        tau = (HeatKernel.blur(t1 * c1, smooth) / HeatKernel.blur(c1, smooth).clamp_min(1e-6)).clamp(0, 1)
        return tau, state


# =======================================================================================
# SECTION 4: DATASETS
# =======================================================================================

IMAGE_EXTENSIONS = (".jpg", ".jpeg", ".png", ".bmp", ".tif", ".tiff", ".webp")


_LIST_CACHE: Dict[str, Tuple[str, ...]] = {}
_DIR_CACHE: Dict[str, Tuple[str, ...]] = {}


def list_images(folder: Union[str, Path]) -> List[Path]:
    """Sorted image files below `folder` (recursive). Listings are cached for the whole process: the inputs are
    read-only, and the audit, the datasets, the trainer and the inference list the same folders (every listing
    is slow on Kaggle's network-backed /kaggle/input). Paths are returned relative to `folder` as given."""
    folder = Path(folder)
    key = os.path.abspath(str(folder))
    rel = _LIST_CACHE.get(key)
    if rel is None:
        if not folder.is_dir():
            return []
        rel = tuple(sorted((p.relative_to(folder).as_posix() for p in folder.rglob("*")
                            if p.suffix.lower() in IMAGE_EXTENSIONS), key=lambda r: r.split("/")))
        _LIST_CACHE[key] = rel
    return [folder / r for r in rel]


def _subdirs(d: Union[str, Path]) -> List[Path]:
    """Immediate sub-folders of d, sorted by name (cached like list_images)."""
    d = Path(d)
    key = os.path.abspath(str(d))
    names = _DIR_CACHE.get(key)
    if names is None:
        try:
            with os.scandir(d) as it:
                names = tuple(sorted(e.name for e in it if e.is_dir()))
        except OSError:
            return []
        _DIR_CACHE[key] = names
    return [d / n for n in names]


def _spread(items: List[Any], n: int) -> List[Any]:
    """n items evenly spread over the list (every scene / sequence represented), not the first n."""
    if n and 0 < n < len(items):
        return [items[int(i)] for i in np.linspace(0, len(items) - 1, n)]
    return items


class ImageDataset(Dataset):
    """Clean images (a folder, or an explicit list of files) -> dict(image in [-1, 1], path, idx)."""

    def __init__(self, data_dir: Optional[Union[str, Path]], image_size: Tuple[int, int] = (256, 256),
                 split: str = "train", augment: bool = True, max_images: int = 0,
                 paths: Optional[Sequence[Union[str, Path]]] = None, name: str = ""):
        super().__init__()
        self.data_dir = Path(data_dir) if data_dir else None
        self.image_size = tuple(image_size)
        self.split = split
        self.augment = augment
        if paths is not None:
            self.image_paths = [Path(p) for p in paths]
        else:
            self.image_paths = list_images(self.data_dir) if self.data_dir is not None else []
        self.image_paths = _spread(self.image_paths, max_images)  # (was: the first N files = the first scenes only)
        if not self.image_paths:
            raise ValueError(f"No images found in {name or data_dir}")
        print(f"Found {len(self.image_paths)} images in {name or data_dir}")
        self.transform = self._build_transforms()

    def _build_transforms(self):
        normalize = transforms.Normalize(mean=[0.5, 0.5, 0.5], std=[0.5, 0.5, 0.5])
        if self.split == "train" and self.augment:
            return transforms.Compose([
                transforms.RandomResizedCrop(self.image_size, scale=(0.6, 1.0), antialias=True),
                transforms.RandomHorizontalFlip(),
                transforms.RandomApply([transforms.ColorJitter(0.1, 0.1, 0.1, 0.03)], p=0.3),
                transforms.ToTensor(),
                normalize,
            ])
        return transforms.Compose([
            transforms.Resize(min(self.image_size), antialias=True),  # keeps the aspect ratio
            transforms.CenterCrop(self.image_size),
            transforms.ToTensor(),
            normalize,
        ])

    def __len__(self):
        return len(self.image_paths)

    def __getitem__(self, idx):
        # Bounded retry instead of unbounded recursion on corrupt files.
        for attempt in range(10):
            j = idx if attempt == 0 else np.random.randint(0, len(self))
            try:
                img_path = self.image_paths[j]
                image = Image.open(img_path).convert("RGB")
                return {"image": self.transform(image), "path": str(img_path), "idx": j}
            except Exception as e:  # noqa: BLE001
                print(f"Error loading image {self.image_paths[j]}: {e}")
        raise RuntimeError("Too many unreadable images in a row.")


class SyntheticImageDataset(Dataset):
    """
    Procedural images (shapes, edges, stripes, gradients, text-like strokes). Deterministic per
    index. Used as a fallback so the whole pipeline (training, resume, inference and
    interpretability) can be smoke-tested without the Kaggle folders.
    """

    def __init__(self, num_images: int, image_size: Tuple[int, int] = (256, 256), seed: int = 0):
        self.n = num_images
        self.image_size = tuple(image_size)
        self.seed = seed

    def __len__(self):
        return self.n

    def __getitem__(self, idx):
        rng = np.random.RandomState(self.seed * 100003 + idx)
        H, W = self.image_size
        yy, xx = np.mgrid[0:H, 0:W].astype(np.float32)
        c0, c1 = rng.rand(3), rng.rand(3)
        ang = rng.rand() * np.pi
        g = (np.cos(ang) * xx / W + np.sin(ang) * yy / H)
        g = (g - g.min()) / (np.ptp(g) + 1e-6)
        base = (c0[None, None] * (1 - g[..., None]) + c1[None, None] * g[..., None])
        if rng.rand() < 0.6:  # stripes / texture
            f = rng.uniform(4, 40)
            th = rng.rand() * np.pi
            stripes = 0.5 + 0.5 * np.sin(2 * np.pi * f * (np.cos(th) * xx / W + np.sin(th) * yy / H))
            base = base * (0.75 + 0.25 * stripes[..., None])
        img = Image.fromarray((np.clip(base, 0, 1) * 255).astype(np.uint8))
        draw = ImageDraw.Draw(img)
        for _ in range(rng.randint(3, 10)):
            col = tuple(int(v) for v in rng.randint(0, 256, 3))
            x0_, y0_ = rng.randint(0, W), rng.randint(0, H)
            x1_, y1_ = x0_ + rng.randint(8, W // 2), y0_ + rng.randint(8, H // 2)
            kind = rng.randint(0, 3)
            if kind == 0:
                draw.ellipse([x0_, y0_, x1_, y1_], fill=col)
            elif kind == 1:
                draw.rectangle([x0_, y0_, x1_, y1_], fill=col)
            else:
                draw.line([x0_, y0_, x1_, y1_], fill=col, width=int(rng.randint(1, 5)))
        t = torch.from_numpy(np.asarray(img, dtype=np.float32) / 255.0).permute(2, 0, 1)
        return {"image": t * 2 - 1, "path": f"synthetic_{idx:05d}", "idx": idx}


_PAIR_TOKENS = ("blurred", "blurry", "blur", "sharp", "gt", "lq", "hq", "input", "target")


def _pair_keys(files: List[Path], base: Path, loose: bool = False) -> Dict[str, Path]:
    """Matching keys of the files of one side of a pair: the relative path; loose=True also drops the side
    tokens ('blur_12.png' and 'gt_12.png' -> '12') and the extension, for copies that name the sides differently."""
    out = {}
    for p in files:
        rel = p.relative_to(base)
        if loose:
            stem = rel.stem.lower()
            for tok in _PAIR_TOKENS:
                stem = stem.replace(tok, "")
            key = (rel.parent / "".join(ch for ch in stem if ch.isalnum())).as_posix()
        else:
            key = rel.as_posix()
        out[key] = p
    return out


def match_pair_files(blur_dir: Path, sharp_dir: Path) -> Tuple[List[Tuple[str, Path, Path]], int]:
    """([(key, blur file, sharp file)], number of unmatched files) for one blur / sharp folder pair: identical
    relative paths, or - when no name matches at all - names without the side tokens (blur_12 <-> gt_12)."""
    bl, sh = list_images(blur_dir), list_images(sharp_dir)
    blur, sharp = _pair_keys(bl, blur_dir), _pair_keys(sh, sharp_dir)
    if not set(blur) & set(sharp):  # e.g. the original RealBlur release: blur/blur_12.png <-> gt/gt_12.png
        blur, sharp = _pair_keys(bl, blur_dir, True), _pair_keys(sh, sharp_dir, True)
    keys = sorted(set(blur) & set(sharp))
    return [(k, blur[k], sharp[k]) for k in keys], len(set(blur) ^ set(sharp))


def _pad_to(t: torch.Tensor, h: int, w: int) -> torch.Tensor:
    """Mirror-pads (C, H, W) at the bottom / right to at least (h, w). The mirror (even) extension is exactly the
    Neumann boundary the heat operator assumes, so a padded real pair stays consistent with the blur model.
    Images smaller than the crop (text crops, small RealBlur frames) used to give smaller crops -> the batch
    could not be collated."""
    while t.shape[-2] < h or t.shape[-1] < w:
        ph = min(h - t.shape[-2], t.shape[-2] - 1) if t.shape[-2] < h else 0
        pw = min(w - t.shape[-1], t.shape[-1] - 1) if t.shape[-1] < w else 0
        if ph <= 0 and pw <= 0:  # a 1-pixel side cannot be mirrored
            return F.pad(t[None], (0, max(0, w - t.shape[-1]), 0, max(0, h - t.shape[-2])), mode="replicate")[0]
        t = F.pad(t[None], (0, max(pw, 0), 0, max(ph, 0)), mode="reflect")[0]
    return t


class PairedImageDataset(Dataset):
    """
    Real degraded -> sharp pairs. Layouts: <split>/blur/NAME <-> <split>/sharp/NAME (DBlur) and per scene
    <split>/<scene>/blur/NAME <-> <split>/<scene>/sharp/NAME (original GoPro / RealBlur style); the folders may also
    be called input/target, lq/gt, blurred/groundtruth, ... (see _BLUR_DIR_NAMES / _SHARP_DIR_NAMES).
      mode 'train': the SAME random crop / flip on both images, at native resolution (the blur size
                    of real photos is preserved; resizing would shrink the blur).
      mode 'val'  : deterministic centre crop.
      mode 'test' : full image (optionally resized so that the longer side <= max_side).
    Images smaller than the crop are mirror-padded in 'train' / 'val' (one size per batch).
    Returns {"image": sharp, "degraded": blurred, "path": blurred path, "subset": dataset name} in [-1, 1].
    `group` is the requested dataset name it was matched from ('RealBlur' for RealBlur_J): the training mix is
    balanced per group.
    """

    def __init__(self, blur_dir: Optional[Union[str, Path]] = None, sharp_dir: Optional[Union[str, Path]] = None,
                 crop: Tuple[int, int] = (256, 256), mode: str = "train", max_images: int = 0, max_side: int = 0,
                 name: str = "", dir_pairs: Optional[Sequence[Tuple[Union[str, Path], Union[str, Path]]]] = None,
                 group: str = ""):
        if dir_pairs is None:
            dir_pairs = [(blur_dir, sharp_dir)]
        dir_pairs = [(Path(b), Path(s)) for b, s in dir_pairs]
        self.blur_dir, self.sharp_dir = dir_pairs[0]
        self.crop, self.mode, self.max_side = tuple(crop), mode, max_side
        self.name = name or self.blur_dir.parent.parent.name
        self.group = group or self.name
        pairs, self.unmatched = [], 0
        for bd, sd in dir_pairs:
            matched, unmatched = match_pair_files(bd, sd)
            pairs += [(b, s) for _, b, s in matched]
            self.unmatched += unmatched
        pairs = _spread(pairs, max_images)  # evenly spread subset (all scenes)
        if not pairs:
            raise ValueError(f"No matching blur/sharp file names in {self.blur_dir} / {self.sharp_dir}"
                             + (f" (and {len(dir_pairs) - 1} more scene folders)" if len(dir_pairs) > 1 else ""))
        self.pairs = pairs

    def __len__(self):
        return len(self.pairs)

    @staticmethod
    def _load(p: Path) -> torch.Tensor:
        return transforms.ToTensor()(Image.open(p).convert("RGB")) * 2 - 1

    def __getitem__(self, idx):
        bp, sp = self.pairs[idx]
        y, x = self._load(bp), self._load(sp)
        if y.shape != x.shape:  # should not happen in DBlur; keep the pair usable
            y = F.interpolate(y[None], size=x.shape[-2:], mode="bilinear", align_corners=False)[0]
        H, W = x.shape[-2:]
        if self.mode in ("train", "val") and (H < self.crop[0] or W < self.crop[1]):
            x, y = _pad_to(x, *self.crop), _pad_to(y, *self.crop)
            H, W = x.shape[-2:]
        ch, cw = min(self.crop[0], H), min(self.crop[1], W)
        if self.mode == "train":
            i, j = random.randint(0, H - ch), random.randint(0, W - cw)
            x, y = x[:, i:i + ch, j:j + cw], y[:, i:i + ch, j:j + cw]
            if random.random() < 0.5:
                x, y = x.flip(-1), y.flip(-1)
        elif self.mode == "val":
            i, j = (H - ch) // 2, (W - cw) // 2
            x, y = x[:, i:i + ch, j:j + cw], y[:, i:i + ch, j:j + cw]
        elif self.max_side and max(H, W) > self.max_side:
            s = self.max_side / max(H, W)
            size = (max(8, int(round(H * s / 8)) * 8), max(8, int(round(W * s / 8)) * 8))
            x = F.interpolate(x[None], size=size, mode="bicubic", align_corners=False, antialias=True)[0].clamp(-1, 1)
            y = F.interpolate(y[None], size=size, mode="bicubic", align_corners=False, antialias=True)[0].clamp(-1, 1)
        return {"image": x.contiguous(), "degraded": y.contiguous(), "path": str(bp), "idx": idx, "subset": self.name}


_BLUR_DIR_NAMES = ("blur", "blurred", "blurry", "input", "inputs", "lq", "degraded")
_SHARP_DIR_NAMES = ("sharp", "gt", "groundtruth", "target", "targets", "hq", "clean")
_SPLIT_NAMES = {"train": ("train", "training", "trainset", "trainingset"), "test": ("test", "testing", "testset"),
                "val": ("val", "validation", "valid", "valset")}


def _norm_name(s: str) -> str:
    """'RealBlur_J' / 'realblur-j' / 'RealBlur J' -> 'realblurj' (folder names differ between dataset copies)."""
    return "".join(ch for ch in s.lower() if ch.isalnum())


def _blur_sharp_dirs(d: Path) -> Optional[Tuple[Path, Path]]:
    sub = {_norm_name(c.name): c for c in _subdirs(d)}
    b = next((sub[n] for n in _BLUR_DIR_NAMES if n in sub), None)
    s = next((sub[n] for n in _SHARP_DIR_NAMES if n in sub), None)
    return (b, s) if (b is not None and s is not None) else None


def match_subsets(root: Union[str, Path], wanted: Sequence[str]) -> List[Tuple[str, Path]]:
    """[(requested name, subset folder)]: an exact match of the normalised name first, otherwise every folder whose
    normalised name starts with it ('RealBlur' -> RealBlur_J and RealBlur_R). The old lookup was an exact,
    case-insensitive match only, so 'RealBlur' or 'Text-OCR' silently found nothing."""
    children = _subdirs(root)
    out, used = [], set()
    for want in wanted:
        w = _norm_name(want)
        hits = ([c for c in children if _norm_name(c.name) == w]
                or [c for c in children if w and _norm_name(c.name).startswith(w)])
        for c in hits:
            if c not in used:
                used.add(c)
                out.append((want, c))
    return out


def find_pair_dirs(root: Union[str, Path], subsets: Sequence[str], split: str) -> List[Tuple[str, List[Tuple[Path, Path]], str]]:
    """[(subset folder name, [(blur_dir, sharp_dir), ...], requested name)] for <root>/<subset>/<split>/{blur,sharp}
    or <root>/<subset>/<split>/<scene>/{blur,sharp}."""
    root = Path(root)
    if not root.is_dir():
        return []
    split_names = _SPLIT_NAMES.get(split, (split,))
    out = []
    for want, d in match_subsets(root, subsets):
        split_dir = next((c for c in _subdirs(d) if _norm_name(c.name) in split_names), None)
        if split_dir is None:
            continue
        bs = _blur_sharp_dirs(split_dir)
        pairs = [bs] if bs else [p for p in (_blur_sharp_dirs(s) for s in _subdirs(split_dir)) if p]
        if pairs:
            out.append((d.name, pairs, want))
    return out


def describe_real_subsets(cfg: Config) -> List[str]:
    """What happened to every requested real dataset that was NOT found (and which folders do exist), so a
    different folder name or layout is visible instead of the dataset being silently left out."""
    root = Path(cfg.paired_root)
    if not root.is_dir():
        return [f"paired_root '{cfg.paired_root}' does not exist -> no real pairs are used"]
    lines = []
    for split, wanted in (("train", cfg.real_train_subsets), ("test", cfg.real_test_subsets)):
        got = {w for _, _, w in find_pair_dirs(root, wanted, split)}
        for w in wanted:
            if w in got:
                continue
            folders = [d.name for _, d in match_subsets(root, [w])]
            why = (f"folder(s) {folders} have no '{split}' split with blur/sharp sub-folders" if folders
                   else "no folder of that name")
            lines.append(f"real {split} set {w!r} not used: {why}")
    if lines:
        lines.append(f"folders under {root}: {', '.join(c.name for c in _subdirs(root)) or '(none)'}")
    return lines


def build_real_pairs(cfg: Config, split: str, mode: str, max_images: int = 0, max_side: int = 0,
                     max_total: int = 0) -> List[PairedImageDataset]:
    """One PairedImageDataset per resolved subset folder ('RealBlur' -> RealBlur_J and RealBlur_R).
    max_total > 0 spreads that many pairs evenly over the subsets (per-epoch validation on every real dataset)."""
    subsets = cfg.real_train_subsets if split == "train" else cfg.real_test_subsets
    found = find_pair_dirs(cfg.paired_root, subsets, split)
    if max_total and found:
        max_images = max(1, int(math.ceil(max_total / len(found))))
    out = []
    for name, pairs, want in found:
        try:
            out.append(PairedImageDataset(crop=cfg.image_size, mode=mode, max_images=max_images, max_side=max_side,
                                          name=name, dir_pairs=pairs, group=want))
        except ValueError as e:
            print(f"[data] {e}")
    return out


def real_sharp_frames(cfg: Config) -> List[Tuple[str, List[Path]]]:
    """Sharp frames of the real TRAIN pairs (per subset, evenly thinned to real_sharp_max_per_subset): additional
    CLEAN images for the synthetic blur-family / noise degradations. Test splits are never used here."""
    if not cfg.real_sharp_as_clean:
        return []
    out = []
    for name, pairs, _ in find_pair_dirs(cfg.paired_root, cfg.real_train_subsets, "train"):
        files = _spread([p for _, sd in pairs for p in list_images(sd)], cfg.real_sharp_max_per_subset)
        if files:
            out.append((name, files))
    return out


# ------------------------------- dataset audit (roles / pairing / sharpness) -------------------------------
_DEGRADED_NAMES = {"blur", "blurred", "blurry", "input", "inputs", "lq", "degraded", "noisy", "low", "haze", "rain"}


def _looks_degraded(path: str) -> bool:
    """Only the last two folder levels are inspected (e.g. .../test/blur): every Kaggle path starts with
    /kaggle/input/..., and 'input' is also the degraded-folder name of some datasets (input/target)."""
    parts = [p.lower() for p in Path(path).parts if p not in ("/", "")]
    return any(p in _DEGRADED_NAMES for p in parts[-2:])


@torch.no_grad()
def sharpness_score(path: Union[str, Path], max_side: int = 512) -> float:
    """High-frequency energy ratio of the luminance (larger = sharper): |x - G_1.5 * x| / std(x)."""
    x, _ = load_image_tensor(path, max_side)
    lum = x.mean(1, keepdim=True)
    hf = (lum - HeatKernel.blur(lum, 1.5)).abs().mean()
    return float(hf / (lum.std() + 1e-6))


def audit_datasets(cfg: Config, n_check: int = 8) -> Dict[str, Any]:
    """
    Stops the pipeline when a degraded folder is used as ground truth (the previous config used
    Gopro/test/BLUR as clean test images and HIDE/test/SHARP as 'blurred' inputs), checks the
    blur/sharp pairing and verifies on a few pairs that 'sharp' really is sharper than 'blur'.
    """
    problems, report = [], {"clean": {}, "pairs": {}, "real_images": None}
    roles = [("train_data_dir", cfg.train_data_dir), ("val_data_dir", cfg.val_data_dir),
             ("test_data_dir", cfg.test_data_dir)] + [(f"extra_clean_dirs[{i}]", d) for i, d in enumerate(cfg.extra_clean_dirs)]
    for role, d in roles:
        if not d:
            continue
        n = len(list_images(d))
        report["clean"][role] = {"path": d, "images": n}
        if n and _looks_degraded(d):
            problems.append(f"{role} = '{d}' is a degraded (blurred) folder but is used as CLEAN ground truth.")
    for name, files in real_sharp_frames(cfg):  # sharp frames of the real TRAIN pairs, also used as clean images
        report["clean"][f"{name}/train sharp"] = {"path": str(files[0].parent), "images": len(files)}
        degraded = [f for f in files[:50] if _looks_degraded(str(f.parent))]
        if degraded:
            problems.append(f"{name}/train sharp frames look like degraded images ({degraded[0]}).")
    if cfg.real_images_dir and list_images(cfg.real_images_dir):
        leaf = Path(cfg.real_images_dir).name.lower()
        report["real_images"] = {"path": cfg.real_images_dir, "images": len(list_images(cfg.real_images_dir))}
        if leaf in ("sharp", "gt", "clean", "target", "groundtruth", "hq"):
            problems.append(f"real_images_dir = '{cfg.real_images_dir}' contains SHARP images; it must contain the "
                            f"blurred photos to restore (e.g. .../HIDE/test/blur).")
    for split, subsets in (("train", cfg.real_train_subsets), ("test", cfg.real_test_subsets)):
        for name, dir_pairs, want in find_pair_dirs(cfg.paired_root, subsets, split):
            # relative paths, exactly as PairedImageDataset pairs them (bare file names paired the wrong files - or
            # crashed - when scenes live in sub-folders with repeated frame names)
            both, unmatched = [], 0
            for bd, sd in dir_pairs:  # exactly the pairing PairedImageDataset uses
                matched, n_un = match_pair_files(bd, sd)
                both += [(b, s) for _, b, s in matched]
                unmatched += n_un
            info = {"blur": str(dir_pairs[0][0]), "sharp": str(dir_pairs[0][1]), "pairs": len(both),
                    "unmatched": unmatched, "scene_folders": len(dir_pairs), "requested_as": want}
            if both:
                pick = _spread(both, min(n_check, len(both)))
                sharper = [sharpness_score(s) > sharpness_score(b) for b, s in pick]
                info["sharp_is_sharper"] = f"{sum(sharper)}/{len(sharper)}"
                if sum(sharper) < 0.75 * len(sharper):
                    problems.append(f"{name}/{split}: the 'sharp' images are not sharper than the 'blur' images in "
                                    f"{len(sharper) - sum(sharper)}/{len(sharper)} checked pairs -> folders swapped?")
            report["pairs"][f"{name}/{split}"] = info
    notes = describe_real_subsets(cfg)
    report["notes"] = notes
    print("Dataset audit:")
    for role, v in report["clean"].items():
        print(f"  CLEAN  {role:22s} {v['images']:6d} images  {v['path']}")
    for k, v in report["pairs"].items():
        scenes = f", {v['scene_folders']} scene folders" if v["scene_folders"] > 1 else ""
        print(f"  PAIRS  {k:22s} {v['pairs']:6d} pairs (unmatched {v['unmatched']}, sharp sharper: "
              f"{v.get('sharp_is_sharper', '-')}{scenes}; requested as {v['requested_as']!r})")
    if report["real_images"]:
        print(f"  REAL   real_images_dir        {report['real_images']['images']:6d} blurred photos  {report['real_images']['path']}")
    for n in notes:
        print(f"  NOTE   {n}")
    for p in problems:
        print(f"  PROBLEM: {p}")
    report["problems"] = problems
    if problems and cfg.strict_dataset_audit:
        raise ValueError("Dataset audit failed (set strict_dataset_audit=False to continue anyway):\n  " + "\n  ".join(problems))
    return report


def build_datasets(cfg: Config) -> Tuple[Dataset, Dataset]:
    """Returns (train, val) of CLEAN images: train_data_dir + extra_clean_dirs + the sharp frames of the real
    TRAIN pairs (GoPro / HIDE / RealBlur / TextOCR ...), val_data_dir. Falls back to procedural data if the
    folders are missing."""
    try:
        parts = [ImageDataset(cfg.train_data_dir, cfg.image_size, "train", cfg.augment, cfg.max_train_images)]
        covered = [os.path.abspath(cfg.train_data_dir)]
        for d in cfg.extra_clean_dirs:
            if d and os.path.abspath(d) in covered:
                continue
            if d and list_images(d):
                parts.append(ImageDataset(d, cfg.image_size, "train", cfg.augment, cfg.max_train_images))
                covered.append(os.path.abspath(d))
            elif d:
                print(f"[data] extra clean folder not found, skipped: {d}")
        for name, files in real_sharp_frames(cfg):
            # files already present through train_data_dir / extra_clean_dirs are not added twice
            files = [f for f in files if not any(os.path.abspath(f).startswith(c + os.sep) for c in covered)]
            if files:
                parts.append(ImageDataset(None, cfg.image_size, "train", cfg.augment, paths=files,
                                          name=f"{name}/train sharp frames (real-pair training split)"))
        train = parts[0] if len(parts) == 1 else torch.utils.data.ConcatDataset(parts)
        val = ImageDataset(cfg.val_data_dir, cfg.image_size, "val", False, cfg.max_val_images)
        return train, val
    except ValueError as e:
        if not cfg.synthetic_fallback:
            raise
        print(f"[data] {e} -> using SyntheticImageDataset fallback.")
        return (SyntheticImageDataset(cfg.synthetic_num_train, cfg.image_size, seed=cfg.seed),
                SyntheticImageDataset(cfg.synthetic_num_val, cfg.image_size, seed=cfg.seed + 1))


def load_image_tensor(path: Union[str, Path], max_side: int = 0) -> Tuple[torch.Tensor, Tuple[int, int]]:
    """Loads an arbitrary-size RGB image as (1, 3, H, W) in [-1, 1]; returns it and the original (W, H)."""
    img = Image.open(path).convert("RGB")
    orig = img.size
    if max_side and max(img.size) > max_side:
        s = max_side / max(img.size)
        img = img.resize((max(8, int(img.width * s)), max(8, int(img.height * s))), Image.BICUBIC)
    t = transforms.ToTensor()(img) * 2 - 1
    return t.unsqueeze(0), orig


# =======================================================================================
# SECTION 5: MODEL
# =======================================================================================

# ------------------------------------ 5.1 generic layers ------------------------------------


class Mlp(nn.Module):
    """MLP as used in Vision Transformer, MLP-Mixer and related networks."""

    def __init__(self, in_features, hidden_features=None, out_features=None, act_layer=nn.GELU,
                 norm_layer=None, bias=True, drop=0.0, use_conv=False):
        super().__init__()
        out_features = out_features or in_features
        hidden_features = hidden_features or in_features
        bias = to_2tuple(bias)
        drop_probs = to_2tuple(drop)
        linear_layer = partial(nn.Conv2d, kernel_size=1) if use_conv else nn.Linear
        self.fc1 = linear_layer(in_features, hidden_features, bias=bias[0])
        self.act = act_layer()
        self.drop1 = nn.Dropout(drop_probs[0])
        self.norm = norm_layer(hidden_features) if norm_layer is not None else nn.Identity()
        self.fc2 = linear_layer(hidden_features, out_features, bias=bias[1])
        self.drop2 = nn.Dropout(drop_probs[1])

    def forward(self, x):
        x = self.drop1(self.act(self.fc1(x)))
        x = self.norm(x)
        return self.drop2(self.fc2(x))


class DropPath(nn.Module):
    """Drop paths (Stochastic Depth) per sample during training."""

    def __init__(self, drop_prob=0.0):
        super().__init__()
        self.drop_prob = drop_prob

    def forward(self, x):
        if self.drop_prob == 0.0 or not self.training:
            return x
        keep_prob = 1 - self.drop_prob
        shape = (x.shape[0],) + (1,) * (x.ndim - 1)
        random_tensor = (keep_prob + torch.rand(shape, dtype=x.dtype, device=x.device)).floor_()
        return x.div(keep_prob) * random_tensor


def bchw_to_bhwc(x: torch.Tensor) -> torch.Tensor:
    """Permutes a tensor from the shape (B, C, H, W) to (B, H, W, C)."""
    return x.permute(0, 2, 3, 1)


def bhwc_to_bchw(x: torch.Tensor) -> torch.Tensor:
    """Permutes a tensor from the shape (B, H, W, C) to (B, C, H, W)."""
    return x.permute(0, 3, 1, 2)


def window_partition(x, window_size: Tuple[int, int]):
    """Partition input feature (B, H, W, C) into non-overlapping windows."""
    B, H, W, C = x.shape
    wh, ww = window_size
    x = x.view(B, H // wh, wh, W // ww, ww, C)
    return x.permute(0, 1, 3, 2, 4, 5).contiguous().view(-1, wh, ww, C)


def window_reverse(windows, window_size: Tuple[int, int], img_size: Tuple[int, int]):
    """Reverse window partitioning."""
    H, W = img_size
    wh, ww = window_size
    C = windows.shape[-1]
    num_windows = (H // wh) * (W // ww)
    B = windows.shape[0] // num_windows
    x = windows.view(B, H // wh, W // ww, wh, ww, C)
    return x.permute(0, 1, 3, 2, 4, 5).contiguous().view(B, H, W, C)


# ------------------------------------ 5.2 Swin-V2 (CR) attention ------------------------------------


class WindowMultiHeadAttention(nn.Module):
    """Window-based multi-head cosine attention with log-spaced continuous position bias."""

    def __init__(self, dim: int, num_heads: int, window_size: Tuple[int, int], drop_attn: float = 0.0,
                 drop_proj: float = 0.0, meta_hidden_dim: int = 384):
        super().__init__()
        assert dim % num_heads == 0, f"Input features ({dim}) must be divisible by number of heads ({num_heads})."
        self.dim = dim
        self.head_dim = dim // num_heads
        self.window_size = to_2tuple(window_size)
        self.num_heads = num_heads
        self.qkv = nn.Linear(dim, dim * 3, bias=True)
        self.attn_drop = nn.Dropout(drop_attn)
        self.proj = nn.Linear(dim, dim, bias=True)
        self.proj_drop = nn.Dropout(drop_proj)
        self.meta_mlp = Mlp(2, hidden_features=meta_hidden_dim, out_features=num_heads, act_layer=nn.ReLU, drop=(0.125, 0.0))
        self.logit_scale = nn.Parameter(torch.log(10 * torch.ones(num_heads)))
        self.capture = False  # interpretability: keep the last attention maps
        self.last_attn: Optional[torch.Tensor] = None
        self._init_relative_position_encoding()

    def _init_relative_position_encoding(self) -> None:
        device = self.logit_scale.device
        coords = torch.stack(ndgrid(torch.arange(self.window_size[0], device=device),
                                    torch.arange(self.window_size[1], device=device)), dim=0).flatten(1)
        rel = (coords[:, :, None] - coords[:, None, :]).permute(1, 2, 0).reshape(-1, 2).float()
        rel_log = torch.sign(rel) * torch.log(1.0 + rel.abs())
        self.register_buffer("relative_coordinates_log", rel_log, persistent=False)
        self.register_buffer("relative_distance", rel.norm(dim=-1).view(self.window_area, self.window_area), persistent=False)

    @property
    def window_area(self):
        return self.window_size[0] * self.window_size[1]

    def _compute_relative_position_bias(self) -> torch.Tensor:
        bias = self.meta_mlp(self.relative_coordinates_log)
        return bias.transpose(1, 0).reshape(self.num_heads, self.window_area, self.window_area).unsqueeze(0)

    def forward(self, x: torch.Tensor, mask: Optional[torch.Tensor] = None) -> torch.Tensor:
        Bw, N, C = x.shape
        qkv = self.qkv(x).view(Bw, N, 3, self.num_heads, C // self.num_heads).permute(2, 0, 3, 1, 4)
        q, k, v = qkv.unbind(0)
        attn = F.normalize(q, dim=-1) @ F.normalize(k, dim=-1).transpose(-2, -1)
        logit_scale = torch.clamp(self.logit_scale.reshape(1, self.num_heads, 1, 1), max=math.log(1.0 / 0.01)).exp()
        attn = attn * logit_scale + self._compute_relative_position_bias()
        if mask is not None:
            nW = mask.shape[0]
            attn = attn.view(Bw // nW, nW, self.num_heads, N, N) + mask.unsqueeze(1).unsqueeze(0)
            attn = attn.view(-1, self.num_heads, N, N)
        attn = attn.softmax(dim=-1)
        if self.capture:
            self.last_attn = attn.detach().float()
        attn = self.attn_drop(attn)
        x = (attn @ v).transpose(1, 2).reshape(Bw, N, C)
        return self.proj_drop(self.proj(x))


class SwinTransformerBlock(nn.Module):
    """Swin-V2 (res-post-norm) block. Pads *then* rolls; attention masks are cached per size."""

    def __init__(self, dim: int, num_heads: int, window_size, shift_size=0, mlp_ratio: float = 4.0,
                 init_values: Optional[float] = 0.0, proj_drop: float = 0.0, drop_attn: float = 0.0,
                 drop_path: float = 0.0, extra_norm: bool = False, norm_layer=nn.LayerNorm):
        super().__init__()
        self.dim = dim
        self.window_size = to_2tuple(window_size)
        shift = to_2tuple(shift_size)
        self.shift_size = (self.window_size[0] // 2, self.window_size[1] // 2) if any(shift) else (0, 0)
        self.window_area = self.window_size[0] * self.window_size[1]
        self.init_values = init_values
        self.norm1 = norm_layer(dim)
        self.attn = WindowMultiHeadAttention(dim, num_heads, self.window_size, drop_attn, proj_drop)
        self.drop_path1 = DropPath(drop_path) if drop_path > 0.0 else nn.Identity()
        self.norm2 = norm_layer(dim)
        self.mlp = Mlp(dim, hidden_features=int(dim * mlp_ratio), out_features=dim, drop=proj_drop)
        self.drop_path2 = DropPath(drop_path) if drop_path > 0.0 else nn.Identity()
        self.norm3 = norm_layer(dim) if extra_norm else nn.Identity()
        self._mask_cache: Dict[Tuple[int, int, str], Optional[torch.Tensor]] = {}
        if self.init_values is not None:  # layer-scale-like zero init of the residual branches
            nn.init.constant_(self.norm1.weight, self.init_values)
            nn.init.constant_(self.norm2.weight, self.init_values)

    def _attention_mask(self, H: int, W: int, Hp: int, Wp: int, device) -> Optional[torch.Tensor]:
        padded = Hp != H or Wp != W
        if not any(self.shift_size) and not padded:
            return None
        key = (H, W, str(device))
        mask = self._mask_cache.get(key)
        if mask is None:
            wh, ww = self.window_size
            sh, sw = self.shift_size
            img_mask = torch.zeros((1, Hp, Wp, 1), device=device)
            if sh or sw:
                cnt = 0
                for hs in (slice(0, -wh), slice(-wh, -sh), slice(-sh, None)):
                    for ws in (slice(0, -ww), slice(-ww, -sw), slice(-sw, None)):
                        img_mask[:, hs, ws, :] = cnt
                        cnt += 1
            if padded:
                # Zero-padded tokens form a region of their own: real tokens never attend to them (they did before,
                # for every input whose latent size is not a multiple of the window, e.g. 1280x720 photos).
                pad = torch.zeros((1, Hp, Wp, 1), device=device)
                pad[:, H:] = 1.0
                pad[:, :, W:] = 1.0
                if sh or sw:  # the mask lives in the rolled coordinates
                    pad = torch.roll(pad, shifts=(-sh, -sw), dims=(1, 2))
                img_mask = img_mask + 16.0 * pad
            mw = window_partition(img_mask, self.window_size).view(-1, self.window_area)
            m = mw.unsqueeze(1) - mw.unsqueeze(2)
            mask = m.masked_fill(m != 0, -100.0).masked_fill(m == 0, 0.0)
            if len(self._mask_cache) >= 16:  # many photo sizes at inference -> bounded cache
                self._mask_cache.clear()
            self._mask_cache[key] = mask
        return mask

    def _shifted_window_attention(self, x):
        B, H, W, C = x.shape
        wh, ww = self.window_size
        pad_h, pad_w = (wh - H % wh) % wh, (ww - W % ww) % ww
        x = F.pad(x, (0, 0, 0, pad_w, 0, pad_h))
        Hp, Wp = H + pad_h, W + pad_w
        sh, sw = self.shift_size
        if sh or sw:
            x = torch.roll(x, shifts=(-sh, -sw), dims=(1, 2))
        xw = window_partition(x, self.window_size).view(-1, self.window_area, C)
        aw = self.attn(xw, mask=self._attention_mask(H, W, Hp, Wp, x.device)).view(-1, wh, ww, C)
        x = window_reverse(aw, self.window_size, (Hp, Wp))
        if sh or sw:
            x = torch.roll(x, shifts=(sh, sw), dims=(1, 2))
        return x[:, :H, :W, :].contiguous()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        B, H, W, C = x.shape
        x = x + self.drop_path1(self.norm1(self._shifted_window_attention(x)))
        x = x.reshape(B, -1, C)
        x = x + self.drop_path2(self.norm2(self.mlp(x)))
        x = self.norm3(x)
        return x.reshape(B, H, W, C)


# ------------------------------------ 5.3 clock conditioning  [N1] ------------------------------------


class Cond:
    """Conditioning bundle passed through the network: global features, per-pixel clock
    embedding (lazily pooled to every resolution) and the mean blur std (pixels)."""

    def __init__(self, feats: torch.Tensor, cmap: Optional[torch.Tensor], sigma_bar: torch.Tensor):
        self.feats, self.cmap, self.sigma_bar = feats, cmap, sigma_bar
        self._cache: Dict[Tuple[int, int], torch.Tensor] = {}

    def cmap_at(self, h: int, w: int) -> Optional[torch.Tensor]:
        if self.cmap is None:
            return None
        if (h, w) not in self._cache:
            self._cache[(h, w)] = self.cmap if tuple(self.cmap.shape[-2:]) == (h, w) else F.adaptive_avg_pool2d(self.cmap, (h, w))
        return self._cache[(h, w)]


class TimePosEmbedding(nn.Module):
    """Sinusoidal embedding. tau in [0, 1] is scaled by T (the original fed t~1e-6)."""

    def __init__(self, dim, scale: float = 1000.0):
        super().__init__()
        self.dim = dim
        self.scale = scale

    def forward(self, t):
        t = t.float() * self.scale
        half = self.dim // 2
        emb = math.log(10000) / (half - 1)
        emb = torch.exp(torch.arange(half, device=t.device) * -emb)
        emb = t[:, None] * emb[None, :]
        return torch.cat((emb.sin(), emb.cos()), dim=-1)


class ClockEmbedding(nn.Module):
    """Per-pixel Fourier embedding of the clock field tau(x) -> (B, E, H, W)."""

    def __init__(self, out_dim: int = 32, n_freq: int = 6):
        super().__init__()
        self.register_buffer("freqs", (2.0 ** torch.arange(n_freq)).float() * math.pi, persistent=False)
        self.net = nn.Sequential(nn.Conv2d(2 * n_freq + 1, out_dim, 1), nn.SiLU(), nn.Conv2d(out_dim, out_dim, 1))

    def forward(self, tau):
        ang = tau * self.freqs.view(1, -1, 1, 1)
        return self.net(torch.cat([tau, ang.sin(), ang.cos()], 1))


class ClockModulatedNorm2d(nn.Module):
    """
    Clock-Modulated Normalisation (successor of ConditionalNorm2d):
        out = GN(x) * (1 + g_global(f) + g_spatial(E(tau)))  +  b_global(f) + b_spatial(E(tau))
    Zero-initialised -> starts as plain GroupNorm (the old version started from random scales).
    """

    def __init__(self, channels, num_features, clock_dim: int = 0):
        super().__init__()
        self.channels = channels
        self.norm = nn.GroupNorm(num_groups(channels), channels, affine=False, eps=1e-4)
        self.fc = nn.Linear(num_features, 2 * channels)
        nn.init.zeros_(self.fc.weight)
        nn.init.zeros_(self.fc.bias)
        self.spatial = nn.Conv2d(clock_dim, 2 * channels, 1) if clock_dim > 0 else None
        if self.spatial is not None:
            nn.init.zeros_(self.spatial.weight)
            nn.init.zeros_(self.spatial.bias)

    def forward(self, x, cond: Cond):
        out = self.norm(x)
        g, b = self.fc(cond.feats)[:, :, None, None].chunk(2, 1)
        if self.spatial is not None and cond.cmap is not None:
            gs, bs = self.spatial(cond.cmap_at(*x.shape[-2:])).chunk(2, 1)
            g, b = g + gs, b + bs
        return out * (1 + g) + b


# ------------------------------------ 5.4 attention / conv blocks ------------------------------------


class ChannelAttention(nn.Module):
    def __init__(self, channels, reduction=16):
        super().__init__()
        hidden = max(1, channels // reduction)
        self.avg_pool = nn.AdaptiveAvgPool2d(1)
        self.max_pool = nn.AdaptiveMaxPool2d(1)
        self.fc = nn.Sequential(nn.Conv2d(channels, hidden, 1), nn.ReLU(inplace=True), nn.Conv2d(hidden, channels, 1))
        self.sigmoid = nn.Sigmoid()

    def forward(self, x):
        return self.sigmoid(self.fc(self.avg_pool(x)) + self.fc(self.max_pool(x))) * x


class SpatialAttention(nn.Module):
    def __init__(self, kernel_size=7):
        super().__init__()
        self.conv = nn.Conv2d(2, 1, kernel_size=kernel_size, padding=kernel_size // 2)
        self.sigmoid = nn.Sigmoid()

    def forward(self, x):
        avg_out = torch.mean(x, dim=1, keepdim=True)
        max_out, _ = torch.max(x, dim=1, keepdim=True)
        return x * self.sigmoid(self.conv(torch.cat([avg_out, max_out], dim=1)))


class BAM(nn.Module):
    def __init__(self, channels, reduction=16, kernel_size=7):
        super().__init__()
        self.cam = ChannelAttention(channels, reduction)
        self.sam = SpatialAttention(kernel_size)

    def forward(self, x):
        return self.cam(self.sam(x) + x) + x


class SqueezeExcitation(nn.Module):
    def __init__(self, channels):
        super().__init__()
        hidden = max(1, channels // 8)
        self.squeeze = nn.AdaptiveAvgPool2d(1)
        self.excitation = nn.Sequential(nn.Linear(channels, hidden), nn.ReLU(inplace=True), nn.Linear(hidden, channels), nn.Sigmoid())

    def forward(self, x):
        b, c = x.shape[:2]
        excited = self.excitation(self.squeeze(x).view(b, c)).view(b, c, 1, 1)
        return x * excited + x


class Stem(nn.Module):
    """GroupNorm instead of BatchNorm (tiny batches + train/eval statistics mismatch)."""

    def __init__(self, in_channels, latent_channels):
        super().__init__()
        mid = max(8, latent_channels // 2)
        self.conv1 = nn.Conv2d(in_channels, mid, kernel_size=3, stride=1, padding=1)
        self.norm1 = nn.GroupNorm(num_groups(mid), mid)
        self.conv2 = nn.Conv2d(mid, latent_channels, kernel_size=3, stride=1, padding=1)
        self.norm2 = nn.GroupNorm(num_groups(latent_channels), latent_channels)
        self.act = nn.ReLU()

    def forward(self, x):
        x = self.act(self.norm1(self.conv1(x)))
        return self.act(self.norm2(self.conv2(x)))


class ResBlock(nn.Module):
    def __init__(self, channel_in, channel_out, kernel_size=3, num_features=128, clock_dim=32):
        super().__init__()
        self.norm1 = ClockModulatedNorm2d(channel_in, num_features, clock_dim)
        self.conv1 = nn.Conv2d(channel_in, channel_in, kernel_size, 1, kernel_size // 2)
        self.norm2 = ClockModulatedNorm2d(channel_in, num_features, clock_dim)
        self.conv2 = nn.Conv2d(channel_in, channel_out, kernel_size, 1, kernel_size // 2)
        self.conv3 = nn.Conv2d(channel_in, channel_out, 1) if channel_in != channel_out else None
        self.act_fnc = nn.ELU()

    def forward(self, x_in, cond: Cond):
        x = self.act_fnc(self.norm1(x_in, cond))
        skip = self.conv3(x) if self.conv3 is not None else x_in
        x = self.act_fnc(self.norm2(self.conv1(x), cond))
        return self.conv2(x) + skip


class DownBlock(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size=3, num_features=128, clock_dim=32):
        super().__init__()
        self.norm1 = ClockModulatedNorm2d(in_channels, num_features, clock_dim)
        self.conv1 = nn.Conv2d(in_channels, out_channels, kernel_size, 2, kernel_size // 2)
        self.norm2 = ClockModulatedNorm2d(out_channels, num_features, clock_dim)
        self.conv2 = nn.Conv2d(out_channels, out_channels, kernel_size, 1, kernel_size // 2)
        self.conv3 = nn.Conv2d(in_channels, out_channels, kernel_size, 2, kernel_size // 2)
        self.act_fnc = nn.LeakyReLU(0.2)

    def forward(self, x, cond):
        x = self.act_fnc(self.norm1(x, cond))
        s = self.conv3(x)
        x = self.act_fnc(self.norm2(self.conv1(x), cond))
        return self.conv2(x) + s


class UpBlock(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size=3, scale_factor=2, num_features=128, clock_dim=32):
        super().__init__()
        self.norm1 = ClockModulatedNorm2d(in_channels, num_features, clock_dim)
        self.conv1 = nn.Conv2d(in_channels, in_channels, kernel_size, 1, kernel_size // 2)
        self.norm2 = ClockModulatedNorm2d(in_channels, num_features, clock_dim)
        self.conv2 = nn.Conv2d(in_channels, out_channels, kernel_size, 1, kernel_size // 2)
        self.conv3 = nn.Conv2d(in_channels, out_channels, kernel_size, 1, kernel_size // 2)
        self.up_nn = nn.Upsample(scale_factor=scale_factor, mode="bicubic", align_corners=False)
        self.act_f = nn.LeakyReLU(0.2)

    def forward(self, x, cond):
        x = self.up_nn(self.act_f(self.norm1(x, cond)))
        s = self.conv3(x)
        x = self.act_f(self.norm2(self.conv1(x), cond))
        return self.conv2(x) + s


class DenseBlock(nn.Module):
    def __init__(self, in_channels, growth_rate, kernel_size=3, num_features=128, clock_dim=32, num_layers=4):
        super().__init__()
        self.layers = nn.ModuleList([
            ResBlock(in_channels + growth_rate * i, growth_rate, kernel_size, num_features, clock_dim) for i in range(num_layers)
        ])

    def forward(self, x, cond):
        feats = [x]
        for layer in self.layers:
            feats.append(layer(torch.cat(feats, dim=1), cond))
        return torch.cat(feats, dim=1)


class TransitionBlock(nn.Module):
    def __init__(self, in_channels, out_channels):
        super().__init__()
        self.conv = nn.Sequential(nn.GroupNorm(num_groups(in_channels), in_channels), nn.ReLU(inplace=True),
                                  nn.Conv2d(in_channels, out_channels, kernel_size=1))

    def forward(self, x):
        return self.conv(x)


class DCNet(nn.Module):
    def __init__(self, in_channels, growth_rate=32, kernel_size=3, num_features=128, clock_dim=32, num_layers=4):
        super().__init__()
        self.dense_block = DenseBlock(in_channels, growth_rate, kernel_size, num_features, clock_dim, num_layers)
        self.trans_block = TransitionBlock(in_channels + growth_rate * num_layers, in_channels)

    def forward(self, x, cond):
        return self.trans_block(self.dense_block(x, cond)) + x


class EncoderBlock(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size=3, num_features=128, clock_dim=32, growth_rate=32, num_layers=2):
        super().__init__()
        self.se = SqueezeExcitation(in_channels)
        self.down = DownBlock(in_channels, out_channels, kernel_size, num_features, clock_dim)
        self.cond = DCNet(out_channels, growth_rate, kernel_size, num_features, clock_dim, num_layers)
        self.res = ResBlock(out_channels, out_channels, 3, num_features, clock_dim)

    def forward(self, x, cond):
        x = self.down(self.se(x), cond)
        x = self.cond(x, cond)
        return self.res(x, cond)


class Encoder(nn.Module):
    def __init__(self, base_channels, num_features=128, clock_dim=32):
        super().__init__()
        b = base_channels
        self.block1 = EncoderBlock(b, b * 2, 5, num_features, clock_dim)  # H/2
        self.block2 = EncoderBlock(b * 2, b * 4, 3, num_features, clock_dim)  # H/4
        self.block3 = EncoderBlock(b * 4, b * 8, 5, num_features, clock_dim)  # H/8
        self.convo = ResBlock(b * 8, num_features, 3, num_features, clock_dim)

    def forward(self, x, cond):
        s1 = self.block1(x, cond)
        s2 = self.block2(s1, cond)
        s3 = self.block3(s2, cond)
        return self.convo(s3, cond), {"block1": s1, "block2": s2, "block3": s3}


class DecoderUpBlock(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size=3, num_features=128, clock_dim=32):
        super().__init__()
        self.bam = BAM(in_channels)
        self.up = UpBlock(in_channels, out_channels, kernel_size, 2, num_features, clock_dim)

    def forward(self, x, cond):
        return self.up(self.bam(x), cond)


class DecoderConvBlock(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size=3, num_features=128, clock_dim=32):
        super().__init__()
        self.se = SqueezeExcitation(in_channels)
        self.res = ResBlock(in_channels, out_channels, kernel_size, num_features, clock_dim)

    def forward(self, x, cond):
        return self.res(self.se(x), cond)


# ------------------------------------ 5.5 Clock-Aware Spectral Gate  [N3] ------------------------------------


class ClockAwareSpectralGate(nn.Module):
    """
    Feature-space inverse-heat filter conditioned on the clock:
        log G_c(w) = ceil_c * tanh(a_c * s_f^2 |w|^2 / (2 ceil_c))  +  tanh(MLP(|w|, 1 - K(w), heat))
    where s_f = sigma_bar / downscale is the blur std *at this feature resolution* and K the
    heat transfer function. The first term is a bounded, partial inversion of the physical
    blur (a_c in (0, 1) learned per channel); the second is a learned residual spectral
    response. Output is spatially gated by the clock embedding and added residually
    (zero-initialised projection -> identity at init).
    """

    def __init__(self, channels: int, clock_dim: int, downscale: int, hidden: int = 32, init_log_ceiling: float = 1.5):
        super().__init__()
        self.downscale = downscale
        self.alpha = nn.Parameter(torch.full((channels,), -1.0))
        self.ceiling = nn.Parameter(torch.full((channels,), init_log_ceiling))
        self.freq_mlp = nn.Sequential(nn.Linear(3, hidden), nn.SiLU(), nn.Linear(hidden, channels))
        nn.init.zeros_(self.freq_mlp[-1].weight)
        nn.init.zeros_(self.freq_mlp[-1].bias)
        self.proj = nn.Conv2d(channels, channels, 1)
        nn.init.zeros_(self.proj.weight)
        nn.init.zeros_(self.proj.bias)
        self.gate = nn.Conv2d(clock_dim, channels, 1)

    def log_gain(self, sigma_feat: torch.Tensor, h: int, w: int) -> torch.Tensor:
        w2 = HeatKernel.omega_sq(h, w, sigma_feat.device)
        heat = 0.5 * sigma_feat.float().view(-1, 1, 1, 1) ** 2 * w2  # (B, 1, 2h, w+1)
        a = torch.sigmoid(self.alpha).view(1, -1, 1, 1)
        ceil = F.softplus(self.ceiling).view(1, -1, 1, 1)
        phys = ceil * torch.tanh(a * heat / ceil)  # smooth, bounded partial inverse heat
        feat = torch.stack([w2.sqrt().expand_as(heat[:, 0]) / math.pi, 1 - torch.exp(-heat[:, 0]),
                            torch.tanh(heat[:, 0] / 4)], dim=-1)
        learned = torch.tanh(self.freq_mlp(feat)).permute(0, 3, 1, 2)
        return phys + learned

    def forward(self, x, cond: Cond):
        B, C, h, w = x.shape
        with autocast_off(x.device.type):
            sig = cond.sigma_bar.float() / self.downscale
            y = HeatKernel.inverse(HeatKernel.spectrum(x.float()) * torch.exp(self.log_gain(sig, h, w).float()), h, w)
        y = self.proj(y.to(x.dtype))
        cm_ = cond.cmap_at(h, w)
        g = torch.sigmoid(self.gate(cm_)) if cm_ is not None else 0.5
        return x + g * y


# ------------------------------------ 5.6 bottleneck / decoder / ViTAL ------------------------------------


class ColdDiffusionBlock(nn.Module):
    """Cold-diffusion bottleneck: clock-modulated norm -> Swin blocks -> spectral gate -> norm."""

    def __init__(self, dim, num_features, clock_dim, num_heads, window_size, mlp_ratio=4.0, num_blocks=2,
                 use_gate=True, downscale=8, drop_path=0.1, drop=0.0):
        super().__init__()
        self.window_size = to_2tuple(window_size)
        self.norm = ClockModulatedNorm2d(dim, num_features, clock_dim)
        self.swin_blocks = nn.ModuleList([
            SwinTransformerBlock(dim=dim, num_heads=num_heads, window_size=window_size,
                                 shift_size=0 if i % 2 == 0 else window_size // 2,  # W-MSA then SW-MSA
                                 mlp_ratio=mlp_ratio, proj_drop=drop, drop_attn=drop, drop_path=drop_path)
            for i in range(num_blocks)
        ])
        self.gate = ClockAwareSpectralGate(dim, clock_dim, downscale) if use_gate else None
        self.out_norm = ClockModulatedNorm2d(dim, num_features, clock_dim)

    def forward(self, z, cond):
        z = self.norm(z, cond)
        z = bchw_to_bhwc(z)
        for blk in self.swin_blocks:
            z = blk(z)
        z = bhwc_to_bchw(z).contiguous()
        if self.gate is not None:
            z = self.gate(z, cond)
        return self.out_norm(z, cond)


def _match(skip: torch.Tensor, ref: torch.Tensor) -> torch.Tensor:
    if skip.shape[-2:] != ref.shape[-2:]:
        skip = F.interpolate(skip, size=ref.shape[-2:], mode="bilinear", align_corners=False)
    return skip


class Decoder(nn.Module):
    """U-Net decoder with *resolution-aligned* skips (stem H, block1 H/2, block2 H/4, block3 H/8)."""

    def __init__(self, num_features, base_channels, out_channels, clock_dim=32, use_gate=True):
        super().__init__()
        b, nf, cd = base_channels, num_features, clock_dim
        self.init_proj = nn.Conv2d(nf, b * 8, kernel_size=1)
        self.block_in = ResBlock(b * 8, b * 8, 3, nf, cd)
        self.fuse4 = DecoderConvBlock(b * 8 + b * 8, b * 8, 3, nf, cd)
        self.up_block3 = DecoderUpBlock(b * 8, b * 4, 3, nf, cd)
        self.up_conv3 = DecoderConvBlock(b * 4 + b * 4, b * 4, 3, nf, cd)
        self.gate3 = ClockAwareSpectralGate(b * 4, cd, downscale=4) if use_gate else None
        self.up_block2 = DecoderUpBlock(b * 4, b * 2, 5, nf, cd)
        self.up_conv2 = DecoderConvBlock(b * 2 + b * 2, b * 2, 5, nf, cd)
        self.up_block1 = DecoderUpBlock(b * 2, b, 3, nf, cd)
        self.up_conv1 = DecoderConvBlock(b + b, b, 3, nf, cd)
        self.refine = DCNet(b, growth_rate=16, kernel_size=5, num_features=nf, clock_dim=cd, num_layers=4)
        self.output = nn.Conv2d(b, out_channels, 3, 1, 1)
        nn.init.zeros_(self.output.weight)  # x0_hat = x_t at initialisation (residual form)
        nn.init.zeros_(self.output.bias)

    def forward(self, x, skips, cond):
        x = self.block_in(self.init_proj(x), cond)
        x = self.fuse4(torch.cat([x, _match(skips["block3"], x)], 1), cond)
        x = self.up_block3(x, cond)
        x = self.up_conv3(torch.cat([x, _match(skips["block2"], x)], 1), cond)
        if self.gate3 is not None:
            x = self.gate3(x, cond)
        x = self.up_block2(x, cond)
        x = self.up_conv2(torch.cat([x, _match(skips["block1"], x)], 1), cond)
        x = self.up_block1(x, cond)
        x = self.up_conv1(torch.cat([x, _match(skips["stem"], x)], 1), cond)
        x = self.refine(x, cond)
        return self.output(x)


class ViTAL(nn.Module):
    """
    ViTAL restoration backbone (no VQ) conditioned on a per-pixel clock field.
    Inputs : x_t, tau(x), sigma_bar, degradation type, optional self-conditioning x0 estimate.
    Outputs: x0_hat (residual form) and a per-pixel Laplace log-scale (aleatoric uncertainty).
    """

    def __init__(self, in_channels=3, dim=48, num_heads=8, window_size=8, num_features=128, clock_dim=32,
                 swin_blocks=2, self_condition=True, predict_uncertainty=True, use_spectral_gate=True,
                 with_residual=True, n_types=len(KINDS), drop_path=0.1, drop=0.0, num_timesteps=1000):
        super().__init__()
        self.in_channels = in_channels
        self.self_condition = self_condition
        self.predict_uncertainty = predict_uncertainty
        self.with_residual = with_residual
        nf = num_features
        self.time_mlp = nn.Sequential(TimePosEmbedding(nf, scale=num_timesteps), nn.Linear(nf, 2 * nf), nn.GELU(),
                                      nn.Linear(2 * nf, nf), nn.GELU())
        self.spread_mlp = nn.Sequential(nn.Linear(1, nf), nn.GELU(), nn.Linear(nf, nf))
        self.type_emb = nn.Embedding(n_types, nf)
        nn.init.zeros_(self.type_emb.weight)
        self.clock_embed = ClockEmbedding(clock_dim)
        stem_in = in_channels * (2 if self_condition else 1) + 1
        self.inp = Stem(stem_in, dim)
        self.enc = Encoder(dim, nf, clock_dim)
        self.trans = ColdDiffusionBlock(nf, nf, clock_dim, num_heads, window_size, 4.0, swin_blocks,
                                        use_spectral_gate, downscale=8, drop_path=drop_path, drop=drop)
        self.dec = Decoder(nf, dim, in_channels * (2 if predict_uncertainty else 1), clock_dim, use_spectral_gate)

    @classmethod
    def from_config(cls, cfg: Config) -> "ViTAL":
        return cls(in_channels=cfg.in_channels, dim=cfg.dim, num_heads=cfg.num_heads, window_size=cfg.window_size,
                   num_features=cfg.num_features, clock_dim=cfg.clock_embed_dim, swin_blocks=cfg.swin_blocks,
                   self_condition=cfg.self_condition, predict_uncertainty=cfg.predict_uncertainty,
                   use_spectral_gate=cfg.use_spectral_gate, with_residual=cfg.with_residual,
                   drop_path=cfg.swin_drop_path, drop=cfg.swin_drop, num_timesteps=cfg.num_timesteps)

    def forward(self, x, tau_map, sigma_bar, kind=None, self_cond=None):
        flat = tau_map.flatten(1).float()
        feats = self.time_mlp(flat.mean(1)) + self.spread_mlp(flat.std(1, unbiased=False).unsqueeze(-1))
        if kind is not None:
            feats = feats + self.type_emb(kind)
        cond = Cond(feats, self.clock_embed(tau_map.float()), sigma_bar)
        parts = [x]
        if self.self_condition:
            parts.append(self_cond if self_cond is not None else torch.zeros_like(x))
        parts.append(tau_map.to(x.dtype) * 2 - 1)
        h0 = self.inp(torch.cat(parts, 1))
        latent, skips = self.enc(h0, cond)
        skips["stem"] = h0
        latent = self.trans(latent, cond)
        out = self.dec(latent, skips, cond).float()
        C = self.in_channels
        x0 = x.float() + out[:, :C] if self.with_residual else out[:, :C]
        log_scale = out[:, C:2 * C].clamp(-7.0, 2.0) if self.predict_uncertainty else None
        return {"x0": x0, "log_scale": log_scale}


# ------------------------------------ 5.7 Spectral Clock Estimator  [N1] ------------------------------------


class _DilatedResBlock(nn.Module):
    def __init__(self, c, d):
        super().__init__()
        self.conv1 = nn.Conv2d(c, c, 3, 1, d, dilation=d)
        self.n1 = nn.GroupNorm(num_groups(c), c)
        self.conv2 = nn.Conv2d(c, c, 3, 1, 1)
        self.n2 = nn.GroupNorm(num_groups(c), c)

    def forward(self, x):
        return x + self.n2(self.conv2(F.silu(self.n1(self.conv1(x)))))


class SpectralClockEstimator(nn.Module):
    """
    Blind estimator of the per-pixel clock tau(x) (and of the degradation type).

    Physics features: band-pass (difference-of-heat) energies of the luminance at scales
    s_j and their log-ratios. Under Gaussian blur sigma, band j is attenuated by roughly
    exp(-sigma^2 w_j^2), so log E_j - log E_{j+1} is (locally) *linear in sigma^2*: the
    clock can be read off the spectrum slope. A small dilated CNN turns these into
    (mu, log-scale) of a Laplace distribution over tau; flat regions (no spectral evidence)
    get a large scale and are filled by confidence-weighted normalised convolution.
    """

    def __init__(self, in_channels=3, hidden=32, bands=(0.5, 1.0, 2.0, 4.0, 8.0), n_types=len(KINDS), window=15):
        super().__init__()
        self.bands = tuple(float(b) for b in bands)
        self.window = int(window) | 1
        J = len(self.bands)
        c_in = in_channels + 2 * J - 1
        h = hidden
        self.body = nn.Sequential(
            nn.Conv2d(c_in, h, 3, 1, 1), nn.GroupNorm(num_groups(h), h), nn.SiLU(),
            nn.Conv2d(h, h, 3, 2, 1), nn.GroupNorm(num_groups(h), h), nn.SiLU(),
            nn.Conv2d(h, 2 * h, 3, 2, 1), nn.GroupNorm(num_groups(2 * h), 2 * h), nn.SiLU(),
            _DilatedResBlock(2 * h, 1), _DilatedResBlock(2 * h, 2), _DilatedResBlock(2 * h, 4), _DilatedResBlock(2 * h, 8),
        )
        self.head = nn.Conv2d(2 * h, 2, 3, 1, 1)
        self.type_head = nn.Sequential(nn.AdaptiveAvgPool2d(1), nn.Flatten(), nn.Linear(2 * h, h), nn.SiLU(), nn.Linear(h, n_types))

    def physics_features(self, x: torch.Tensor) -> torch.Tensor:
        with autocast_off(x.device.type):
            lum = x.float().mean(1, keepdim=True)
            h, w = lum.shape[-2:]
            L = HeatKernel.spectrum(lum)
            levels = [lum] + [HeatKernel.inverse(L * HeatKernel.transfer(s, h, w, x.device), h, w) for s in self.bands]
            energies = []
            for j in range(len(self.bands)):
                band = levels[j] - levels[j + 1]
                e = F.avg_pool2d(band ** 2, self.window, 1, self.window // 2, count_include_pad=False)
                energies.append(torch.log(e + 1e-6))
            slopes = [energies[j] - energies[j + 1] for j in range(len(energies) - 1)]
            return torch.cat([(e + 7.0) / 4.0 for e in energies] + slopes, 1)

    def forward(self, x: torch.Tensor) -> Dict[str, torch.Tensor]:
        H, W = x.shape[-2:]
        phys = self.physics_features(x)
        h = self.body(torch.cat([x.float(), phys], 1))
        out = F.interpolate(self.head(h).float(), size=(H, W), mode="bilinear", align_corners=False)
        return {"tau_mu": torch.sigmoid(out[:, :1]), "tau_logscale": out[:, 1:2].clamp(-7.0, 2.0),
                "type_logits": self.type_head(h).float(), "physics": phys}

    @staticmethod
    def smooth(tau_mu: torch.Tensor, logscale: torch.Tensor, sigma: float) -> torch.Tensor:
        """Confidence-propagated clock: blur(c * mu) / blur(c), c = 1/scale (normalised convolution)."""
        conf = torch.exp(-logscale.float().clamp(-6, 4))
        num = HeatKernel.blur(tau_mu.float() * conf, sigma)
        den = HeatKernel.blur(conf, sigma)
        return (num / den.clamp_min(1e-6)).clamp(0, 1)

    @staticmethod
    @torch.no_grad()
    def blur_shape(y: torch.Tensor, sigma_hat: torch.Tensor, n_ang: int = 24) -> Tuple[torch.Tensor, torch.Tensor]:
        """
        Blind blur direction and axis ratio of an image, parameter-free.                       [N12]
        The directional decay of the power spectrum is s(phi) = u^T S u + c(content). The isotropic
        part is confounded by the image content, so the trace of S comes from the learned clock
        (sigma_hat, RMS radius) and only the deviator (anisotropy + direction) from the spectrum.
        Returns theta (B,) and rho = minor/major axis ratio (B,).
        """
        s_bar = sigma_hat.float().clamp_min(0.3)
        r_max = (math.sqrt(3.0) / s_bar).clamp(0.05 * math.pi, 0.7 * math.pi)  # ~3 nepers of decay (tuned on photos)
        P = _hann_power(y)
        r, _ = _polar(*P.shape[-2:], y.device)
        floor = P.flatten(1)[:, (r.flatten() > 0.85 * math.pi)].median(1).values.view(-1, 1, 1)
        P = (P - floor).clamp_min(1e-3 * floor + 1e-12)
        s, ctr = directional_decay(P, torch.stack([0.2 * r_max, r_max], 1), n_ang=n_ang)
        _, dev_amp, theta = orientation_from_decay(s, ctr)
        l1 = s_bar ** 2 + dev_amp
        l2 = (s_bar ** 2 - dev_amp).clamp_min(0.0)
        return theta, torch.sqrt(l2 / l1)


# ------------------------------------ 5.8 Cold diffusion wrapper ------------------------------------


class ColdDiffusionModel(nn.Module):
    """
    Clock-Field Cold Diffusion around the ViTAL backbone.

        forward process  : x_tau = D(x0, tau(x))                 (deterministic, continuous tau)
        network          : x0_hat, log b = R(x_tau, tau, kind, x0_prev)
        samplers         : 'direct' (1 step), 'naive' (Alg. 1), 'improved' (Alg. 2),
                           'srn' (Alg. 2 + spectral range-null anchoring, [N2])
        blind mode       : tau_obs(x) from the Spectral Clock Estimator     [N1]
        generation       : degraded-prior bank + srn sampler                [N8]
    """

    def __init__(self, model: ViTAL, cfg: Config):
        super().__init__()
        self.model = model
        self.cfg = cfg
        self.degradation_type = cfg.degradation_type
        self.num_timesteps = cfg.num_timesteps
        self.schedule_type = cfg.schedule_type
        self.degradation = ColdDegradation(cfg)
        self.clock_estimator = SpectralClockEstimator(cfg.in_channels, cfg.clock_hidden, cfg.clock_bands, len(KINDS), cfg.clock_window)
        self.pad_multiple = 8
        D = cfg.in_channels * cfg.prior_res ** 2
        self.register_buffer("prior_mean", torch.zeros(D))
        self.register_buffer("prior_factor", torch.zeros(D, D))
        self.register_buffer("prior_ready", torch.zeros(1))

    # ---- sampling of training conditions -------------------------------------------------
    def sample_kind(self, B: int, device, generator=None) -> torch.Tensor:
        if self.cfg.degradation_type == "mixed":
            return (_rand((B,), device, generator) * len(KINDS)).long().clamp(max=len(KINDS) - 1)
        if self.cfg.degradation_type == "allinone":
            ids = torch.tensor([KINDS.index(k) for k in self.cfg.allinone_kinds], device=device)
            p = torch.tensor(self.cfg.allinone_probs, dtype=torch.float32)
            cdf = (p.cumsum(0) / p.sum()).tolist()
            u = _rand((B,), device, generator)
            j = torch.zeros(B, dtype=torch.long, device=device)
            for c in cdf[:-1]:
                j = j + (u > c).long()
            return ids[j]
        return torch.full((B,), KINDS.index(self.cfg.degradation_type), dtype=torch.long, device=device)

    def _random_field(self, n, H, W, device, generator=None) -> torch.Tensor:
        """Smooth ('defocus-like') or layered ('foreground/background') field in [-1, 1]."""
        lo_r, hi_r = self.cfg.field_grid
        r = int(lo_r + _rand((1,), "cpu", generator).item() * (hi_r - lo_r + 1))
        r = int(min(max(r, 2), max(hi_r, 2)))
        f = F.interpolate(_randn((n, 1, r, r), device, generator), size=(H, W), mode="bicubic", align_corners=False)
        layered = _rand((n, 1, 1, 1), device, generator) < 0.5
        sharp = 2 + 6 * _rand((n, 1, 1, 1), device, generator)
        f = torch.where(layered, torch.tanh(sharp * f), f)
        fmin = f.flatten(1).amin(1).view(-1, 1, 1, 1)
        fmax = f.flatten(1).amax(1).view(-1, 1, 1, 1)
        return 2 * (f - fmin) / (fmax - fmin).clamp_min(1e-6) - 1

    def sample_tau(self, B, H, W, device, generator=None, force_field: Optional[bool] = None) -> torch.Tensor:
        """Clock fields for training. Fixes the old 1/sigma 'importance' sampling that almost
        exclusively drew near-clean timesteps."""
        cfg = self.cfg
        u = _rand((B,), device, generator)
        if cfg.tau_sampling == "uniform":
            c = u
        else:
            ln = torch.sigmoid(cfg.logit_mean + cfg.logit_std * _randn((B,), device, generator))
            c = ln if cfg.tau_sampling == "logit_normal" else torch.where(_rand((B,), device, generator) < 0.5, u, ln)
        c = c.clamp(0, 1)
        tau = c.view(B, 1, 1, 1).expand(B, 1, H, W).clone()
        if force_field is None:
            sel = _rand((B,), device, generator) < cfg.field_prob
        else:
            sel = torch.full((B,), bool(force_field), device=device)
        if bool(sel.any()):
            n = int(sel.sum())
            f = self._random_field(n, H, W, device, generator)
            amp = cfg.field_spread * (0.2 + 0.8 * _rand((n,), device, generator))
            tau[sel] = (c[sel].view(-1, 1, 1, 1) + amp.view(-1, 1, 1, 1) * f).clamp(0, 1)
        return tau

    # ---- network call ----------------------------------------------------------------------
    def sigma_bar(self, tau: torch.Tensor, kind: torch.Tensor) -> torch.Tensor:
        return self.degradation.sigma(tau.float()).flatten(1).mean(1) * (kind == BLUR).float()

    def denoise(self, x_t, tau, kind, self_cond=None) -> Dict[str, torch.Tensor]:
        B, C, H, W = x_t.shape
        if tau.dim() == 1:
            tau = tau.view(B, 1, 1, 1).expand(B, 1, H, W)
        m = self.pad_multiple
        ph, pw = (m - H % m) % m, (m - W % m) % m

        def pad(t, mode="reflect"):
            return F.pad(t, (0, pw, 0, ph), mode=mode) if (ph or pw) else t

        sc = pad(self_cond) if (self_cond is not None and self.cfg.self_condition) else None
        out = self.model(pad(x_t), pad(tau.float(), "replicate"), self.sigma_bar(tau, kind), kind, sc)
        return {k: (v[..., :H, :W] if isinstance(v, torch.Tensor) and v.dim() == 4 else v) for k, v in out.items()}

    def forward(self, x_t, tau, kind, self_cond=None):
        return self.denoise(x_t, tau, kind, self_cond)

    def estimate_clock(self, y: torch.Tensor, smooth_sigma: Optional[float] = None) -> Dict[str, torch.Tensor]:
        est = self.clock_estimator(y)
        s = self.cfg.clock_smooth_sigma if smooth_sigma is None else smooth_sigma
        scale = est["tau_logscale"].float().exp()
        if s > 0:
            est["tau_smooth"] = SpectralClockEstimator.smooth(est["tau_mu"], est["tau_logscale"], s)
            est["scale_smooth"] = SpectralClockEstimator.smooth(scale, est["tau_logscale"], s)
        else:
            est["tau_smooth"], est["scale_smooth"] = est["tau_mu"], scale
        # Risk-averse clock: over-estimating the blur causes ringing / hallucination, under-estimating
        # only leaves residual blur -> use a lower confidence bound of the Laplace posterior.
        est["tau_lcb"] = (est["tau_smooth"] - self.cfg.blind_clock_margin * est["scale_smooth"]).clamp(0, 1)
        return est

    # ---- sampler building blocks -------------------------------------------------------------
    def cold_step(self, x_t, x0_hat, t_map, s_map, kind, state, gate: Optional[torch.Tensor] = None) -> torch.Tensor:
        """
        Bansal et al. Algorithm 2 generalised to clock fields:
            x_s = x_t - D(x0_hat, t) + D(x0_hat, s).
        For noise-type samples the noise realisation is re-estimated from the current state
        (eps_hat = (x_t - x0_hat)/n_t, i.e. DDIM) - it is *never* taken from ground truth,
        which would leak x0. The same holds for blur samples carrying clock-tied noise [N10]:
        eps_hat = (x_t - K_t x0_hat) / (eta t). With a small eta this also *anneals* whatever the
        operator does not explain (real noise, kernel mismatch) by the factor s/t per step, instead
        of adding it back to the output as plain Algorithm 2 does [N12].
        gate (B,) bool: blur samples whose residual goes through the Residual Spectral Gate [N13]:
            x_s = K_s x0_hat + G r + (s/t) (1 - G) r,   r = x_t - K_t x0_hat.
        """
        st = dict(state)
        if gate is not None:
            gate = gate & (kind == BLUR)
        if gate is not None and bool(gate.any()):
            out = self.cold_step(x_t, x0_hat, t_map, s_map, kind, state) if not bool(gate.all()) else x_t
            idx = gate.nonzero(as_tuple=True)[0]
            st_b = self.degradation.blur_only({k: v[idx] for k, v in state.items()})
            xt, x0, tt, ss, kk = x_t[idx].float(), x0_hat[idx].float(), t_map[idx], s_map[idx], kind[idx]
            r = xt - self.degradation.apply(x0, tt, kk, st_b)[0]
            r_keep = residual_spectral_gate(r)
            ratio = torch.where(tt > 1e-6, ss / tt.clamp_min(1e-6), torch.zeros_like(tt))
            out = out.clone()
            out[idx] = (self.degradation.apply(x0, ss, kk, st_b)[0] + r_keep + ratio * (r - r_keep)).to(out.dtype)
            return out
        is_noise = (kind == NOISE).view(-1, 1, 1, 1)
        if bool(is_noise.any()):
            n_t = self.degradation.noise_level(t_map)
            eps_hat = (x_t - x0_hat) / n_t.clamp_min(1e-4)
            eps_hat = torch.where(n_t > 1e-4, eps_hat, st["noise"])
            st["noise"] = torch.where(is_noise, eps_hat, st["noise"])
        eta = st.get("eta")
        comp = (kind == BLUR) & (eta > 0) if eta is not None else None
        if comp is not None and bool(comp.any()):
            n_t = eta.view(-1, 1, 1, 1) * t_map.clamp(0, 1)
            k_t, _ = self.degradation.apply(x0_hat, t_map, kind, self.degradation.blur_only(st))
            eps_hat = (x_t - k_t) / n_t.clamp_min(1e-6)
            eps_hat = torch.where(n_t > 1e-6, eps_hat, st["noise"])
            st["noise"] = torch.where(comp.view(-1, 1, 1, 1), eps_hat, st["noise"])
        d_t, _ = self.degradation.apply(x0_hat, t_map, kind, st)
        d_s, _ = self.degradation.apply(x0_hat, s_map, kind, st)
        return x_t - d_t + d_s

    def range_null(self, x0_hat, y, tau_obs, kind, state, eta: float, lam: float,
                   tau_unc: Optional[torch.Tensor] = None, mu: Optional[torch.Tensor] = None,
                   gate: bool = False) -> torch.Tensor:
        """Spectral range-null anchoring of x0_hat to the observation y.   [N2]
        tau_unc (B,): clock uncertainty of an estimated operator -> operator-uncertainty Wiener [N12].
        gate: the blur residual goes through the Residual Spectral Gate first (white noise removed) [N13]."""
        if eta <= 0:
            return x0_hat
        deg = self.degradation
        out = x0_hat.clone()
        for k_idx, name in enumerate(KINDS):
            sel = kind == k_idx
            if name == "noise" or not bool(sel.any()):
                continue
            idx = sel.nonzero(as_tuple=True)[0]
            xs, ys, ts = x0_hat[idx], y[idx], tau_obs[idx]
            st = {k: v[idx] for k, v in state.items()}
            ks = kind[idx]
            if name == "mask":  # exact projection: observed pixels are the range space
                corr = (st["rank"] >= deg.mask_ratio(ts)).float() * (ys - xs)
            elif name == "downsample":  # iterative back-projection
                corr = ys - deg.apply(xs, ts, ks, st)[0]
            else:  # blur family: Wiener range-space pseudo-inverse (noise stays in the residual -> lam)
                st_b = deg.blur_only(st)
                r0 = ys - deg.apply(xs, ts, ks, st_b)[0]
                if gate:
                    r0 = residual_spectral_gate(r0)
                corr = deg.wiener_backproject(r0, ts, lam, st_b, tau_unc[idx] if tau_unc is not None else None,
                                              mu[idx] if mu is not None else None)
                rot = (st_b["shape"] != ISO) if "shape" in st_b else torch.zeros(len(idx), dtype=torch.bool, device=y.device)
                if bool(rot.any()):
                    # Rotated kernels + reflective (mirror) boundaries are not diagonal in the Fourier basis, so
                    # the Wiener step is only an approximate inverse and, repeated over the sampler steps, can
                    # amplify errors. The residual-optimal step length alpha = <r, Ac>/|Ac|^2 (clamped to [0, 1])
                    # guarantees |y - A x| never increases. Isotropic blur keeps the exact update (alpha = 1).
                    Ac = deg.apply(corr, ts, ks, st_b)[0]
                    alpha = ((r0 * Ac).flatten(1).sum(1) / (Ac * Ac).flatten(1).sum(1).clamp_min(1e-12)).clamp(0, 1)
                    corr = corr * torch.where(rot, alpha, torch.ones_like(alpha)).view(-1, 1, 1, 1)
            out[idx] = xs + eta * corr
        return out

    # ---- restoration ---------------------------------------------------------------------------
    @torch.no_grad()
    def restore(self, y: torch.Tensor, tau_obs: Optional[torch.Tensor] = None, kind: Optional[torch.Tensor] = None,
                steps: Optional[int] = None, sampler: Optional[str] = None, strength: float = 1.0,
                churn: Optional[float] = None, eta: Optional[float] = None, lam: Optional[float] = None,
                record: bool = False, observed: Optional[torch.Tensor] = None, generator=None,
                x0_gt: Optional[torch.Tensor] = None, op_state: Optional[Dict[str, torch.Tensor]] = None,
                residual_gate: Optional[bool] = None) -> Dict[str, Any]:
        """
        Restore observations y (B, C, H, W) in [-1, 1].
        tau_obs=None -> blind: the clock field is estimated (Spectral Clock Estimator) and
        multiplied by `strength` (user control of the restoration strength); the blur direction
        and axis ratio come from the spectrum [N12] and the unexplained residual is annealed.
        op_state: exact operator of a synthetic observation (blur shape, direction, noise share).
        Synchronised Field Descent: tau_k(x) = tau_obs(x) * (1 - k/K)^rho for all pixels.
        """
        cfg = self.cfg
        sampler = sampler or cfg.sampler
        churn = cfg.churn if churn is None else churn
        eta = cfg.rn_eta if eta is None else eta
        blind = tau_obs is None
        if lam is None:  # an *estimated* operator is uncertain -> stronger Wiener regularisation
            lam = cfg.rn_lambda_real if blind else cfg.rn_lambda
        y = y.float()
        B, C, H, W = y.shape
        info: Dict[str, Any] = {}
        est = None
        if tau_obs is None or kind is None:
            est = self.estimate_clock(y)
            info["clock"] = {k: v for k, v in est.items() if k != "physics"}
        if kind is None:
            ok = allowed_kinds(cfg)
            if len(ok) > 1:  # type head restricted to the kinds that were trained
                logits = est["type_logits"].clone()
                mask = torch.full_like(logits, float("-inf"))
                mask[:, ok] = 0.0
                probs = (logits + mask).softmax(1)
                kind = probs.argmax(1)
                if BLUR in ok:  # blur (incl. blur + noise) unless the type head is confident about another kind
                    unsure = (kind != BLUR) & (probs.max(1).values < cfg.blind_kind_min_prob)
                    kind = torch.where(unsure, torch.full_like(kind, BLUR), kind)
                info["type_probs"] = probs
            else:
                kind = torch.full((B,), ok[0], dtype=torch.long, device=y.device)
        if tau_obs is None:
            tau_obs = (est["tau_lcb"] * strength).clamp(0, 1)
        elif tau_obs.dim() == 1:
            tau_obs = tau_obs.view(B, 1, 1, 1).expand(B, 1, H, W)
        tau_obs = tau_obs.float()
        state = self.degradation.new_state(y, generator, shape="iso")  # iso, no extra noise = pretrained operator
        state["rank"] = self.degradation.infer_rank(y, tau_obs, observed, generator)
        if op_state is not None:  # known operator (synthetic observation)
            for key in ("shape", "theta", "rho", "eta"):
                if key in op_state:
                    state[key] = op_state[key].to(y.device)
        elif blind:
            is_blur = kind == BLUR
            if bool(is_blur.any()):  # blur direction / axis ratio from the spectrum  [N12]
                s_hat = self.degradation.sigma(tau_obs).flatten(1).mean(1)
                theta, rho = SpectralClockEstimator.blur_shape(y, s_hat)
                aniso = is_blur & (rho < cfg.blind_aniso_snap)
                state["shape"] = torch.where(aniso, torch.full_like(state["shape"], ANISO), state["shape"])
                state["theta"], state["rho"] = theta, rho.clamp(cfg.aniso_min_ratio, 1.0)
                # residual annealing: real noise / kernel mismatch shrink with the clock instead of being
                # added back to the output (any eta > 0 gives the factor s/t per step)
                state["eta"] = torch.where(is_blur, torch.full_like(state["eta"], cfg.residual_anneal_floor), state["eta"])
                info["blur_shape"] = {"theta": theta, "rho": rho, "aniso": aniso}
            info["noise_sigma"] = estimate_noise_sigma(y)
        # observation noise variance (MAD) for the noise-aware Wiener anchoring
        noise_var = estimate_noise_sigma(y).pow(2) if (cfg.rn_noise_aware and sampler == "srn") else None
        # Residual Spectral Gate [N13]: keep the coloured operator-error residual, anneal the white noise
        if residual_gate is None:
            residual_gate = cfg.residual_gate == "all" or (cfg.residual_gate == "known" and not blind)
        gate_mask = torch.full((B,), bool(residual_gate), dtype=torch.bool, device=y.device)
        info["residual_gate"] = bool(residual_gate)
        # clock uncertainty of an ESTIMATED operator (Laplace scale of the estimator) -> damped anchoring [N12]
        tau_unc = None
        if blind and est is not None:
            tau_unc = (est["scale_smooth"].float() * strength).flatten(1).mean(1).clamp_min(cfg.blind_tau_unc_floor)
            info["tau_uncertainty"] = tau_unc

        K = int(steps or cfg.sample_steps)
        if sampler == "direct":
            K = 1
        elif cfg.adaptive_steps:
            K = max(min(cfg.min_steps, K), int(math.ceil(K * float(tau_obs.max().clamp(min=1e-3)))))
        u = [(1 - k / K) ** cfg.step_rho for k in range(K + 1)]

        x = y.clone()
        x0_prev, x0, log_scale = None, y.clone(), None
        traj, traj_x0, traj_tau, traj_psnr, traj_unc = [], [], [], [], []
        nonfinite_steps = 0
        for k in range(K):
            t_map, s_map = tau_obs * u[k], tau_obs * u[k + 1]
            out = self.denoise(x, t_map, kind, self_cond=x0_prev)
            x0 = out["x0"].float()
            log_scale = out["log_scale"]
            # NaN guard: a non-finite network prediction (e.g. fp16 overflow) must never poison the
            # whole trajectory -> fall back to the previous estimate (or the current state).
            if not bool(torch.isfinite(x0).all()):
                nonfinite_steps += 1
                fallback = x0_prev if x0_prev is not None else x.float().clamp(-1, 1)
                x0 = torch.where(torch.isfinite(x0), x0, fallback)
            if log_scale is not None and not bool(torch.isfinite(log_scale).all()):
                log_scale = torch.nan_to_num(log_scale.float(), nan=0.0, posinf=2.0, neginf=-7.0)
            x0 = x0.clamp(-1, 1)
            # Anchoring repeated at every step converges to the UNREGULARISED inverse y/K (lam only damps one
            # step), re-injecting observation noise / kernel errors. Schedules [N12]: 'every' step, 'final'
            # step only, or 'distributed' (a fraction (u_k - u_k+1) per step: one full correction in total).
            mode = cfg.blind_anchor if blind else cfg.anchor_schedule
            if sampler == "srn" and (mode != "final" or k == K - 1):
                eta_k = eta * (u[k] - u[k + 1]) / max(u[0] - u[K], 1e-8) if mode == "distributed" else eta
                mu = None
                if noise_var is not None:  # noise-aware Wiener: gradient prior mu |w|^2, mu = s_n^2 / var(grad x0)
                    g2 = 0.5 * ((x0[..., :, 1:] - x0[..., :, :-1]).pow(2).flatten(1).mean(1)
                                + (x0[..., 1:, :] - x0[..., :-1, :]).pow(2).flatten(1).mean(1))
                    mu = noise_var / g2.clamp_min(1e-6)
                x0 = self.range_null(x0, y, tau_obs, kind, state, eta_k, lam, tau_unc, mu,
                                     gate=bool(residual_gate)).clamp(-1, 1)
            if churn > 0 and log_scale is not None and k < K - 1:  # uncertainty-gated stochasticity [N6]
                b = log_scale.float().exp()
                uu = _rand(x0.shape, x0.device, generator) - 0.5
                x0 = (x0 - churn * u[k + 1] * b * torch.sign(uu) * torch.log1p(-2 * uu.abs().clamp(max=0.4999))).clamp(-1, 1)
            if sampler == "direct":
                x = x0
            elif sampler == "naive":  # Algorithm 1
                x = self.degradation.apply(x0, s_map, kind, state)[0]
            else:  # Algorithm 2 (+ range-null for srn), optionally with the Residual Spectral Gate [N13]
                x = self.cold_step(x, x0, t_map, s_map, kind, state, gate=gate_mask if residual_gate else None)
            x0_prev = x0
            if record:
                traj.append(x.detach().cpu())
                traj_x0.append(x0.detach().cpu())
                traj_tau.append(float(t_map.mean()))
                if log_scale is not None:
                    traj_unc.append(log_scale.float().exp().mean().item())
                if x0_gt is not None:
                    traj_psnr.append(psnr(x0, x0_gt).mean().item())
        info.update({
            "output": x.clamp(-1, 1), "x0": x0, "tau_obs": tau_obs, "kind": kind, "steps": K, "sampler": sampler,
            "nonfinite_steps": nonfinite_steps, "op_state": state,
            "uncertainty": log_scale.float().exp() if log_scale is not None else None,
            "trajectory": traj, "x0_trajectory": traj_x0, "tau_trajectory": traj_tau,
            "psnr_trajectory": traj_psnr, "uncertainty_trajectory": traj_unc,
        })
        return info

    # ---- generation from a degraded prior  [N8] -------------------------------------------------
    def generation_kind(self) -> Optional[str]:
        dt = self.cfg.degradation_type
        if dt in ("blur", "mixed") or (dt == "allinone" and "blur" in self.cfg.allinone_kinds):
            return "blur"
        if dt in ("downsample", "noise"):
            return dt
        return None  # a fully masked image carries no information to sample from

    @torch.no_grad()
    def fit_prior(self, loader, device=None, max_images: Optional[int] = None) -> bool:
        name = self.generation_kind()
        if name is None:
            print("[prior] generation is not defined for the 'mask' degradation - skipped.")
            return False
        device = device or self.prior_mean.device
        max_images = max_images or self.cfg.prior_max_images
        feats, n = [], 0
        for batch in loader:
            x = batch["image"].to(device).float()
            if name in ("blur", "downsample"):
                kind = torch.full((x.shape[0],), KINDS.index(name), dtype=torch.long, device=device)
                st = self.degradation.new_state(x, shape="iso")  # isotropic maximal blur = the prior's domain
                x, _ = self.degradation.apply(x, torch.ones(x.shape[0], device=device), kind, st)
            feats.append(F.adaptive_avg_pool2d(x, self.cfg.prior_res).flatten(1).double().cpu())
            n += x.shape[0]
            if n >= max_images:
                break
        if not feats:
            return False
        X = torch.cat(feats, 0)
        N, D = X.shape
        mu = X.mean(0)
        Xc = X - mu
        cov = Xc.T @ Xc / max(N - 1, 1)
        alpha = D / (N + D)  # shrinkage towards a scaled identity
        cov = (1 - alpha) * cov + alpha * (cov.trace() / D) * torch.eye(D, dtype=cov.dtype) + 1e-6 * torch.eye(D, dtype=cov.dtype)
        L = torch.linalg.cholesky(cov)
        self.prior_mean.copy_(mu.float().to(self.prior_mean.device))
        self.prior_factor.copy_(L.float().to(self.prior_factor.device))
        self.prior_ready.fill_(1.0)
        print(f"[prior] fitted a {D}-dim Gaussian degraded prior on {N} images ({name}).")
        return True

    @torch.no_grad()
    def generate(self, n: int, image_size: Tuple[int, int], steps: Optional[int] = None,
                 churn: Optional[float] = None, generator=None, record: bool = False) -> Dict[str, Any]:
        if float(self.prior_ready.item()) < 0.5:
            raise RuntimeError("Degraded prior not fitted - call fit_prior() first.")
        name = self.generation_kind()
        C, p = self.cfg.in_channels, self.cfg.prior_res
        dev = self.prior_mean.device
        z = self.prior_mean[None] + _randn((n, self.prior_mean.numel()), dev, generator) @ self.prior_factor.T
        x = F.interpolate(z.view(n, C, p, p), size=tuple(image_size), mode="bicubic", align_corners=False).clamp(-1, 1)
        kind = torch.full((n,), KINDS.index(name), dtype=torch.long, device=dev)
        tau = torch.ones(n, 1, *image_size, device=dev)
        st = self.degradation.new_state(x, generator, shape="iso")
        if name == "blur":
            # The prior was fitted on thumbnails of D(x0, 1), so an upsampled prior sample already IS an observation
            # at tau = 1. Applying D(., 1) again (as before) blurred it to sigma_max * sqrt(2) and started the sampler
            # outside its training distribution. Only the bicubic thumbnail grid is smoothed away (half a cell).
            cell = max(image_size) / float(p)
            x_T = HeatKernel.blur(x, min(0.5 * cell, float(self.degradation.sigma(torch.tensor(1.0)))))
        else:  # noise: the prior holds clean thumbnails -> degrade; downsample: D(., 1) is (nearly) idempotent
            x_T, _ = self.degradation.apply(x, tau, kind, st)
        res = self.restore(x_T, tau_obs=tau, kind=kind, steps=steps or self.cfg.generate_steps, sampler="srn",
                           churn=self.cfg.gen_churn if churn is None else churn, record=record, generator=generator,
                           op_state=st, residual_gate=False)  # the injected diversity noise is kept
        res["prior_sample"] = x_T
        return res


# =======================================================================================
# SECTION 6: LOSSES
# =======================================================================================


class PerceptualLoss(nn.Module):
    """Optional VGG16 feature loss (needs the torchvision weights; disabled by default)."""

    def __init__(self, layers: Sequence[int] = (3, 8, 15, 22)):
        super().__init__()
        from torchvision.models import VGG16_Weights, vgg16

        vgg = vgg16(weights=VGG16_Weights.IMAGENET1K_V1).features[: max(layers) + 1].eval()
        for p in vgg.parameters():
            p.requires_grad_(False)
        self.vgg = vgg
        self.layers = set(layers)
        self.register_buffer("mean", torch.tensor([0.485, 0.456, 0.406]).view(1, 3, 1, 1))
        self.register_buffer("std", torch.tensor([0.229, 0.224, 0.225]).view(1, 3, 1, 1))

    def forward(self, pred, target):
        x = (to01(pred) - self.mean) / self.std
        y = (to01(target) - self.mean) / self.std
        loss = 0.0
        for i, layer in enumerate(self.vgg):
            x, y = layer(x), layer(y)
            if i in self.layers:
                loss = loss + F.l1_loss(x, y)
        return loss


class ColdDiffusionLoss(nn.Module):
    """
    Full training objective of ViTAL-CF:

        L = l_rec  * Charbonnier(x0_hat, x0)
          + l_unc  * beta-Laplace NLL (scale head only, mean-decoupled)          [N6]
          + l_freq * Null-Space Spectral loss  sum_w W_tau(w) |F(x0_hat - x0)|    [N5]
          + l_cyc  * || D(x0_hat, tau) - x_tau ||_1   (re-degradation consistency)
          + l_roll * Charbonnier(R(x_s^alg2, s, sc=x0_hat), x0)                  [N4]
          + l_clk  * clock-estimator Laplace NLL + L1 + TV                       [N1]
          + l_type * CE(type)            (mixed / allinone mode)
          + l_perc * VGG perceptual      (optional)

    Synthetic samples: x_tau = D(x0, tau) with the blur family / noise [N9, N10].
    Real pairs (y_real given): x_tau = the REAL blurred photo, x0 its sharp frame, tau the
    physics-fitted clock field of the pair [N11]; the re-degradation term is skipped (a real
    blur is not exactly in the operator family), the rollout anneals the residual [N12].
    """

    def __init__(self, cfg: Config):
        super().__init__()
        self.cfg = cfg
        self.perceptual = None
        if cfg.lambda_perceptual > 0:
            try:
                self.perceptual = PerceptualLoss()
            except Exception as e:  # noqa: BLE001 (no internet on Kaggle, ...)
                print(f"[loss] perceptual loss disabled: {e}")

    @staticmethod
    def charbonnier(pred, target, eps: float = 1e-3):
        return torch.sqrt((pred.float() - target.float()) ** 2 + eps ** 2).mean()

    @staticmethod
    def beta_laplace_nll(mean, target, log_scale, beta: float = 1.0):
        """
        Laplace NLL |e|/b + log b with the error detached (the mean is trained by the
        reconstruction loss only) and beta-weighting stopgrad(b)^beta (Seitzer et al. 2022),
        which gives the well-conditioned gradient b - |e| for beta = 1.
        """
        log_scale = log_scale.float()
        b = log_scale.exp()
        err = (target.float() - mean.float()).abs().detach()
        w = b.detach() ** beta if beta > 0 else 1.0
        return (w * (err / b + log_scale)).mean()

    def null_space_spectral(self, pred, target, tau, kind, deg: ColdDegradation, state=None):
        with autocast_off(pred.device.type):
            diff = pred.float() - target.float()
            h, w = diff.shape[-2:]
            D = HeatKernel.spectrum(diff).abs() / (2.0 * math.sqrt(h * w))
            Wt = deg.annihilation_weight(tau, kind, h, w, self.cfg.nss_gamma, self.cfg.nss_floor, state)
            per = (Wt * D).flatten(1).sum(1) / (Wt.expand_as(D).flatten(1).sum(1) + 1e-8)
            return per.mean()

    @staticmethod
    def total_variation(x):
        return (x[..., 1:, :] - x[..., :-1, :]).abs().mean() + (x[..., :, 1:] - x[..., :, :-1]).abs().mean()

    def forward(self, diffusion: ColdDiffusionModel, x0: torch.Tensor, tau: Optional[torch.Tensor] = None,
                kind: Optional[torch.Tensor] = None, generator=None, rollout: Optional[bool] = None,
                y_real: Optional[torch.Tensor] = None, state: Optional[Dict[str, torch.Tensor]] = None):
        cfg = self.cfg
        x0 = x0.float()
        B, C, H, W = x0.shape
        dev = x0.device
        deg = diffusion.degradation
        real = y_real is not None
        if real:  # real blurred photo + its sharp frame  [N11]
            kind = torch.full((B,), BLUR, dtype=torch.long, device=dev)
            tau, state = deg.fit_real_pair(x0, y_real.float(), anneal_floor=max(cfg.residual_anneal_floor, 1e-6))
            x_t = y_real.float()
        else:
            if kind is None:
                kind = diffusion.sample_kind(B, dev, generator)
            if state is None:
                state = deg.new_state(x0, generator)
            if tau is None:
                tau = diffusion.sample_tau(B, H, W, dev, generator)
            elif tau.dim() == 1:
                tau = tau.view(B, 1, 1, 1).expand(B, 1, H, W).contiguous()
            tau = deg.effective_tau(tau, kind, state)  # motion streaks saturate at motion_max_len
            x_t, state = deg.apply(x0, tau, kind, state)

        # Estimator-in-the-loop conditioning [N11]: at test time the network sees the ESTIMATED clock, so part
        # of the samples are conditioned on the (detached, smoothed) estimate instead of the label.
        est = diffusion.clock_estimator(x_t.detach()) if cfg.lambda_clock > 0 else None
        tau_net = tau
        p_est = cfg.est_cond_prob_real if real else cfg.est_cond_prob_syn
        if est is not None and p_est > 0 and self.training:
            use = _rand((B,), dev, generator) < p_est
            if bool(use.any()):
                with torch.no_grad():
                    t_est = SpectralClockEstimator.smooth(est["tau_mu"].detach(), est["tau_logscale"].detach(),
                                                          cfg.clock_smooth_sigma) if cfg.clock_smooth_sigma > 0 else est["tau_mu"].detach()
                tau_net = torch.where(use.view(-1, 1, 1, 1), t_est.float(), tau)
        out = diffusion.denoise(x_t, tau_net, kind)
        x0_hat = out["x0"].float()
        logs: Dict[str, float] = {}
        total = cfg.lambda_rec * self.charbonnier(x0_hat, x0)
        logs["rec"] = F.l1_loss(x0_hat, x0).item()

        if out["log_scale"] is not None and cfg.lambda_unc > 0:
            l_unc = self.beta_laplace_nll(x0_hat, x0, out["log_scale"])
            total = total + cfg.lambda_unc * l_unc
            logs["unc"] = l_unc.item()
        if cfg.lambda_freq > 0:
            l_freq = self.null_space_spectral(x0_hat, x0, tau, kind, deg, state)
            total = total + cfg.lambda_freq * l_freq
            logs["freq"] = l_freq.item()
        if cfg.lambda_cycle > 0 and not real:
            d_hat, _ = deg.apply(x0_hat, tau, kind, state)
            l_cyc = F.l1_loss(d_hat, x_t)
            total = total + cfg.lambda_cycle * l_cyc
            logs["cycle"] = l_cyc.item()
        if self.perceptual is not None:
            l_p = self.perceptual(x0_hat, x0)
            total = total + cfg.lambda_perceptual * l_p
            logs["perceptual"] = float(l_p)

        do_roll = rollout if rollout is not None else (self.training and float(_rand((1,), "cpu", generator)) < cfg.rollout_prob)
        if do_roll and cfg.lambda_rollout > 0:
            lo, hi = cfg.rollout_delta
            delta = torch.exp(math.log(lo) + (math.log(hi) - math.log(lo)) * _rand((B,), dev, generator))
            s = tau * (1 - delta).view(-1, 1, 1, 1)
            with torch.no_grad():
                x0_sg = x0_hat.detach().clamp(-1, 1)
                x_s = diffusion.cold_step(x_t, x0_sg, tau, s, kind, state)
            out2 = diffusion.denoise(x_s, s, kind, self_cond=x0_sg)
            l_roll = self.charbonnier(out2["x0"], x0)
            if out2["log_scale"] is not None and cfg.lambda_unc > 0:
                l_roll = l_roll + cfg.lambda_unc * self.beta_laplace_nll(out2["x0"], x0, out2["log_scale"])
            total = total + cfg.lambda_rollout * l_roll
            logs["rollout"] = l_roll.item()

        if est is not None:
            mu, ls = est["tau_mu"], est["tau_logscale"]
            l_clk = self.beta_laplace_nll(mu, tau, ls) + F.l1_loss(mu, tau) + cfg.clock_tv_weight * self.total_variation(mu)
            total = total + cfg.lambda_clock * l_clk
            logs["clock"] = l_clk.item()
            logs["clock_mae"] = (mu.detach() - tau).abs().mean().item()
            if is_multi_kind(cfg) and cfg.lambda_type > 0:
                l_type = F.cross_entropy(est["type_logits"], kind)
                total = total + cfg.lambda_type * l_type
                logs["type"] = l_type.item()
                logs["type_acc"] = (est["type_logits"].argmax(1) == kind).float().mean().item()

        logs["total"] = total.item()
        with torch.no_grad():
            logs["psnr"] = psnr(x0_hat, x0).mean().item()
            logs["real_psnr" if real else "syn_psnr"] = logs["psnr"]
            if real:
                logs["real_psnr_input"] = psnr(x_t, x0).mean().item()
        extras = {"x0": x0.detach(), "x_t": x_t.detach(), "x0_hat": x0_hat.detach(), "tau": tau.detach(), "kind": kind,
                  "log_scale": out["log_scale"].detach() if out["log_scale"] is not None else None,
                  "tau_hat": est["tau_mu"].detach() if est is not None else None}
        return total, logs, extras


# =======================================================================================
# SECTION 7: METRICS
# =======================================================================================


def psnr(pred: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
    """Per-image PSNR (dB) of [-1, 1] images, computed on [0, 1]."""
    mse = ((to01(pred.float()) - to01(target.float())) ** 2).flatten(1).mean(1).clamp_min(1e-10)
    return 10 * torch.log10(1.0 / mse)


def _gaussian_window(size: int = 11, sigma: float = 1.5, channels: int = 3, device="cpu"):
    g = torch.exp(-((torch.arange(size, device=device).float() - size // 2) ** 2) / (2 * sigma ** 2))
    g = g / g.sum()
    return (g[:, None] @ g[None, :]).expand(channels, 1, size, size).contiguous()


def ssim(pred: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
    """Per-image SSIM (Wang et al. 2004), Gaussian window 11/1.5, on [0, 1]."""
    x, y = to01(pred.float()), to01(target.float())
    C = x.shape[1]
    size = min(11, min(x.shape[-2:]))
    size = size if size % 2 else size - 1
    win = _gaussian_window(max(size, 1), 1.5, C, x.device)
    c1, c2 = 0.01 ** 2, 0.03 ** 2
    mu_x, mu_y = F.conv2d(x, win, groups=C), F.conv2d(y, win, groups=C)
    sxx = F.conv2d(x * x, win, groups=C) - mu_x ** 2
    syy = F.conv2d(y * y, win, groups=C) - mu_y ** 2
    sxy = F.conv2d(x * y, win, groups=C) - mu_x * mu_y
    s = ((2 * mu_x * mu_y + c1) * (2 * sxy + c2)) / ((mu_x ** 2 + mu_y ** 2 + c1) * (sxx + syy + c2))
    return s.flatten(1).mean(1)


class LPIPSMetric:
    """LPIPS through pyiqa (optional)."""

    def __init__(self, device):
        self.metric = None
        if PYIQA_AVAILABLE:
            try:
                self.metric = pyiqa.create_metric("lpips", device=device, as_loss=False)
            except Exception as e:  # noqa: BLE001
                print(f"[metrics] LPIPS unavailable: {e}")

    @torch.no_grad()
    def __call__(self, pred, target) -> Optional[torch.Tensor]:
        if self.metric is None:
            return None
        try:
            return self.metric(to01(pred.float()), to01(target.float())).flatten().float()
        except Exception:  # noqa: BLE001
            return None


def radial_power_spectrum(x: torch.Tensor, n_bins: int = 64) -> Tuple[np.ndarray, np.ndarray]:
    """Radially averaged log power spectrum of the luminance of (C, H, W) or (1, C, H, W)."""
    if x.dim() == 4:
        x = x[0]
    lum = to01(x.float()).mean(0)
    lum = lum - lum.mean()
    H, W = lum.shape
    win = torch.hann_window(H, device=lum.device)[:, None] * torch.hann_window(W, device=lum.device)[None, :]
    P = torch.fft.fftshift(torch.fft.fft2(lum * win)).abs() ** 2
    yy, xx = torch.meshgrid(torch.arange(H, device=lum.device) - H // 2, torch.arange(W, device=lum.device) - W // 2, indexing="ij")
    r = torch.sqrt((yy.float() / (H / 2)) ** 2 + (xx.float() / (W / 2)) ** 2)  # 1 == Nyquist
    idx = torch.clamp((r / math.sqrt(2) * n_bins).long(), max=n_bins - 1).flatten()
    num = torch.zeros(n_bins, device=lum.device).index_add_(0, idx, P.flatten())
    den = torch.zeros(n_bins, device=lum.device).index_add_(0, idx, torch.ones_like(P.flatten()))
    prof = torch.log10(num / den.clamp_min(1) + 1e-12)
    freqs = (torch.arange(n_bins, device=lum.device).float() + 0.5) / n_bins * math.sqrt(2)
    return freqs.cpu().numpy(), prof.cpu().numpy()


def null_space_recovery(pred, target, degraded, tau, kind, deg: ColdDegradation, thresh: float = 0.5,
                        state: Optional[Dict[str, torch.Tensor]] = None) -> torch.Tensor:
    """
    NSR: the fraction of the *annihilated* spectral error that restoration removed:
        1 - sum_w M |F(x0_hat - x0)| / sum_w M |F(y - x0)|,   M = [1 - |K_tau|^2 > thresh]
    (1 = perfect recovery of the destroyed frequencies, 0 = no better than the input).
    """
    with autocast_off(pred.device.type):
        h, w = pred.shape[-2:]
        Wt = deg.annihilation_weight(tau, kind, h, w, 1.0, 0.0, state)
        M = (Wt > thresh).float()
        e_pred = (HeatKernel.spectrum(pred.float() - target.float()).abs() * M).flatten(1).sum(1)
        e_in = (HeatKernel.spectrum(degraded.float() - target.float()).abs() * M).flatten(1).sum(1)
        return 1 - e_pred / e_in.clamp_min(1e-8)


def pearson(a: torch.Tensor, b: torch.Tensor) -> float:
    a, b = a.flatten().float(), b.flatten().float()
    a, b = a - a.mean(), b - b.mean()
    return float((a * b).sum() / (a.norm() * b.norm() + 1e-12))


# =======================================================================================
# SECTION 8: TRAINER
# =======================================================================================


class TrainStep(nn.Module):
    """
    The whole training objective inside one forward() (multi-GPU unit of work).
    nn.DataParallel / DDP then parallelise the degradation, both network passes (incl. the SCR
    rollout), the clock estimator and every loss, not only the backbone. DDP also requires the
    gradient-producing computation to go through the wrapper's forward.
    Logs come back as 1-element tensors so DataParallel can gather them; autocast is entered
    here because DataParallel runs its replicas in threads (the autocast state is thread-local).
    """

    def __init__(self, diffusion: "ColdDiffusionModel", loss_fn: "ColdDiffusionLoss", use_amp: bool = False,
                 amp_dtype: torch.dtype = torch.float16):
        super().__init__()
        self.diffusion = diffusion
        self.loss_fn = loss_fn
        self.use_amp = use_amp
        self.amp_dtype = amp_dtype

    def forward(self, x0: torch.Tensor, rollout: bool, y_real: Optional[torch.Tensor] = None):
        """x0: clean (synthetic step) or sharp (real-pair step, y_real = the blurred photos)."""
        with torch.autocast(device_type=x0.device.type, dtype=self.amp_dtype, enabled=self.use_amp):
            total, logs, extras = self.loss_fn(self.diffusion, x0, rollout=bool(rollout), y_real=y_real)
        keys = list(logs.keys())
        vals = torch.tensor([float(logs[k]) for k in keys], dtype=torch.float32).to(total.device)
        return total.float().reshape(1), {k: vals[i:i + 1] for i, k in enumerate(keys)}, extras


class EMA:
    """Exponential moving average of the weights (with the usual warm-up of the decay)."""

    def __init__(self, model: nn.Module, decay: float = 0.999):
        self.decay = decay
        self.model = copy.deepcopy(model).eval()
        for p in self.model.parameters():
            p.requires_grad_(False)

    @torch.no_grad()
    def update(self, model: nn.Module, step: int):
        d = min(self.decay, (1 + step) / (10 + step))
        for e, m in zip(self.model.parameters(), model.parameters()):
            e.lerp_(m.detach(), 1 - d)
        for e, m in zip(self.model.buffers(), model.buffers()):
            e.copy_(m)

    def state_dict(self):
        return self.model.state_dict()

    def load_state_dict(self, sd):
        self.model.load_state_dict(sd)


def _make_grad_scaler(enabled: bool):
    try:
        return torch.amp.GradScaler("cuda", enabled=enabled)
    except (AttributeError, TypeError):
        return torch.cuda.amp.GradScaler(enabled=enabled)


PRIOR_BUFFERS = ("prior_mean", "prior_factor", "prior_ready")


class Trainer:
    """
    Training loop with: AdamW + warm-up/cosine schedule, AMP (fp16 + GradScaler on T4, bf16 on
    Ampere+), gradient accumulation and clipping, EMA, deterministic validation, automatic resumption
    from the latest checkpoint (model, EMA, optimiser, scheduler, scaler, RNG, curves),
    best-model tracking, train-vs-valid curves and periodic visual snapshots.
    Multi-GPU (Kaggle T4 x2): nn.DataParallel in a notebook, DDP under torchrun. `self.model` is
    always the plain model (checkpoints, EMA, validation); `self.train_step` is the wrapped
    training objective.
    """

    def __init__(self, model: ColdDiffusionModel, train_dataset: Dataset, val_dataset: Dataset, config: Config):
        self.cfg = cfg = config
        self.device = torch.device(cfg.device)
        self.model = model.to(self.device)
        self.train_dataset, self.val_dataset = train_dataset, val_dataset
        # ---- multi-GPU layout ----
        self.mode = parallel_mode(cfg)
        self.distributed = self.mode == "ddp"
        self.rank, self.world_size = get_rank(), get_world_size()
        self.is_main = self.rank == 0
        n_dp = torch.cuda.device_count() if self.mode == "dp" else 1
        self.n_gpus = self.world_size if self.distributed else n_dp
        per_gpu = cfg.batch_size if cfg.batch_size_per_gpu else max(1, cfg.batch_size // self.n_gpus)
        loader_bs = per_gpu * n_dp  # DataParallel splits one loader batch across the GPUs
        self.global_batch = per_gpu * self.n_gpus
        pin = self.device.type == "cuda"
        nw = cfg.num_workers
        if self.distributed:  # the CPU cores are shared by the processes
            nw = min(nw, max(1, (os.cpu_count() or 2) // self.world_size))
        # Seeded per-epoch order (sharded under DDP) -> a mid-epoch checkpoint resumes exactly.
        self.train_sampler = EpochSampler(len(train_dataset), cfg.seed, self.rank, self.world_size)
        self.loader_batch = loader_bs
        self.train_loader = DataLoader(train_dataset, batch_size=loader_bs, sampler=self.train_sampler,
                                       num_workers=nw, pin_memory=pin,
                                       drop_last=self.train_sampler.num_samples > loader_bs, persistent_workers=nw > 0)
        self.val_loader = DataLoader(val_dataset, batch_size=cfg.batch_size, shuffle=False, num_workers=nw,
                                     pin_memory=pin, persistent_workers=nw > 0)
        # ---- REAL blur->sharp pairs (training mix + per-epoch validation)  [N11] ----
        # Every phase of the start-up announces itself, so a slow step is visible instead of a silent "hang".
        t_phase = time.time()
        print(f"  [trainer] mode={self.mode}, loader batch {loader_bs}, {nw} workers; indexing real blur/sharp pairs ...")
        self.real_iter = None
        self.real_train_names: List[str] = []
        if cfg.real_pair_prob > 0:
            parts = build_real_pairs(cfg, "train", "train")  # GoPro, HIDE, RealBlur_J/R, TextOCR ... (train splits)
            if parts:
                real_ds = parts[0] if len(parts) == 1 else torch.utils.data.ConcatDataset(parts)
                # balanced per requested dataset (a plain uniform sampler let the largest set dominate)
                self.real_sampler = BalancedEpochSampler([len(p) for p in parts], [p.group for p in parts],
                                                         cfg.real_subset_balance, cfg.seed + 99991, self.rank,
                                                         self.world_size)
                n_real_workers = max(2, nw // 2) if nw > 0 else 0  # real steps decode full-size photo pairs
                self.real_loader = DataLoader(real_ds, batch_size=loader_bs, sampler=self.real_sampler,
                                              num_workers=n_real_workers, pin_memory=pin,
                                              drop_last=self.real_sampler.num_samples >= loader_bs,  # per rank
                                              persistent_workers=n_real_workers > 0)
                self.real_iter = self._real_batches()
                shares = self.real_sampler.probs.tolist()
                self.real_train_names = [f"{p.name} ({len(p)} pairs, {sh:.0%} of real steps)" for p, sh in zip(parts, shares)]
        # Real validation on EVERY real test set (fixed centre crops, spread evenly over the subsets), not just the first.
        real_val = build_real_pairs(cfg, "test", "val", max_total=cfg.real_val_images)
        real_val_ds = (real_val[0] if len(real_val) == 1 else torch.utils.data.ConcatDataset(real_val)) if real_val else None
        self.real_val_loader = (DataLoader(real_val_ds, batch_size=cfg.batch_size, shuffle=False, num_workers=0)
                                if real_val_ds is not None else None)
        self.real_val_name = "+".join(p.name for p in real_val)
        print(f"  [trainer] real pairs: train {', '.join(self.real_train_names) or 'none'} | validation "
              f"{self.real_val_name or 'none'} ({time.time() - t_phase:.1f} s); building optimiser / EMA / "
              f"{'DDP' if self.mode == 'ddp' else ('DataParallel' if self.mode == 'dp' else 'model')} ...")
        self.loss_fn = ColdDiffusionLoss(cfg).to(self.device)
        self.optimizer = optim.AdamW(self._param_groups(), lr=cfg.learning_rate, betas=tuple(cfg.betas), eps=1e-8)
        self.batches_per_epoch = len(self.train_loader)
        self.steps_per_epoch = max(1, math.ceil(len(self.train_loader) / cfg.grad_accum_steps))
        self.total_steps = max(1, cfg.epochs * self.steps_per_epoch)
        # LR schedule: warm-up + cosine. A fine-tuning request (extra_epochs) restarts it at `start` over
        # `total` steps with peak finetune_lr; the active schedule is saved in the checkpoints.
        self.sched = {"start": 0, "warmup": cfg.warmup_steps, "total": self.total_steps, "peak": 1.0}
        floor = cfg.min_lr_ratio

        def lr_lambda(step):  # closure over self.sched -> not pickled into the scheduler state
            sc = self.sched
            s = step - sc["start"]
            if s < sc["warmup"]:
                return sc["peak"] * float(s + 1) / float(max(1, sc["warmup"]))
            progress = min(1.0, float(s - sc["warmup"]) / float(max(1, sc["total"] - sc["warmup"])))
            return sc["peak"] * (floor + (1 - floor) * 0.5 * (1.0 + math.cos(math.pi * progress)))

        self.scheduler = optim.lr_scheduler.LambdaLR(self.optimizer, lr_lambda)
        self.use_amp = cfg.use_amp and self.device.type == "cuda"
        self.amp_dtype = select_amp_dtype(self.device, cfg.amp_dtype) if self.use_amp else torch.float16
        self.scaler = _make_grad_scaler(self.use_amp and self.amp_dtype == torch.float16)
        # EMA only where it is used (rank 0 validates and saves).
        self.ema = EMA(self.model, cfg.ema_decay) if (cfg.use_ema and self.is_main) else None

        # ---- wrapped training objective (DataParallel / DDP / plain) ----
        core = TrainStep(self.model, self.loss_fn, self.use_amp, self.amp_dtype)
        if self.distributed:
            # The type head of the clock estimator only receives gradients in 'mixed' mode.
            all_used = is_multi_kind(cfg) and cfg.lambda_type > 0 and cfg.lambda_clock > 0
            dev_ids = [self.device.index] if self.device.type == "cuda" else None
            self.train_step: nn.Module = DDP(core, device_ids=dev_ids, output_device=dev_ids[0] if dev_ids else None,
                                             find_unused_parameters=not all_used, broadcast_buffers=False)
        elif self.mode == "dp":
            self.train_step = nn.DataParallel(core)
        else:
            self.train_step = core

        self.current_epoch = 0
        self.global_step = 0
        self.best_metric = -float("inf")
        # The name carries the real validation set: scores of another set (e.g. the old GoPro-only one) are not
        # comparable, so a changed set resets the best score instead of blocking every new 'best'.
        self.best_metric_name = (f"real_ema_psnr[{self.real_val_name}:{len(self.real_val_loader.dataset)}]"
                                 if (cfg.select_best_by == "real" and self.real_val_loader is not None)
                                 else "synthetic_ema_psnr")
        self.history: Dict[str, List[Any]] = {"epoch": []}
        self.lr_history: List[float] = []
        self.checkpoint_dir = Path(cfg.checkpoint_dir)
        self.checkpoint_dir.mkdir(parents=True, exist_ok=True)
        self.viz_dir = Path(cfg.visualization_dir) / "training"
        self.viz_dir.mkdir(parents=True, exist_ok=True)
        # ---- Kaggle session safety ----
        budget_h = cfg.time_budget_hours
        if budget_h < 0:  # auto: Kaggle sessions stop at 12 h -> leave time to save
            budget_h = 11.0 if (os.environ.get("KAGGLE_KERNEL_RUN_TYPE") or Path("/kaggle/working").is_dir()) else 0.0
        self.time_budget_s = budget_h * 3600.0
        self.stop_requested = False
        self.training_complete = False
        self.current_epoch_trained = False
        self.epoch_samples_done = 0  # samples (all GPUs) of the current epoch already trained (mid-epoch checkpoints)
        self.resume_skip_samples = 0  # per rank, set when resuming an interrupted epoch
        self._last_ckpt_time = time.time()
        self.epoch_loop_completed = False  # the last train_epoch() ran through its whole loader (no budget stop)
        # Resume *after* every piece of state exists (the old code reset the metrics afterwards).
        self.saved_extra = None
        print("  [trainer] looking for a checkpoint to resume from ...")
        self._load_checkpoint()
        self._apply_extra_epochs()
        self.session_start_step = self.global_step
        print("  [trainer] ready.")

    def _apply_extra_epochs(self):
        """
        Config.epochs is the TOTAL number of epochs. extra_epochs > 0 trains that many epochs beyond the
        resumed checkpoint (an interrupted epoch counts as one) and, with finetune_lr_restart, restarts the
        LR schedule (warm-up + cosine over the extra epochs, peak finetune_lr). The request is saved in the
        checkpoints, so a later session continues it instead of extending it again.
        """
        cfg = self.cfg
        if cfg.extra_epochs <= 0:
            if self.saved_extra and self.saved_extra.get("target_epochs", 0) > cfg.epochs:
                cfg.epochs = int(self.saved_extra["target_epochs"])  # keep finishing an earlier request
                print(f"  continuing the fine-tuning request saved in the checkpoint: epochs -> {cfg.epochs}")
            return
        same = self.saved_extra and self.saved_extra.get("extra_epochs") == cfg.extra_epochs
        if same and cfg.new_extra_request and self.current_epoch >= int(self.saved_extra["target_epochs"]):
            same = False  # the saved request is complete -> a new one (an unfinished one is always continued)
        if same:  # the same request in a later session: continue it, do not extend again
            cfg.epochs = int(self.saved_extra["target_epochs"])
            print(f"  extra_epochs={cfg.extra_epochs}: continuing the saved request (target epoch {cfg.epochs}, "
                  f"now at epoch {self.current_epoch})")
            return
        cfg.epochs = self.current_epoch + cfg.extra_epochs
        self.saved_extra = {"extra_epochs": cfg.extra_epochs, "target_epochs": cfg.epochs}
        self.total_steps = cfg.epochs * self.steps_per_epoch
        if cfg.finetune_lr_restart:
            remaining = max(1, (cfg.epochs - self.current_epoch) * self.steps_per_epoch
                            - self.resume_skip_samples * self.world_size // max(1, self.global_batch))
            warm = min(cfg.finetune_warmup_steps, max(1, remaining // 10))  # never longer than 10% of the run
            # LambdaLR multiplies the base LR restored from the checkpoint, which differs from Config.learning_rate
            # whenever the pretrained run used another value -> the peak must be relative to that base LR.
            base_lr = float(self.scheduler.base_lrs[0]) if self.scheduler.base_lrs else cfg.learning_rate
            self.sched = {"start": self.global_step, "warmup": warm, "total": remaining,
                          "peak": cfg.finetune_lr / max(base_lr, 1e-12)}
            self.scheduler.last_epoch = self.global_step - 1
            self.scheduler.step()  # applies the new schedule now
        print(f"  extra_epochs={cfg.extra_epochs}: training epochs {self.current_epoch}..{cfg.epochs - 1} "
              f"(target epoch {cfg.epochs})" + (f"; LR schedule restarted: warm-up {self.sched['warmup']} steps, "
                                                f"peak {cfg.finetune_lr:g}, cosine over {self.sched['total']} steps"
                                                if cfg.finetune_lr_restart else ""))

    # ---- optimiser helpers ---------------------------------------------------------------
    def _param_groups(self):
        decay, no_decay = [], []
        for n, p in self.model.named_parameters():
            if not p.requires_grad:
                continue
            if p.ndim <= 1 or n.endswith(".bias") or "emb" in n or "logit_scale" in n:
                no_decay.append(p)
            else:
                decay.append(p)
        return [{"params": decay, "weight_decay": self.cfg.weight_decay}, {"params": no_decay, "weight_decay": 0.0}]

    def _autocast(self):
        return torch.autocast(device_type=self.device.type, dtype=self.amp_dtype, enabled=self.use_amp)

    # ---- checkpoints ---------------------------------------------------------------------------
    @staticmethod
    def _atomic_save(obj, path: Path):
        tmp = path.with_name(path.name + ".tmp")
        torch.save(obj, tmp)
        os.replace(tmp, path)

    def _payload(self, epoch_complete: bool) -> Dict[str, Any]:
        return {
            "epoch": self.current_epoch,
            "epoch_complete": epoch_complete,
            "epoch_samples_done": 0 if epoch_complete else int(self.epoch_samples_done),  # exact mid-epoch resume
            "loader_batch": self.loader_batch,
            "world_size": self.world_size,
            "global_step": self.global_step,
            "model_state_dict": self.model.state_dict(),
            "ema_state_dict": self.ema.state_dict() if self.ema else None,
            "optimizer_state_dict": self.optimizer.state_dict(),
            "scheduler_state_dict": self.scheduler.state_dict(),
            "scaler_state_dict": self.scaler.state_dict(),
            "best_metric": self.best_metric,
            "best_metric_name": self.best_metric_name,
            "lr_schedule": dict(self.sched),
            "extra_request": self.saved_extra,  # {'extra_epochs', 'target_epochs'} of an active fine-tuning request
            "history": self.history,
            "lr_history": self.lr_history,
            "config": self.cfg.to_dict(),
            "rng": {
                "python": random.getstate(),
                "numpy": np.random.get_state(),
                "torch": torch.get_rng_state(),
                "cuda": torch.cuda.get_rng_state_all() if torch.cuda.is_available() else None,
            },
        }

    def save_checkpoint(self, epoch_complete: bool = True, is_best: bool = False):
        if not self.is_main:  # DDP: weights are identical on every rank, rank 0 writes
            return
        payload = self._payload(epoch_complete)
        if epoch_complete:
            self._atomic_save(payload, self.checkpoint_dir / f"checkpoint_epoch_{self.current_epoch:04d}.pt")
            old = sorted(self.checkpoint_dir.glob("checkpoint_epoch_*.pt"))
            for p in old[: max(0, len(old) - self.cfg.keep_last_k)]:
                p.unlink(missing_ok=True)
        self._atomic_save(payload, self.checkpoint_dir / "checkpoint_latest.pt")
        if is_best:
            self._atomic_save(payload, self.checkpoint_dir / "checkpoint_best.pt")
            print(f"  -> new best model (metric = {self.best_metric:.4f})")
        self._last_ckpt_time = time.time()
        extra = "" if epoch_complete else f", {self.epoch_samples_done} samples of this epoch done"
        print(f"Checkpoint saved at epoch {self.current_epoch} (complete={epoch_complete}, step={self.global_step}{extra})")

    # ---- pretrained-model safety ----------------------------------------------------------------
    ARCH_KEYS = ("in_channels", "dim", "num_heads", "window_size", "num_features", "swin_blocks", "clock_embed_dim",
                 "use_spectral_gate", "self_condition", "predict_uncertainty", "clock_hidden", "clock_bands", "prior_res")
    SEMANTIC_KEYS = ("num_timesteps", "schedule_type", "min_sigma", "max_sigma", "image_size")

    def _config_diff(self, saved: Dict[str, Any], keys: Sequence[str]) -> List[str]:
        cur = self.cfg.to_dict()
        out = []
        for k in keys:
            if k in saved:
                a, b = saved[k], cur.get(k)
                if (list(a) if isinstance(a, (list, tuple)) else a) != (list(b) if isinstance(b, (list, tuple)) else b):
                    out.append(f"    {k}: checkpoint={a!r}  current={b!r}")
        return out

    def _protect_pretrained(self):
        """One-time copy of the checkpoints found at start-up to <checkpoint_dir>/pretrained_backup/.
        Never overwritten (a later session keeps the *first* copy), never pruned by keep_last_k."""
        if not (self.cfg.protect_pretrained and self.is_main):
            return
        backup = self.checkpoint_dir / "pretrained_backup"
        if backup.exists():
            print(f"Pretrained backup present and left untouched: {backup}")
            return
        files = [self.checkpoint_dir / n for n in ("checkpoint_best.pt", "checkpoint_latest.pt", "final_model.pt")]
        files = [p for p in files if p.is_file()]
        if not files:
            return
        need = sum(p.stat().st_size for p in files)
        free = shutil.disk_usage(self.checkpoint_dir).free
        if free < 1.2 * need:
            print(f"  WARNING: only {free / 1e9:.1f} GB free, the pretrained checkpoints need {need / 1e9:.1f} GB -> "
                  f"NO backup made. Download {', '.join(p.name for p in files)} now.")
            return
        tmp = backup.with_name(backup.name + ".partial")
        shutil.rmtree(tmp, ignore_errors=True)
        tmp.mkdir(parents=True)
        for p in files:
            shutil.copy2(p, tmp / p.name)
        with open(tmp / "README.txt", "w") as f:
            f.write(f"Copy of the checkpoints found at start-up on {time.strftime('%Y-%m-%d %H:%M:%S')}.\n"
                    "Written once, never modified by the training code. To restart from it, copy a file back to "
                    "the checkpoint folder or set Config.resume_from to its path.\n")
        os.replace(tmp, backup)  # atomic: a half-copied backup is never mistaken for a complete one
        print(f"Pretrained checkpoints protected: copied {', '.join(p.name for p in files)} "
              f"({need / 1e9:.2f} GB) -> {backup}")

    def _candidate_checkpoints(self) -> List[Tuple[Path, str]]:
        """[(path, source)]: 'workdir' (checkpoint_dir, the continuation - always wins), 'explicit' (resume_from),
        'found' (checkpoint names found by the search) and 'weights' (other weight files found by the search)."""
        def in_dir(d: Path) -> List[Path]:
            if not d.is_dir():
                return []
            c = [d / "checkpoint_latest.pt", d / "checkpoint_best.pt"]
            c += sorted(d.glob("checkpoint_epoch_*.pt"), reverse=True)
            c.append(d / "final_model.pt")
            return [p for p in c if p.is_file()]

        cfg = self.cfg
        self._search_report = [f"{self.checkpoint_dir} (checkpoint_dir): nothing"]
        cands = [(p, "workdir") for p in in_dir(self.checkpoint_dir)]
        if cands:
            print(f"  found {len(cands)} checkpoint(s) in {self.checkpoint_dir}")
            return cands
        rf = (cfg.resume_from or "").strip()
        if rf and rf != "auto":
            p = Path(rf)
            cands = [(q, "explicit") for q in (in_dir(p) if p.is_dir() else ([p] if p.is_file() else []))]
            if not cands:
                print(f"  resume_from='{rf}': no checkpoint there")
                self._search_report.append(f"resume_from='{rf}': no checkpoint there")
            return cands
        if rf != "auto":
            return []
        roots = [r for r in cfg.resume_search_roots if r and Path(r).is_dir()]
        if not roots:
            return []
        print(f"  no checkpoint in '{self.checkpoint_dir}' -> searching {', '.join(roots)} (depth <= "
              f"{cfg.resume_search_depth}, <= {cfg.resume_search_timeout_s:g} s, data sets last) ...")
        data_dirs = [cfg.train_data_dir, cfg.val_data_dir, cfg.test_data_dir, cfg.real_images_dir, cfg.paired_root,
                     *cfg.extra_clean_dirs]
        skip = data_dirs + [cfg.output_dir, cfg.visualization_dir, str(self.checkpoint_dir)]
        found, weights = find_checkpoints(roots, cfg.resume_search_depth, cfg.resume_search_timeout_s, skip, data_dirs)
        self._search_report.append(f"{', '.join(roots)}: {len(found)} checkpoint(s), {len(weights)} other weight file(s)")
        if found:
            print("  checkpoints found (read-only inputs are safe; the first compatible one is used):")
            for q in found[:10]:
                print(f"    {q}")
            if len(found) > 10:
                print(f"    ... and {len(found) - 10} more")
        if weights:
            print(f"  other weight files (tried last, only if they match this model exactly): "
                  f"{', '.join(str(q) for q in weights[:5])}{' ...' if len(weights) > 5 else ''}")
        return [(q, "found") for q in found] + [(q, "weights") for q in weights[:5]]

    @staticmethod
    def _state_dict_of(ckpt: Any) -> Optional[Dict[str, torch.Tensor]]:
        if isinstance(ckpt, dict):
            for key in ("model_state_dict", "ema_state_dict", "state_dict", "model"):
                if isinstance(ckpt.get(key), dict):
                    return ckpt[key]
            if ckpt and all(isinstance(v, torch.Tensor) for v in ckpt.values()):
                return ckpt
        return None

    def _mismatch(self, sd: Optional[Dict[str, torch.Tensor]]) -> str:
        """'' when sd fits this model exactly, otherwise a short reason."""
        if sd is None:
            return "no model state_dict in the file"
        own = self.model.state_dict()
        missing, extra = set(own) - set(sd), set(sd) - set(own)
        if missing or extra:
            return f"{len(missing)} missing / {len(extra)} unexpected tensors"
        bad = [k for k in own if tuple(sd[k].shape) != tuple(own[k].shape)]
        return f"{len(bad)} tensors of a different shape (e.g. {bad[0]})" if bad else ""

    def _load_checkpoint(self, path: Optional[Union[str, Path]] = None) -> bool:
        self._protect_pretrained()
        self._search_report: List[str] = []
        if path:
            cands = [(Path(path), "explicit")]
        else:
            # One search (rank 0) and the SAME decision on every rank: two independent searches could disagree
            # (time limit), and a rank that resumes while the other starts from scratch deadlocks DDP.
            cands = self._candidate_checkpoints() if self.is_main else []
            if self.distributed:
                box = [[(str(p), src) for p, src in cands], list(self._search_report)]
                dist.broadcast_object_list(box, src=0)
                cands = [(Path(p), src) for p, src in box[0]]
                self._search_report = box[1]
        errors, mismatched, skipped = [], [], []
        for p, src in cands:
            t0 = time.time()
            print(f"  reading {p} ...")
            try:
                # CPU first: load_state_dict copies into the parameters and the optimiser moves its state to the
                # parameters' device, so mapping to the GPU only doubled the peak GPU memory at start-up.
                ckpt = torch.load(p, map_location="cpu", weights_only=False)
            except Exception as e:  # noqa: BLE001 (truncated / corrupt file -> next candidate)
                errors.append((p, src, str(e)))
                print(f"  could not read {p} ({e}) -> trying the next candidate")
                continue
            if src in ("found", "weights"):
                # Files found by the search may belong to another project: only an exact fit is used. A misfit
                # checkpoint of THIS pipeline is reported below (it is probably the pretrained run with other
                # architecture settings) - it is never silently replaced by a model trained from scratch.
                why = self._mismatch(self._state_dict_of(ckpt))
                if why:
                    print(f"  {p} does not fit this model ({why}) -> next candidate")
                    (mismatched if src == "found" else skipped).append((p, why, ckpt))
                    continue
                if src == "weights":
                    ckpt = {"model_state_dict": self._state_dict_of(ckpt)}
            print(f"Loading checkpoint from {p} (read in {time.time() - t0:.1f} s)")
            return self._restore(ckpt, p)
        if any(src in ("workdir", "explicit") for _, src, _ in errors):
            raise RuntimeError("Checkpoints exist but none could be read - nothing was modified:\n"
                               + "\n".join(f"{p}: {e}" for p, _, e in errors))
        if mismatched:  # a checkpoint of this pipeline exists but does not fit: show which settings differ
            p, why, ckpt = mismatched[0]
            return self._restore(ckpt, p)  # raises the architecture error with the Config diff
        report = self._search_report + [f"{p}: {why}" for p, why, _ in skipped] + [f"{p}: unreadable ({e})"
                                                                                for p, _, e in errors]
        hint = ("Attach the notebook version (its Output) or the dataset / model that holds checkpoint_latest.pt with "
                "'Add Input', or set Config.resume_from='/kaggle/input/.../checkpoint_latest.pt'.")
        if self.cfg.require_pretrained:
            raise RuntimeError("No pretrained checkpoint found:\n  " + "\n  ".join(report) + "\n" + hint
                               + " For a genuinely new run set Config.require_pretrained=False.")
        bar = "!" * 78
        print(f"\n{bar}\nNO PRETRAINED CHECKPOINT FOUND -> TRAINING STARTS FROM SCRATCH.\n  "
              + "\n  ".join(report) + f"\nTo continue a pretrained model instead: {hint}\n"
              "(Config.require_pretrained=True turns this into an error.)\n" + bar + "\n")
        return False

    def _restore(self, ckpt: Dict[str, Any], path: Path) -> bool:
        saved_cfg = ckpt.get("config") or {}
        sd = ckpt.get("model_state_dict", ckpt)
        try:
            self.model.load_state_dict(sd)
        except RuntimeError as e:
            # The old code moved the file away and silently restarted from scratch; with a pretrained model
            # that is exactly what must never happen -> stop, touch nothing.
            diff = self._config_diff(saved_cfg, self.ARCH_KEYS)
            raise RuntimeError(
                f"{path} does not match the current architecture. Nothing was moved or overwritten. Put the "
                f"architecture settings of the pretrained run back into Config"
                + (":\n" + "\n".join(diff) if diff else ".")
                + "\n(If this file is not your model, set Config.resume_from to your checkpoint, or to '' to start "
                  "from scratch.)" + f"\n{str(e)[:2000]}") from None
        sem = self._config_diff(saved_cfg, self.SEMANTIC_KEYS)
        if sem:
            print("  WARNING: these settings differ from the pretrained run and change what the network was trained on:\n"
                  + "\n".join(sem))
        if self.ema is not None:
            if ckpt.get("ema_state_dict") is not None:
                self.ema.load_state_dict(ckpt["ema_state_dict"])
            else:
                self.ema = EMA(self.model, self.cfg.ema_decay)
        if "epoch" not in ckpt:  # weights-only file (e.g. final_model.pt, whose weights are the EMA weights)
            print(f"Loaded weights only from {path} (no optimiser / epoch state) -> fine-tuning starts at epoch 0.")
            return True
        for obj, key in ((self.optimizer, "optimizer_state_dict"), (self.scheduler, "scheduler_state_dict"),
                         (self.scaler, "scaler_state_dict")):
            state = ckpt.get(key)
            if not state:
                if key == "scaler_state_dict" and self.scaler.is_enabled():
                    print("  GradScaler: the checkpoint has no scaler state (it was trained with bf16/fp32 AMP) -> "
                          "fresh fp16 scaler; the first steps calibrate the loss scale (a few skipped steps are normal).")
                continue
            try:
                obj.load_state_dict(state)
            except Exception as e:  # noqa: BLE001
                print(f"  (could not restore {key}: {e})")
        self.global_step = int(ckpt.get("global_step", 0))
        self.best_metric = float(ckpt.get("best_metric", -float("inf")))
        saved_name = ckpt.get("best_metric_name", "synthetic_ema_psnr")
        if saved_name != self.best_metric_name:  # different selection criterion -> numbers are not comparable
            print(f"  best-model criterion changed ({saved_name} -> {self.best_metric_name}): best score reset "
                  f"(the previous best file is kept in pretrained_backup/).")
            self.best_metric = -float("inf")
        saved_type = (ckpt.get("config") or {}).get("degradation_type")
        if saved_type and saved_type != self.cfg.degradation_type:
            print(f"  fine-tuning the pretrained '{saved_type}' model on '{self.cfg.degradation_type}' degradations "
                  f"(blur family: defocus / anisotropic / motion, noise, real pairs).")
        self.history = ckpt.get("history", self.history) or {"epoch": []}
        if not any(k.endswith("sampler_psnr_input") for k in self.history):
            # Sampler values recorded with the old noiseless protocol are not comparable -> keep them, renamed.
            moved = [k for k in ("val_ema_sampler_psnr", "val_sampler_psnr") if k in self.history]
            for k in moved:
                self.history[k + "_noiseless_legacy"] = self.history.pop(k)
            if moved:
                print("  history: old sampler PSNR values (noiseless protocol) kept as '*_noiseless_legacy'.")
        self.lr_history = ckpt.get("lr_history", [])
        complete = ckpt.get("epoch_complete", True)
        self.current_epoch = int(ckpt["epoch"]) + (1 if complete else 0)
        if ckpt.get("lr_schedule"):
            self.sched.update(ckpt["lr_schedule"])
        self.saved_extra = ckpt.get("extra_request")
        if not complete:  # exact mid-epoch resume (checkpoints of older versions restart the epoch)
            done = int(ckpt.get("epoch_samples_done", 0) or 0)
            self.resume_skip_samples = min(max(0, done // self.world_size), self.train_sampler.num_samples)
        rng = ckpt.get("rng") or {}
        try:
            if self.is_main:
                random.setstate(rng["python"])
                np.random.set_state(rng["numpy"])
                torch.set_rng_state(rng["torch"].cpu())
                if rng.get("cuda") is not None and torch.cuda.is_available():
                    states = [s.cpu() for s in rng["cuda"]][:torch.cuda.device_count()]  # fewer GPUs than saved
                    torch.cuda.set_rng_state_all(states)
            else:  # DDP: other ranks keep their own streams (different degradations for different images)
                seed_everything(self.cfg.seed + 1000 * self.rank + self.global_step, self.cfg.deterministic)
        except Exception:  # noqa: BLE001
            pass
        where = (f", skipping the {self.resume_skip_samples * self.world_size} samples it already trained"
                 if self.resume_skip_samples else "")
        print(f"Resumed from epoch {ckpt['epoch']} ({'complete' if complete else 'interrupted'}), "
              f"global_step {self.global_step} -> continuing at epoch {self.current_epoch}{where}")
        return True

    # ---- training ------------------------------------------------------------------------------
    def _sync_flags(self, total: torch.Tensor) -> Tuple[bool, bool]:
        """(loss finite, time budget exhausted), agreed by every rank: under DDP all ranks must skip the
        same batch and stop at the same step (or they hang)."""
        over = self.time_budget_s > 0 and (time.time() - SESSION_START) > self.time_budget_s
        flags = torch.stack([torch.isfinite(total.detach()).all().float(),
                             torch.tensor(0.0 if over else 1.0, device=total.device)])
        if self.distributed:
            dist.all_reduce(flags, op=dist.ReduceOp.MIN)
        ok, cont = flags.tolist()
        return ok > 0.5, cont < 0.5

    def _merge_epoch_logs(self, sums: Dict[str, float], counts: Dict[str, int]) -> Dict[str, float]:
        if self.distributed:  # epoch averages over the data seen by *all* ranks
            gathered: List[Any] = [None] * self.world_size
            dist.all_gather_object(gathered, (sums, counts))
            sums, counts = {}, {}
            for s, c in gathered:
                for k in s:
                    sums[k] = sums.get(k, 0.0) + s[k]
                    counts[k] = counts.get(k, 0) + c[k]
        return {k: sums[k] / max(counts[k], 1) for k in sums}

    def _real_batches(self):
        """Endless stream of real blur->sharp batches (own seeded order, independent of the epoch)."""
        ep = 0
        while True:
            self.real_sampler.set_epoch(ep)
            ep += 1
            yield from self.real_loader

    def train_epoch(self) -> Dict[str, float]:
        cfg = self.cfg
        self.train_step.train()  # model + loss
        # Seeded order for this epoch; an interrupted epoch skips exactly the samples it already trained.
        skip = self.resume_skip_samples
        self.resume_skip_samples = 0
        self.train_sampler.set_epoch(self.current_epoch, skip)
        self.epoch_samples_done = skip * self.world_size
        sums: Dict[str, float] = {}
        counts: Dict[str, int] = {}
        accum = max(1, cfg.grad_accum_steps)
        n_batches = len(self.train_loader)
        batch0 = skip // max(1, self.loader_batch)  # batches of this epoch already trained before a resume
        self.epoch_loop_completed = False
        pbar = tqdm(self.train_loader, desc=f"Epoch {self.current_epoch} - Training", leave=False, disable=not self.is_main)
        self.optimizer.zero_grad(set_to_none=True)
        for i, batch in enumerate(pbar):
            x0 = batch["image"].to(self.device, non_blocking=True)
            is_step = (i + 1) % accum == 0 or (i + 1) == n_batches
            # Per-batch decisions from a generator seeded by (seed, epoch, batch): identical on every DDP rank (the
            # global RNG differs per rank, so one GPU ran a 2-pass rollout / real-pair step while the other waited)
            # and reproducible after a mid-epoch resume.
            dec = torch.Generator().manual_seed(cfg.seed * 1_000_003 + 100_003 * self.current_epoch + batch0 + i)
            # SCR rollout [N4]: one decision per batch, shared by every GPU replica of that batch.
            rollout = float(torch.rand(1, generator=dec)) < cfg.rollout_prob
            # Real-pair step [N11]: the model learns real (motion) blur from real blurred photos + sharp frames.
            use_real = self.real_iter is not None and float(torch.rand(1, generator=dec)) < cfg.real_pair_prob
            if use_real:
                rb = next(self.real_iter)
                inp, y_real = rb["image"].to(self.device, non_blocking=True), rb["degraded"].to(self.device, non_blocking=True)
            else:
                inp, y_real = x0, None
            sync = self.train_step.no_sync() if (self.distributed and not is_step) else contextlib.nullcontext()
            with sync:
                total, logs_t, extras = self.train_step(inp, rollout, y_real)
                total = total.mean()  # DataParallel returns one value per GPU (equal shards)
                keys = list(logs_t.keys())
                logs = dict(zip(keys, torch.stack([logs_t[k].float().mean() for k in keys]).tolist()))
                self.epoch_samples_done += x0.shape[0] * self.world_size
                finite, over_budget = self._sync_flags(total)
                self.stop_requested = self.stop_requested or over_budget
                if not finite:
                    print(f"  non-finite loss at step {self.global_step}; batch skipped")
                    self.optimizer.zero_grad(set_to_none=True)
                    continue
                self.scaler.scale(total / accum).backward()
            if is_step:
                self.scaler.unscale_(self.optimizer)
                grad_norm = torch.nn.utils.clip_grad_norm_(self.model.parameters(), cfg.grad_clip)
                if bool(torch.isfinite(grad_norm)):  # fp16 overflow steps are skipped by the scaler: keep them
                    logs["grad_norm"] = float(grad_norm)  # out of the epoch mean (it read 'inf' before)
                self.scaler.step(self.optimizer)
                self.scaler.update()
                self.optimizer.zero_grad(set_to_none=True)
                self.scheduler.step()
                self.global_step += 1
                if self.ema is not None:
                    self.ema.update(self.model, self.global_step)
                self.lr_history.append(self.optimizer.param_groups[0]["lr"])
                if self.is_main and cfg.viz_every > 0 and self.global_step % cfg.viz_every == 0:
                    self._visualize_training(extras, f"step_{self.global_step:07d}_epoch_{self.current_epoch:03d}")
            for k, v in logs.items():
                sums[k] = sums.get(k, 0.0) + v
                counts[k] = counts.get(k, 0) + 1
            pbar.set_postfix({"loss": f"{logs['total']:.4f}", "rec": f"{logs['rec']:.4f}", "psnr": f"{logs['psnr']:.2f}",
                              "lr": f"{self.optimizer.param_groups[0]['lr']:.2e}"})
            if is_step:
                if self.stop_requested:  # time budget (all ranks agree) -> train() saves the exact position
                    self.epoch_loop_completed = (i + 1) == n_batches  # stopped on the last batch = epoch finished
                    break
                if (cfg.checkpoint_every_min > 0 and (i + 1) < n_batches
                        and time.time() - self._last_ckpt_time > 60.0 * cfg.checkpoint_every_min):
                    self.save_checkpoint(epoch_complete=False)  # rank 0 writes; a killed session loses <= N min
                    self._last_ckpt_time = time.time()
        else:  # no break: the whole (possibly drop_last-shortened) epoch was trained
            self.epoch_loop_completed = True
        return self._merge_epoch_logs(sums, counts)

    @torch.no_grad()
    def validate(self, model: ColdDiffusionModel, with_sampler: bool = False, with_real: bool = False) -> Dict[str, float]:
        """Deterministic validation: fixed clocks (val_taus + one clock field), fixed seeds.
        with_real: blind restoration of real blurred photos vs their sharp frames (what we want)."""
        cfg = self.cfg
        was_training = model.training
        model.eval()
        self.loss_fn.eval()
        g = torch.Generator().manual_seed(cfg.seed + 777)
        sums: Dict[str, float] = {}
        counts: Dict[str, int] = {}
        taus: List[Any] = list(cfg.val_taus) + ["field"]
        n_val = len(self.val_loader) if cfg.val_max_batches <= 0 else min(len(self.val_loader), cfg.val_max_batches)
        for bi, batch in enumerate(tqdm(self.val_loader, desc=f"Epoch {self.current_epoch} - Validation", total=n_val, leave=False)):
            if bi >= n_val:
                break
            x0 = batch["image"].to(self.device).float()
            B, C, H, W = x0.shape
            for tv in taus:
                kind = model.sample_kind(B, self.device, g)
                if tv == "field":
                    tau = model.sample_tau(B, H, W, self.device, g, force_field=True)
                else:
                    tau = torch.full((B,), float(tv), device=self.device)
                with self._autocast():
                    _, logs, extras = self.loss_fn(model, x0, tau=tau, kind=kind, generator=g, rollout=True)
                logs["ssim"] = ssim(extras["x0_hat"], x0).mean().item()
                for k, v in logs.items():
                    sums[k] = sums.get(k, 0.0) + v * B
                    counts[k] = counts.get(k, 0) + B
        res = {k: sums[k] / max(counts[k], 1) for k in sums}
        if with_sampler:
            res.update(self._validate_sampler(model))
        if with_real and self.real_val_loader is not None:
            res.update(self._validate_real(model))
        if was_training:
            model.train()
        return res

    @torch.no_grad()
    def _validate_real(self, model: ColdDiffusionModel) -> Dict[str, float]:
        """
        BLIND restoration of REAL blurred photos (fixed 256 centre crops of the real test pairs, native
        scale), compared with their sharp frames: the number that reflects the actual goal. fp32.
        """
        cfg = self.cfg
        acc: Dict[str, List[float]] = {}
        for batch in self.real_val_loader:
            x0 = batch["image"].to(self.device).float()
            y = batch["degraded"].to(self.device).float()
            rd = model.restore(y, sampler="direct", generator=torch.Generator().manual_seed(cfg.seed))
            rs = model.restore(y, steps=cfg.val_sampler_steps, sampler=cfg.sampler,
                               generator=torch.Generator().manual_seed(cfg.seed))
            vals = {"real_psnr_input": psnr(y, x0), "real_psnr_direct": psnr(rd["output"], x0),
                    "real_psnr_srn": psnr(rs["output"], x0), "real_ssim_srn": ssim(rs["output"], x0),
                    "real_ssim_direct": ssim(rd["output"], x0)}
            for k, v in vals.items():
                acc.setdefault(k, []).extend(v.float().cpu().tolist())
            # per real dataset (GoPro / HIDE / RealBlur_J / ...): input, direct and SRN PSNR
            for i, name in enumerate(batch.get("subset") or []):
                for k in ("real_psnr_input", "real_psnr_direct", "real_psnr_srn"):
                    acc.setdefault(f"{k}@{name}", []).append(float(vals[k][i]))
        out = {k: float(np.mean(v)) for k, v in acc.items()}
        if out:
            out["real_psnr_best"] = max(out["real_psnr_direct"], out["real_psnr_srn"])
        return out

    @torch.no_grad()
    def _validate_sampler(self, model: ColdDiffusionModel) -> Dict[str, float]:
        """
        Multi-step SRN sampler on *realistic* observations (sensor noise + 8-bit quantisation, the
        protocol of the Inferencer), in fp32 like deployment, on `val_sampler_batches` fixed val
        batches with its own fixed seed (comparable from epoch to epoch). Known clock and blind.
        The previous version used one noiseless float batch (inverse crime -> ~53 dB) under fp16.
        """
        cfg = self.cfg
        g = torch.Generator().manual_seed(cfg.seed + 4242)
        acc: Dict[str, List[float]] = {}
        nonfinite = 0
        for bi, batch in enumerate(self.val_loader):
            if bi >= max(1, cfg.val_sampler_batches):
                break
            x0 = batch["image"].to(self.device).float()
            B, C, H, W = x0.shape
            kind = model.sample_kind(B, self.device, g)
            st = model.degradation.new_state(x0, g)
            tau = model.degradation.effective_tau(model.sample_tau(B, H, W, self.device, g, force_field=True), kind, st)
            y, st = model.degradation.apply(x0, tau, kind, st)
            y = realistic_observation(y, cfg.eval_obs_noise, cfg.eval_quantize, g)
            observed = st["rank"] >= model.degradation.mask_ratio(tau)
            r = model.restore(y, tau_obs=tau, kind=kind, steps=cfg.val_sampler_steps, sampler="srn", generator=g,
                              observed=observed, op_state=st)
            nonfinite += r["nonfinite_steps"]
            vals = {"sampler_psnr": psnr(r["output"], x0), "sampler_ssim": ssim(r["output"], x0),
                    "sampler_psnr_input": psnr(y, x0)}
            if cfg.val_sampler_blind:
                rb = model.restore(y, steps=cfg.val_sampler_steps, sampler="srn", generator=g)
                nonfinite += rb["nonfinite_steps"]
                vals["sampler_blind_psnr"] = psnr(rb["output"], x0)
            for k, v in vals.items():
                acc.setdefault(k, []).extend(v.float().cpu().tolist())
        out = {k: float(np.mean(v)) for k, v in acc.items()}
        out["sampler_nonfinite"] = float(nonfinite)
        if nonfinite:
            print(f"  WARNING: {nonfinite} sampler step(s) produced non-finite predictions (replaced by the NaN guard).")
        return out

    def _append(self, key: str, value):
        lst = self.history.setdefault(key, [])
        while len(lst) < len(self.history["epoch"]) - 1:
            lst.append(None)
        lst.append(value)

    def _record(self, epoch, tr, va, ve):
        self.history["epoch"].append(epoch)
        for k, v in tr.items():
            self._append(f"train_{k}", v)
        for k, v in va.items():
            self._append(f"val_{k}", v)
        for k in ("psnr", "ssim", "sampler_psnr", "total", "sampler_ssim", "sampler_psnr_input", "sampler_blind_psnr",
                  "sampler_nonfinite", "real_psnr_input", "real_psnr_direct", "real_psnr_srn", "real_ssim_srn",
                  "real_ssim_direct", "real_psnr_best"):
            if k in ve:
                self._append(f"val_ema_{k}", ve[k])
        for k in ve:  # per real dataset ('real_psnr_srn@HIDE', ...)
            if "@" in k:
                self._append(f"val_ema_{k}", ve[k])
        self._append("lr", self.optimizer.param_groups[0]["lr"])
        n = len(self.history["epoch"])
        for k, lst in self.history.items():  # keep every column aligned with the epochs
            while len(lst) < n:
                lst.append(None)

    def train(self):
        cfg = self.cfg
        unit = "GPUs" if self.device.type == "cuda" else "CPU processes"
        gpus = {"ddp": f"{self.world_size} {unit} (DDP)", "dp": f"{self.n_gpus} GPUs (DataParallel)",
                "single": "1 GPU", "cpu": "CPU"}[self.mode]
        print(f"Starting training for {cfg.epochs} epochs (from epoch {self.current_epoch}) on {self.device} "
              f"| {gpus} | global batch {self.global_batch} | {self.steps_per_epoch} optimiser steps/epoch "
              f"| AMP={self.use_amp} ({self.amp_dtype}{' + GradScaler' if self.scaler.is_enabled() else ''})")
        kinds = cfg.allinone_kinds if cfg.degradation_type == "allinone" else (
            KINDS if cfg.degradation_type == "mixed" else (cfg.degradation_type,))
        shapes = ", ".join(f"{n} {p:.0%}" for n, p in zip(BLUR_SHAPES, np.array(cfg.blur_shape_probs) / sum(cfg.blur_shape_probs)))
        print(f"Training data: {len(self.train_dataset)} CLEAN images degraded on the fly [{', '.join(kinds)}; blur = "
              f"{shapes}; +noise on {cfg.compound_noise_prob:.0%} of blurs]"
              + (f" | REAL pairs on {cfg.real_pair_prob:.0%} of steps: {', '.join(self.real_train_names)}"
                 if self.real_iter is not None else " | no real pairs found")
              + (f" | real validation: {self.real_val_name} ({len(self.real_val_loader.dataset)} crops)"
                 if self.real_val_loader is not None else "")
              + f" | best model by: {self.best_metric_name}")
        if self.time_budget_s > 0:
            left = self.time_budget_s - (time.time() - SESSION_START)
            print(f"Time budget: training stops cleanly after {self.time_budget_s / 3600:.2f} h of session time "
                  f"({left / 3600:.2f} h left); mid-epoch checkpoint every {self.cfg.checkpoint_every_min:g} min.")
            if left <= 0:
                print("  WARNING: this kernel has been running longer than the budget already (the budget counts from "
                      "the process start, like Kaggle's session limit): training stops after the first step. Restart "
                      "the session or raise Config.time_budget_hours (0 = off).")
        self.training_complete = False
        self.status = "trained"
        if self.current_epoch >= cfg.epochs:  # the previous version printed 'Training completed successfully!' here
            interrupted = self.resume_skip_samples > 0
            self.status = "nothing_to_train"
            # current_epoch == number of COMPLETED epochs (an interrupted epoch is not counted), so this branch always
            # means "finished"; a checkpoint BEYOND Config.epochs used to count as unfinished (no inference / prior)
            self.training_complete = self.current_epoch >= cfg.epochs
            bar = "!" * 78
            print(f"\n{bar}\nNOTHING TO TRAIN: the checkpoint is at epoch {self.current_epoch}"
                  + (f" (interrupted after {self.resume_skip_samples * self.world_size} samples)" if interrupted else "")
                  + f" and Config.epochs = {cfg.epochs}.\n"
                  + (f"The extra_epochs={cfg.extra_epochs} request stored in the checkpoint is already complete "
                     f"(target epoch {cfg.epochs}).\nFor more epochs set Config.new_extra_request = True (or another "
                     f"extra_epochs value)."
                     if (cfg.extra_epochs > 0 and self.saved_extra
                         and self.saved_extra.get("extra_epochs") == cfg.extra_epochs) else
                     f"Config.epochs is the TOTAL number of epochs, not additional ones. To train N more epochs set "
                     f"Config.extra_epochs = N\n(or Config.epochs > {self.current_epoch}).")
                  + ("" if self.training_complete else "\nNo inference with run_inference='when_done' (set 'always' to "
                                                       "evaluate this checkpoint anyway).") + f"\n{bar}")
            if self.training_complete and self.is_main and float(self.model.prior_ready.item()) < 0.5:
                self.finalize()
            return
        for epoch in range(self.current_epoch, cfg.epochs):
            self.current_epoch = epoch
            t0 = time.time()
            tr = self.train_epoch()
            # (the sample count never reached num_samples with drop_last, so a budget stop on the last batch
            # was saved as an interrupted epoch that the next session then 'resumed' with zero batches)
            epoch_finished = self.epoch_loop_completed
            if self.stop_requested and not epoch_finished:  # time budget: save exactly here, next session resumes here
                self.save_checkpoint(epoch_complete=False)
                n_ep = self.train_sampler.num_samples * self.world_size
                print(f"\nTime budget reached: epoch {epoch} stopped after {self.epoch_samples_done}/{n_ep} samples "
                      f"(global step {self.global_step}). The next run resumes exactly from this point.")
                barrier()
                self.status = "time_budget"
                return
            if not self.is_main:  # DDP: rank 0 validates / saves / plots while the other ranks wait
                barrier()
                if self.stop_requested:
                    return
                continue
            do_val = ((epoch + 1) % max(1, cfg.val_every) == 0) or epoch == cfg.epochs - 1
            want_sampler = cfg.val_sampler_every > 0 and ((epoch + 1) % cfg.val_sampler_every == 0 or epoch == cfg.epochs - 1)
            va = (self.validate(self.model, with_sampler=want_sampler and self.ema is None,
                                with_real=self.ema is None) if do_val else {})
            ve = (self.validate(self.ema.model, with_sampler=want_sampler, with_real=True)
                  if (do_val and self.ema is not None) else {})
            self._record(epoch, tr, va, ve)
            sel = ve or va
            if self.best_metric_name.startswith("real_ema_psnr"):
                metric = sel.get("real_psnr_best", float("nan"))
            else:
                metric = sel.get("psnr", float("nan"))
            is_best = do_val and np.isfinite(metric) and metric > self.best_metric
            if is_best:
                self.best_metric = metric
            self.save_checkpoint(epoch_complete=True, is_best=is_best)
            self.current_epoch_trained = True
            self.plot_curves()
            self.save_history()
            print(f"\nEpoch {epoch} ({time.time() - t0:.0f}s) | train loss {tr.get('total', float('nan')):.5f} "
                  f"psnr {tr.get('psnr', float('nan')):.2f} | val loss {va.get('total', float('nan')):.5f} "
                  f"psnr {va.get('psnr', float('nan')):.2f} ssim {va.get('ssim', float('nan')):.4f} "
                  f"| EMA psnr {ve.get('psnr', float('nan')):.2f} | sampler {self._sampler_str(ve or va, epoch)} "
                  f"| clock MAE {va.get('clock_mae', float('nan')):.4f} | lr {self.optimizer.param_groups[0]['lr']:.3e}")
            if "real_psnr_input" in sel:  # the real goal: blind restoration of real blurred photos
                print(f"         REAL {self.real_val_name} blur->sharp (blind, {len(self.real_val_loader.dataset)} crops): "
                      f"input {sel['real_psnr_input']:.2f} dB -> direct {sel['real_psnr_direct']:.2f} dB / "
                      f"SRN {sel['real_psnr_srn']:.2f} dB (SSIM {sel['real_ssim_srn']:.4f})"
                      + (f" | train on real pairs: {tr['real_psnr']:.2f} dB (input {tr.get('real_psnr_input', float('nan')):.2f})"
                         if "real_psnr" in tr else ""))
                per = sorted({k.split("@", 1)[1] for k in sel if k.startswith("real_psnr_srn@")})
                if per:
                    print("         per dataset (input -> direct / SRN dB): " + " | ".join(
                        f"{n} {sel[f'real_psnr_input@{n}']:.2f} -> {sel[f'real_psnr_direct@{n}']:.2f} / "
                        f"{sel[f'real_psnr_srn@{n}']:.2f}" for n in per))
            barrier()
            if self.stop_requested:  # budget hit on the last batch of an epoch: the epoch was saved complete
                print("\nTime budget reached at the end of the epoch; the next run starts the next epoch.")
                self.status = "time_budget"
                return
        self.training_complete = True
        # (no epoch left to train and a prior already fitted -> nothing to redo)
        if self.is_main and (self.current_epoch_trained or float(self.model.prior_ready.item()) < 0.5):
            self.finalize()

    def _sampler_str(self, d: Dict[str, float], epoch: int) -> str:
        """Sampler metric for the epoch line. The old line printed 'nan' on every epoch where the
        sampler validation was simply not scheduled (it ran every 5th epoch only)."""
        if "sampler_psnr" not in d:
            k = self.cfg.val_sampler_every
            if k <= 0:
                return "off"
            nxt = min(((epoch + 1) // k + 1) * k - 1, self.cfg.epochs - 1)
            return f"not run this epoch (next: epoch {nxt})"
        s = f"SRN {d['sampler_psnr']:.2f} dB (input {d.get('sampler_psnr_input', float('nan')):.2f}"
        if "sampler_blind_psnr" in d:
            s += f", blind {d['sampler_blind_psnr']:.2f}"
        return s + ")"

    def finalize(self):
        """Fit the degraded prior (generation) and store it in every relevant checkpoint."""
        loader = DataLoader(self.train_dataset, batch_size=self.cfg.batch_size, shuffle=True,
                            num_workers=self.cfg.num_workers)  # (decoding up to prior_max_images photos serially was slow)
        if not self.model.fit_prior(loader, self.device):
            return
        if self.ema is not None:
            for name in PRIOR_BUFFERS:
                getattr(self.ema.model, name).copy_(getattr(self.model, name))
        for p in (self.checkpoint_dir / "checkpoint_best.pt", self.checkpoint_dir / "checkpoint_latest.pt"):
            if p.exists():
                ck = torch.load(p, map_location="cpu", weights_only=False)
                for key in ("model_state_dict", "ema_state_dict"):
                    if ck.get(key) is not None:
                        for name in PRIOR_BUFFERS:
                            ck[key][name] = getattr(self.model, name).detach().cpu().clone()
                self._atomic_save(ck, p)

    # ---- logging -------------------------------------------------------------------------------
    @torch.no_grad()
    def _visualize_training(self, extras: Dict[str, Any], tag: str):
        n = min(4, extras["x0"].shape[0])
        rows = [to01(extras["x0"][:n]), to01(extras["x_t"][:n]), to01(extras["x0_hat"][:n])]
        rows.append(torch.stack([colorize((extras["x0_hat"][i] - extras["x0"][i]).abs().mean(0), "magma", 0, 0.5) for i in range(n)]))
        rows.append(torch.stack([colorize(extras["tau"][i, 0], "viridis", 0, 1) for i in range(n)]))
        if extras.get("tau_hat") is not None:
            rows.append(torch.stack([colorize(extras["tau_hat"][i, 0], "viridis", 0, 1) for i in range(n)]))
        if extras.get("log_scale") is not None:
            rows.append(torch.stack([colorize(extras["log_scale"][i].float().exp().mean(0), "inferno") for i in range(n)]))
        grid = make_grid(torch.cat([r.float().cpu() for r in rows]), nrow=n, padding=2)
        path = self.viz_dir / f"{tag}.png"
        save_image(grid, path)
        print(f"  visualisation (rows: clean, degraded, restored, |error|, clock, estimated clock, uncertainty) -> {path}")

    def save_history(self):
        save_json({"history": self.history, "lr_history": self.lr_history}, self.checkpoint_dir / "history.json")
        keys = list(self.history.keys())
        with open(self.checkpoint_dir / "history.csv", "w", newline="") as f:
            w = csv.writer(f)
            w.writerow(keys)
            for i in range(len(self.history["epoch"])):
                w.writerow([self.history[k][i] if i < len(self.history[k]) else None for k in keys])

    def plot_curves(self):
        h = self.history
        ep = h.get("epoch", [])
        if not ep:
            return
        fig, axes = plt.subplots(2, 3, figsize=(17, 9))

        def draw(ax, series, title, ylabel, logy=False):
            for key, label, style in series:
                vals = h.get(key, [])
                pts = [(e, v) for e, v in zip(ep, vals) if v is not None and np.isfinite(v)]
                if pts:
                    ax.plot([p[0] for p in pts], [p[1] for p in pts], style, marker="o", ms=3, label=label)
            ax.set_title(title)
            ax.set_xlabel("epoch")
            ax.set_ylabel(ylabel)
            if logy:
                ax.set_yscale("log")
            ax.grid(True, alpha=0.3)
            if ax.lines:
                ax.legend(fontsize=8)

        draw(axes[0, 0], [("train_total", "train", "b-"), ("val_total", "valid", "r--"), ("val_ema_total", "valid (EMA)", "g-.")],
             "Total loss (train vs valid)", "loss", logy=True)
        draw(axes[0, 1], [("train_rec", "train", "b-"), ("val_rec", "valid", "r--")], "Reconstruction L1 (x0)", "L1")
        draw(axes[0, 2], [("train_psnr", "train (1-step)", "b-"), ("val_psnr", "valid (1-step)", "r--"),
                          ("val_ema_psnr", "valid EMA (1-step)", "g-."), ("val_ema_sampler_psnr", "valid EMA SRN sampler", "m:"),
                          ("val_sampler_psnr", "valid SRN sampler", "c:"),
                          ("val_ema_sampler_blind_psnr", "valid EMA SRN sampler (blind)", "y:"),
                          ("val_ema_sampler_psnr_input", "sampler input (noisy, 8-bit)", "k:")], "PSNR", "dB")
        if any(k.startswith("val_ema_real") for k in h):  # the real goal replaces the SSIM panel
            draw(axes[1, 0], [("val_ema_real_psnr_input", "real blurred input", "k:"),
                              ("val_ema_real_psnr_direct", "EMA blind direct", "b-"),
                              ("val_ema_real_psnr_srn", "EMA blind SRN", "m-"),
                              ("train_real_psnr", "train real pairs (1-step)", "c--")],
                 "REAL blur -> sharp (blind)", "PSNR (dB)")
        else:
            draw(axes[1, 0], [("val_ssim", "valid", "r--"), ("val_ema_ssim", "valid EMA", "g-.")], "SSIM", "SSIM")
        draw(axes[1, 1], [("train_clock_mae", "train", "b-"), ("val_clock_mae", "valid", "r--")],
             "Spectral Clock Estimator MAE [N1]", "|tau_hat - tau|")
        ax = axes[1, 2]
        if self.lr_history:
            ax.plot(np.arange(1, len(self.lr_history) + 1), self.lr_history, color="orange")
        ax.set_title("Learning-rate schedule")
        ax.set_xlabel("optimiser step")
        ax.set_ylabel("lr")
        ax.grid(True, alpha=0.3)
        plt.tight_layout()
        for p in (self.checkpoint_dir / "training_curves.png", Path(self.cfg.visualization_dir) / "training_curves.png"):
            fig.savefig(p, dpi=130, bbox_inches="tight")
        plt.close(fig)


# =======================================================================================
# SECTION 9: INFERENCER
# =======================================================================================

DARK_BG = "#1a1a1a"


class Inferencer:
    """
    Every capability of the model, plus everything needed to understand it.

    Capabilities
      * infer / evaluate        synthetic restoration with known or estimated clock, all samplers,
                                PSNR / SSIM / LPIPS / Null-Space Recovery, quality vs degradation
      * restore_real_image      blind restoration of real photos (estimated clock field, strength control)
      * strength_sweep          controllable restoration strength (tau_obs * kappa)
      * generate_samples        unconditional generation from the degraded prior
      * evaluate_clock          accuracy and calibration of the Spectral Clock Estimator

    Interpretability (interpret)
      trajectories (strip + GIF + per-step PSNR/uncertainty), Swin attention maps and per-head
      attention distance/entropy, encoder/decoder feature PCA, spectral-gate gain curves vs.
      the physical inverse-heat gain, range/null-space decomposition of the output,
      radial power spectra, uncertainty maps + reliability diagram, clock-sensitivity map
      d x0_hat / d tau, estimated vs true clock field, physics features of the estimator,
      raw tensors (.pt) and JSON summaries.
    """

    def __init__(self, model: ColdDiffusionModel, config: Config, device: Optional[str] = None,
                 checkpoint: Optional[str] = "auto", use_ema: bool = True):
        self.cfg = config
        self.device = torch.device(device or config.device)
        self.model = model.to(self.device).eval()
        self.loaded_from: Optional[str] = None
        self.real_sampler = config.real_sampler if config.real_sampler != "auto" else config.sampler
        if checkpoint:
            self.load_checkpoint(checkpoint, use_ema)
        self.root = Path(config.output_dir) / "inference"
        self.root.mkdir(parents=True, exist_ok=True)
        self.lpips = LPIPSMetric(self.device) if (config.compute_lpips and PYIQA_AVAILABLE) else None

    # ---- loading -------------------------------------------------------------------------------
    def load_checkpoint(self, checkpoint: str = "auto", use_ema: bool = True):
        ck_dir = Path(self.cfg.checkpoint_dir)
        if checkpoint == "auto":
            cands = [ck_dir / "checkpoint_best.pt", ck_dir / "checkpoint_latest.pt", ck_dir / "final_model.pt"]
            path = next((p for p in cands if p.exists()), None)
            if path is None:
                print("[inferencer] no checkpoint found - using the in-memory weights.")
                return
        else:
            path = Path(checkpoint)
        ck = torch.load(path, map_location="cpu", weights_only=False)  # (the optimiser state never needs the GPU)
        if use_ema and ck.get("ema_state_dict") is not None:
            sd, which = ck["ema_state_dict"], "EMA"
        else:
            sd, which = ck.get("model_state_dict", ck), "raw"
        res = self.model.load_state_dict(sd, strict=False)
        if res.missing_keys or res.unexpected_keys:
            print(f"[inferencer] missing={len(res.missing_keys)} unexpected={len(res.unexpected_keys)} keys")
        self.loaded_from = str(path)
        print(f"[inferencer] loaded {which} weights from {path}")
        if self.cfg.real_sampler == "auto":  # the sampler that did better on the REAL validation pairs
            h = ck.get("history") or {}
            last = lambda k: next((v for v in reversed(h.get(k, [])) if v is not None), None)  # noqa: E731
            d, s = last("val_ema_real_psnr_direct"), last("val_ema_real_psnr_srn")
            if d is not None and s is not None:
                self.real_sampler = "direct" if d > s else "srn"
                print(f"[inferencer] real photos: sampler '{self.real_sampler}' (real validation: direct {d:.2f} dB, SRN {s:.2f} dB)")

    # ---- helpers -------------------------------------------------------------------------------
    def _gen(self, offset: int = 0) -> torch.Generator:
        return torch.Generator().manual_seed(self.cfg.seed + 2024 + offset)

    def _dir(self, *parts) -> Path:
        d = self.root.joinpath(*parts)
        d.mkdir(parents=True, exist_ok=True)
        return d

    @staticmethod
    def _safe(name: str, fn):
        try:
            return fn()
        except Exception as e:  # noqa: BLE001
            print(f"[inferencer] '{name}' failed: {e}")
            traceback.print_exc()
            return None

    def _tau_map(self, tau, B, H, W, generator) -> torch.Tensor:
        if isinstance(tau, torch.Tensor):
            t = tau.to(self.device).float()
            return t.view(B, 1, 1, 1).expand(B, 1, H, W).contiguous() if t.dim() == 1 else t
        if tau == "field":
            return self.model.sample_tau(B, H, W, self.device, generator, force_field=True)
        return torch.full((B, 1, H, W), float(tau), device=self.device)

    def _observe(self, y: torch.Tensor, generator: Optional[torch.Generator]) -> torch.Tensor:
        """Realistic synthetic observation: sensor noise + 8-bit quantisation. Without it an exact,
        noiseless, known operator can be inverted perfectly (the 'inverse crime')."""
        if self.cfg.eval_obs_noise > 0:
            y = y + self.cfg.eval_obs_noise * _randn(tuple(y.shape), y.device, generator)
        if self.cfg.eval_quantize:
            y = torch.round(to01(y) * 255.0) / 255.0 * 2 - 1
        return y.clamp(-1, 1)

    def _metrics(self, out, x0, y, tau, kind, state=None) -> Dict[str, float]:
        m = {"psnr": psnr(out, x0).mean().item(), "ssim": ssim(out, x0).mean().item(),
             "psnr_input": psnr(y, x0).mean().item(), "ssim_input": ssim(y, x0).mean().item(),
             "nsr": null_space_recovery(out, x0, y, tau, kind, self.model.degradation, state=state).mean().item()}
        if self.lpips is not None:
            v = self.lpips(out, x0)
            if v is not None:
                m["lpips"] = v.mean().item()
        return m

    # ---- capability 1: synthetic restoration -------------------------------------------------------
    @torch.no_grad()
    def infer(self, images: torch.Tensor, tau: Union[float, str, torch.Tensor] = "field", kind: Optional[torch.Tensor] = None,
              sampler: Optional[str] = None, steps: Optional[int] = None, blind: bool = False, record: bool = True,
              generator: Optional[torch.Generator] = None, shape: Optional[str] = None) -> Dict[str, Any]:
        """Degrade CLEAN images with a known clock (and blur shape: None = random family member,
        'iso' | 'aniso' | 'motion' = forced), restore them (known or blind operator), measure."""
        g = generator or self._gen()
        x0 = images.to(self.device).float()
        B, C, H, W = x0.shape
        if kind is None:
            kind = self.model.sample_kind(B, self.device, g)
        deg = self.model.degradation
        st = deg.new_state(x0, g, shape=shape)
        tau_map = deg.effective_tau(self._tau_map(tau, B, H, W, g), kind, st)
        y, st = deg.apply(x0, tau_map, kind, st)
        y = self._observe(y, g)
        observed = st["rank"] >= deg.mask_ratio(tau_map)
        t0 = time.time()
        with self._infer_autocast():
            res = self.model.restore(y, tau_obs=None if blind else tau_map, kind=None if blind else kind, sampler=sampler,
                                     steps=steps, record=record, observed=observed, generator=g, x0_gt=x0,
                                     op_state=None if blind else st)
        res["output"], res["x0"] = res["output"].float(), res["x0"].float()
        res["time"] = time.time() - t0
        res.update({"input": x0, "degraded": y, "tau_true": tau_map, "kind_true": kind, "blind": blind, "true_state": st})
        res["metrics"] = self._metrics(res["output"], x0, y, tau_map, kind, st)
        return res

    @torch.no_grad()
    def evaluate(self, loader: DataLoader, samplers: Optional[Sequence[str]] = None, taus: Optional[Sequence[Any]] = None,
                 max_batches: Optional[int] = None, include_blind: bool = True, save_dir: Optional[Path] = None) -> Dict[str, Any]:
        """Benchmark every sampler on every degradation level and condition (blur shapes, noise, ...)
        on CLEAN images (identical degradations for every sampler). Method keys: '<condition>|<sampler>'."""
        cfg = self.cfg
        samplers = list(samplers or cfg.eval_samplers)
        taus = list(taus or cfg.eval_taus) + ["field"]
        max_batches = max_batches or cfg.eval_max_batches
        save_dir = save_dir or self._dir("evaluation")
        methods = [(s, False) for s in samplers] + ([(s, True) for s in cfg.eval_blind_samplers] if include_blind else [])
        conditions: List[Tuple[str, int, Optional[str]]] = []
        for k in allowed_kinds(cfg):
            if k == BLUR:
                conditions += [(f"blur-{s}", BLUR, s) for s in cfg.eval_blur_shapes]
            else:
                conditions.append((KINDS[k], k, None))
        rows = []
        for bi, batch in enumerate(tqdm(loader, desc="Evaluation", total=min(len(loader), max_batches))):
            if bi >= max_batches:
                break
            x0 = batch["image"]
            for ci, (cname, k, shape) in enumerate(conditions):
                kind = torch.full((x0.shape[0],), k, dtype=torch.long, device=self.device)
                for ti, tv in enumerate(taus):
                    seed_off = 1000 * bi + 37 * ci + ti
                    for s, blind in methods:
                        res = self.infer(x0, tau=tv, kind=kind, sampler=s, blind=blind, record=False,
                                         generator=self._gen(seed_off), shape=shape, steps=cfg.eval_steps)
                        rows.append({"batch": bi, "tau": str(tv), "method": f"{cname}|{s}" + ("-blind" if blind else ""),
                                     "steps": res["steps"], "sec_per_image": res["time"] / x0.shape[0], **res["metrics"]})
        if not rows:
            return {}
        keys = sorted({k for r in rows for k in r if k not in ("batch", "tau", "method")})
        summary: Dict[str, Dict[str, Dict[str, float]]] = {}
        for r in rows:
            summary.setdefault(r["method"], {}).setdefault(r["tau"], {k: [] for k in keys})
            for k in keys:
                if k in r:
                    summary[r["method"]][r["tau"]][k].append(r[k])
        summary = {m: {t: {k: float(np.mean(v)) for k, v in d.items() if v} for t, d in td.items()} for m, td in summary.items()}
        with open(save_dir / "evaluation_raw.csv", "w", newline="") as f:
            w = csv.DictWriter(f, fieldnames=["batch", "tau", "method"] + keys)
            w.writeheader()
            w.writerows(rows)
        save_json(summary, save_dir / "evaluation_summary.json")

        # quality vs. degradation plot, one figure per condition
        num_taus = [t for t in taus if t != "field"]
        for cname, _, _ in conditions:
            sub = {m: td for m, td in summary.items() if m.split("|")[0] == cname}
            if not sub:
                continue
            fig, axes = plt.subplots(1, 3, figsize=(18, 4.8))
            for ax, metric, title in zip(axes, ("psnr", "ssim", "nsr"), ("PSNR (dB)", "SSIM", "Null-space recovery [0-1]")):
                first = next(iter(sub.values()))
                if metric != "nsr":
                    ax.plot(num_taus, [first[str(t)][f"{metric}_input"] for t in num_taus], "k:", marker="x", label="degraded input")
                for m, td in sub.items():
                    ax.plot(num_taus, [td[str(t)].get(metric, np.nan) for t in num_taus], marker="o", label=m.split("|")[1])
                ax.set_xlabel("clock tau (degradation level)")
                ax.set_title(f"{title} - {cname}")
                ax.grid(True, alpha=0.3)
                ax.legend(fontsize=8)
            plt.tight_layout()
            fig.savefig(save_dir / f"quality_vs_degradation_{cname}.png", dpi=150)
            plt.close(fig)

        print("\nEvaluation summary on CLEAN test images (PSNR / SSIM / NSR):")
        header = "condition|method".ljust(26) + "".join(str(t).rjust(22) for t in taus)
        print(header)
        for m, td in summary.items():
            line = m.ljust(26)
            for t in taus:
                d = td.get(str(t), {})
                line += f"{d.get('psnr', np.nan):7.2f}/{d.get('ssim', np.nan):.3f}/{d.get('nsr', np.nan):5.2f}".rjust(22)
            print(line)
        return summary

    # ---- capability 2: blind restoration of real images -----------------------------------------------
    @torch.no_grad()
    def restore_real_image(self, image_path: Union[str, Path], save_dir: Optional[Path] = None, strength: float = 1.0,
                           sampler: Optional[str] = None, steps: Optional[int] = None,
                           gt: Optional[Union[str, Path, torch.Tensor]] = None) -> Dict[str, Any]:
        """Blind restoration: the Spectral Clock Estimator reads tau(x) from the photo itself.
        For DBlur-style folders (.../blur/NAME) the sharp frame .../sharp/NAME is used as ground truth."""
        image_path = Path(image_path)
        if gt is None and _norm_name(image_path.parent.name) in _BLUR_DIR_NAMES:  # blur/NAME -> sharp/NAME (or gt/...)
            sharp_dirs = [d for d in _subdirs(image_path.parent.parent) if _norm_name(d.name) in _SHARP_DIR_NAMES]
            gt = next((d / image_path.name for d in sharp_dirs if (d / image_path.name).is_file()), None)
        save_dir = save_dir or self._dir("real", image_path.stem)
        save_dir.mkdir(parents=True, exist_ok=True)
        y, orig_size = load_image_tensor(image_path, self.cfg.real_max_side)
        y = y.to(self.device)
        kw = dict(tau_obs=None, kind=None, sampler=sampler or self.real_sampler, steps=steps, strength=strength,
                  lam=self.cfg.rn_lambda_real, record=True, generator=self._gen())
        try:  # fp16 on T4 (NaN-guarded inside restore); out of memory -> 768 px
            with self._infer_autocast():
                res = self.model.restore(y, **kw)
        except RuntimeError as e:
            if "out of memory" not in str(e).lower():
                raise
            torch.cuda.empty_cache()
            y = self._resize_pair(y, y, 768)[1]
            print(f"[real] {image_path.name}: out of memory at {self.cfg.real_max_side} px -> restored at 768 px")
            with self._infer_autocast():
                res = self.model.restore(y, **kw)
        out = res["output"].float()
        save_image(to01(y), save_dir / "input.png")
        save_image(to01(out), save_dir / "restored.png")
        full = tensor_to_pil(out)
        if full.size != orig_size:
            full = full.resize(orig_size, Image.LANCZOS)
        full.save(save_dir / "restored_fullres.png")
        clock = res.get("clock", {})
        maps = {"clock_field": colorize(res["tau_obs"][0, 0], "viridis", 0, 1)}
        if clock:
            maps["clock_raw"] = colorize(clock["tau_mu"][0, 0], "viridis", 0, 1)
            maps["clock_confidence"] = colorize(torch.exp(-clock["tau_logscale"][0, 0]), "cividis")
        if res["uncertainty"] is not None:
            maps["uncertainty"] = colorize(res["uncertainty"][0].mean(0), "inferno")
        maps["residual"] = colorize((out - y)[0].abs().mean(0), "magma")
        for k, v in maps.items():
            save_image(v, save_dir / f"{k}.png")
        if self.cfg.save_gif and res["trajectory"]:
            save_gif([to01(f[0]) for f in res["trajectory"]], save_dir / "trajectory.gif")
        metrics: Dict[str, Any] = {"image": str(image_path), "strength": strength, "steps": res["steps"],
                                   "mean_tau": float(res["tau_obs"].mean()), "max_tau": float(res["tau_obs"].max()),
                                   "mean_sigma_px": float(self.model.degradation.sigma(res["tau_obs"]).mean()),
                                   "data_consistency_l1": float((self.model.degradation.apply(
                                       out, res["tau_obs"], res["kind"],
                                       self.model.degradation.blur_only(res["op_state"]))[0] - y).abs().mean()),
                                   "kind": KINDS[int(res["kind"][0])]}
        if "blur_shape" in res:
            metrics["blur_direction_deg"] = float(torch.rad2deg(res["blur_shape"]["theta"][0]))
            metrics["blur_axis_ratio"] = float(res["blur_shape"]["rho"][0])
            metrics["blur_anisotropic"] = bool(res["blur_shape"]["aniso"][0])
        if "noise_sigma" in res:
            metrics["noise_sigma_255"] = float(res["noise_sigma"][0]) * 127.5
        if is_multi_kind(self.cfg) and clock:
            probs = clock["type_logits"].softmax(1)[0]
            metrics["type_probs"] = {KINDS[i]: float(probs[i]) for i in range(len(KINDS))}
        if gt is not None:
            gt_t = gt if isinstance(gt, torch.Tensor) else load_image_tensor(gt, self.cfg.real_max_side)[0]
            gt_t = gt_t.to(self.device).float()
            if gt_t.shape[-2:] != out.shape[-2:]:  # e.g. after the out-of-memory fallback
                gt_t = F.interpolate(gt_t, size=out.shape[-2:], mode="bicubic", align_corners=False,
                                     antialias=True).clamp(-1, 1)
            if gt_t.shape[-2:] == out.shape[-2:]:
                metrics.update({"psnr": psnr(out, gt_t).item(), "ssim": ssim(out, gt_t).item(),
                                "psnr_input": psnr(y, gt_t).item(), "ssim_input": ssim(y, gt_t).item()})
        save_json(metrics, save_dir / "metrics.json")
        self._comparison_figure([("Input", to01(y[0]), "#ff4444"), ("Restored", to01(out[0]), "#00ff88"),
                                 ("Estimated clock tau(x)", maps["clock_field"], "#44aaff"),
                                 ("Uncertainty", maps.get("uncertainty", maps["residual"]), "#ffaa00")],
                                "Blind restoration with Clock-Field Cold Diffusion", save_dir / "comparison.png")
        self._spectra_figure({"input": y, "restored": out}, save_dir / "radial_spectra.png")
        print(f"[real] {image_path.name}: kind {metrics['kind']}, mean tau {metrics['mean_tau']:.3f} "
              f"(sigma~{metrics['mean_sigma_px']:.2f}px), {res['steps']} steps -> {save_dir}"
              + (f" | PSNR {metrics['psnr_input']:.2f} -> {metrics['psnr']:.2f} dB "
                 f"({metrics['psnr'] - metrics['psnr_input']:+.2f})" if "psnr" in metrics else ""))
        res["metrics"] = metrics
        return res

    def deblur_real_image(self, image_path: str, save_path: Optional[str] = None) -> torch.Tensor:
        """Backwards-compatible name of the old API."""
        save_dir = Path(save_path).with_suffix("") if save_path else None
        return self.restore_real_image(image_path, save_dir=save_dir)["output"]

    @torch.no_grad()
    def strength_sweep(self, image: Union[str, Path, torch.Tensor], strengths: Optional[Sequence[float]] = None,
                       save_dir: Optional[Path] = None) -> Dict[float, torch.Tensor]:
        """Restoration-strength control: tau_obs = kappa * tau_hat."""
        strengths = list(strengths or self.cfg.strength_sweep)
        save_dir = save_dir or self._dir("strength_sweep")
        y = load_image_tensor(image, self.cfg.real_max_side)[0] if not isinstance(image, torch.Tensor) else image
        y = y.to(self.device).float()
        outs = {}
        for s in strengths:
            with self._infer_autocast():
                outs[s] = self.model.restore(y, strength=s, lam=self.cfg.rn_lambda_real, sampler=self.real_sampler,
                                             generator=self._gen())["output"].float()
        grid = make_grid(torch.cat([to01(y)] + [to01(outs[s]) for s in strengths]).cpu(), nrow=len(strengths) + 1, padding=2)
        save_image(grid, save_dir / "strength_sweep.png")
        panels = [("input", to01(y[0]), "#ff4444")] + [(f"kappa = {s}", to01(outs[s][0]), "#00ff88") for s in strengths]
        self._comparison_figure(panels, "Controllable restoration strength", save_dir / "strength_sweep_figure.png")
        return outs

    # ---- capability 3: generation -----------------------------------------------------------------------
    @torch.no_grad()
    def generate_samples(self, num_samples: Optional[int] = None, image_size: Optional[Tuple[int, int]] = None,
                         steps: Optional[int] = None, save_dir: Optional[Path] = None,
                         fit_loader: Optional[DataLoader] = None) -> Optional[torch.Tensor]:
        num_samples = num_samples or self.cfg.generate_num
        image_size = tuple(image_size or self.cfg.image_size)
        save_dir = Path(save_dir) if save_dir else self._dir("generated")
        save_dir.mkdir(parents=True, exist_ok=True)
        if float(self.model.prior_ready.item()) < 0.5:
            if fit_loader is None or not self.model.fit_prior(fit_loader, self.device):
                print("[generate] no degraded prior available - skipped.")
                return None
        print(f"Generating {num_samples} samples...")
        res = self.model.generate(num_samples, image_size, steps=steps, record=True, generator=self._gen(7))
        samples = res["output"]
        for i in range(num_samples):
            save_image(to01(samples[i]), save_dir / f"generated_sample_{i:03d}.png")
        nrow = min(4, num_samples)
        save_image(make_grid(to01(samples).cpu(), nrow=nrow, padding=2), save_dir / "generated_grid.png")
        save_image(make_grid(to01(res["prior_sample"]).cpu(), nrow=nrow, padding=2), save_dir / "prior_samples_grid.png")
        self._trajectory_strip(res, save_dir / "generation_trajectory.png", idx=0)
        if self.cfg.save_gif and res["trajectory"]:
            save_gif([to01(f[0]) for f in res["trajectory"]], save_dir / "generation.gif")
        print(f"Samples saved to {save_dir}")
        return samples

    # ---- capability 4: clock estimator evaluation ----------------------------------------------------------
    @torch.no_grad()
    def evaluate_clock(self, loader: DataLoader, max_batches: Optional[int] = None, save_dir: Optional[Path] = None) -> Dict[str, Any]:
        save_dir = save_dir or self._dir("clock_estimator")
        max_batches = max_batches or self.cfg.eval_max_batches
        taus = list(self.cfg.eval_taus) + ["field"]
        t_true, t_raw, t_smooth, err_abs, pred_scale = [], [], [], [], []
        per_tau: Dict[str, List[float]] = {}
        correct, total = 0, 0
        for bi, batch in enumerate(loader):
            if bi >= max_batches:
                break
            x0 = batch["image"].to(self.device).float()
            B, C, H, W = x0.shape
            for ti, tv in enumerate(taus):
                g = self._gen(5000 + 1000 * bi + ti)
                kind = self.model.sample_kind(B, self.device, g)
                st = self.model.degradation.new_state(x0, g)
                tau = self.model.degradation.effective_tau(self._tau_map(tv, B, H, W, g), kind, st)
                y, _ = self.model.degradation.apply(x0, tau, kind, st)
                est = self.model.estimate_clock(self._observe(y, g))
                sub = (slice(None), slice(None), slice(None, None, 8), slice(None, None, 8))
                t_true.append(tau[sub].flatten().cpu())
                t_raw.append(est["tau_mu"][sub].flatten().cpu())
                t_smooth.append(est["tau_smooth"][sub].flatten().cpu())
                err_abs.append((est["tau_mu"] - tau)[sub].abs().flatten().cpu())
                pred_scale.append(est["tau_logscale"][sub].exp().flatten().cpu())
                per_tau.setdefault(str(tv), []).append((est["tau_smooth"] - tau).abs().mean().item())
                correct += int((est["type_logits"].argmax(1) == kind).sum())
                total += B
        if not t_true:
            return {}
        tt, tr, ts = torch.cat(t_true), torch.cat(t_raw), torch.cat(t_smooth)
        ea, ps = torch.cat(err_abs), torch.cat(pred_scale)
        out = {"mae_raw": float((tr - tt).abs().mean()), "mae_smoothed": float((ts - tt).abs().mean()),
               "mae_per_tau": {k: float(np.mean(v)) for k, v in per_tau.items()},
               "uncertainty_error_pearson": pearson(ps, ea)}
        if is_multi_kind(self.cfg):
            out["type_accuracy"] = correct / max(total, 1)
        save_json(out, save_dir / "clock_metrics.json")
        fig, axes = plt.subplots(1, 3, figsize=(17, 5))
        axes[0].hexbin(tt.numpy(), ts.numpy(), gridsize=40, cmap="viridis", mincnt=1)
        axes[0].plot([0, 1], [0, 1], "r--")
        axes[0].set_xlabel("true tau")
        axes[0].set_ylabel("estimated tau (smoothed)")
        axes[0].set_title(f"Spectral Clock Estimator  MAE={out['mae_smoothed']:.3f}")
        ks = list(out["mae_per_tau"].keys())
        axes[1].bar(ks, [out["mae_per_tau"][k] for k in ks], color="#44aaff")
        axes[1].set_title("MAE per degradation level")
        q = torch.quantile(ps, torch.linspace(0, 1, 11))
        xs, ys = [], []
        for i in range(10):
            m = (ps >= q[i]) & (ps <= q[i + 1])
            if m.any():
                xs.append(float(ps[m].mean()))
                ys.append(float(ea[m].mean()))
        axes[2].plot(xs, ys, "o-", label="estimator")
        lim = max(xs + ys + [1e-3])
        axes[2].plot([0, lim], [0, lim], "k--", label="perfect (Laplace: E|e| = b)")
        axes[2].set_xlabel("predicted scale b")
        axes[2].set_ylabel("mean |error|")
        axes[2].set_title(f"Clock uncertainty calibration (r={out['uncertainty_error_pearson']:.2f})")
        axes[2].legend()
        for a in axes:
            a.grid(True, alpha=0.3)
        plt.tight_layout()
        fig.savefig(save_dir / "clock_estimator.png", dpi=150)
        plt.close(fig)
        print(f"[clock] MAE raw {out['mae_raw']:.4f} | smoothed {out['mae_smoothed']:.4f} | "
              f"uncertainty/error r = {out['uncertainty_error_pearson']:.3f}")
        return out

    # ---- capability 5: interpretability ---------------------------------------------------------------
    @torch.no_grad()
    def interpret(self, image: torch.Tensor, tau: Union[float, str, torch.Tensor] = "field",
                  save_dir: Optional[Path] = None) -> Dict[str, Any]:
        """Everything that helps understanding one restoration (single image)."""
        save_dir = save_dir or self._dir("interpretability")
        m = self.model
        x0 = image[:1].to(self.device).float()
        g = self._gen(99)
        kind = m.sample_kind(1, self.device, g)
        if is_multi_kind(m.cfg) and BLUR in allowed_kinds(m.cfg):
            kind = torch.full_like(kind, BLUR)  # the spectral analyses are defined for (isotropic) blur
        shape = "iso" if int(kind[0]) == BLUR else None
        res = self.infer(x0, tau=tau, kind=kind, sampler="srn", record=True, generator=g, shape=shape)
        res_imp = self.infer(x0, tau=res["tau_true"], kind=kind, sampler="improved", record=False,
                             generator=self._gen(99), shape=shape)
        y, out, tau_t = res["degraded"], res["output"], res["tau_true"]
        summary: Dict[str, Any] = {"metrics_srn": res["metrics"], "metrics_improved": res_imp["metrics"],
                                   "steps": res["steps"], "kind": KINDS[int(kind[0])]}

        # 1) trajectory
        self._trajectory_strip(res, save_dir / "trajectory_strip.png", idx=0)
        if self.cfg.save_gif and res["trajectory"]:
            frames = [torch.cat([to01(a[0]), to01(b[0])], -1) for a, b in zip(res["trajectory"], res["x0_trajectory"])]
            save_gif(frames, save_dir / "trajectory_state_vs_x0.gif")
        if res["psnr_trajectory"]:
            fig, ax1 = plt.subplots(figsize=(7, 4))
            ax1.plot(res["psnr_trajectory"], "b-o", ms=3, label="PSNR(x0_hat_k)")
            ax1.set_xlabel("sampling step k")
            ax1.set_ylabel("PSNR (dB)", color="b")
            if res["uncertainty_trajectory"]:
                ax2 = ax1.twinx()
                ax2.plot(res["uncertainty_trajectory"], "r--", label="mean predicted scale")
                ax2.set_ylabel("mean uncertainty b", color="r")
            ax1.set_title("Restoration along the SRN trajectory")
            ax1.grid(True, alpha=0.3)
            plt.tight_layout()
            fig.savefig(save_dir / "trajectory_metrics.png", dpi=150)
            plt.close(fig)

        # 2) attention + features at the first sampling step
        summary["attention"] = self._attention_and_features(y, tau_t, kind, save_dir)

        # 3) spectral gate gain curves  [N3]
        summary["spectral_gates"] = self._spectral_gate_curves(tau_t, kind, y.shape[-2:], save_dir)

        # 4) range / null-space decomposition  [N2]
        summary["range_null"] = self._range_null_figure(x0, y, out, res_imp["output"], tau_t, kind, save_dir)

        # 5) radial spectra
        self._spectra_figure({"clean": x0, "degraded": y, "restored (SRN)": out, "restored (Alg. 2)": res_imp["output"]},
                             save_dir / "radial_spectra.png")

        # 6) uncertainty
        if res["uncertainty"] is not None:
            summary["uncertainty"] = self._uncertainty_figure(res["x0"], x0, res["uncertainty"], save_dir)

        # 7) clock sensitivity d x0_hat / d tau
        d = 0.05
        xp = m.denoise(y, (tau_t + d).clamp(0, 1), kind)["x0"]
        xm = m.denoise(y, (tau_t - d).clamp(0, 1), kind)["x0"]
        sens = (xp - xm).abs().mean(1)[0] / (2 * d)
        save_image(colorize(sens, "magma"), save_dir / "clock_sensitivity.png")
        summary["clock_sensitivity_mean"] = float(sens.mean())

        # 8) clock estimation
        est = m.estimate_clock(y)
        maps = [colorize(tau_t[0, 0], "viridis", 0, 1), colorize(est["tau_mu"][0, 0], "viridis", 0, 1),
                colorize(est["tau_smooth"][0, 0], "viridis", 0, 1), colorize(torch.exp(-est["tau_logscale"][0, 0]), "cividis"),
                colorize((est["tau_smooth"] - tau_t)[0, 0].abs(), "magma", 0, 0.5)]
        save_image(make_grid(torch.stack(maps), nrow=5, padding=2), save_dir / "clock_true_raw_smooth_conf_err.png")
        phys = est["physics"][0]
        save_image(make_grid(torch.stack([colorize(phys[i]) for i in range(phys.shape[0])]), nrow=phys.shape[0], padding=2),
                   save_dir / "clock_physics_features.png")
        summary["clock_mae"] = float((est["tau_smooth"] - tau_t).abs().mean())

        # 9) main figure + raw tensors
        self.visualize_results(res, save_path=str(save_dir / "overview.png"))
        torch.save({k: (v.cpu() if isinstance(v, torch.Tensor) else v) for k, v in
                    {"input": x0, "degraded": y, "output": out, "x0": res["x0"], "tau_true": tau_t, "tau_obs": res["tau_obs"],
                     "uncertainty": res["uncertainty"], "clock_mu": est["tau_mu"], "clock_smooth": est["tau_smooth"],
                     "clock_sensitivity": sens}.items()}, save_dir / "tensors.pt")
        save_json(summary, save_dir / "interpretability_summary.json")
        print(f"[interpret] saved to {save_dir}")
        return summary

    def _attention_and_features(self, y, tau, kind, save_dir: Path) -> Dict[str, Any]:
        net = self.model.model
        feats: Dict[str, torch.Tensor] = {}
        named = {"stem": net.inp, "enc_block1": net.enc.block1, "enc_block2": net.enc.block2, "enc_block3": net.enc.block3,
                 "bottleneck": net.trans, "dec_H/4": net.dec.up_conv3, "dec_H/2": net.dec.up_conv2, "dec_H": net.dec.up_conv1}
        hooks = [mod.register_forward_hook(lambda _m, _i, o, n=n: feats.__setitem__(n, o.detach().float()))
                 for n, mod in named.items()]
        attn_mods = [blk.attn for blk in net.trans.swin_blocks]
        for a in attn_mods:
            a.capture = True
        try:
            self.model.denoise(y, tau, kind)
        finally:
            for h in hooks:
                h.remove()
            for a in attn_mods:
                a.capture = False
        # feature PCA
        tiles = []
        H, W = y.shape[-2:]
        for n in named:
            if n in feats:
                rgb = self._pca_rgb(feats[n][0])
                tiles.append(F.interpolate(rgb[None], size=(H, W), mode="nearest")[0])
        if tiles:
            save_image(make_grid(torch.stack(tiles), nrow=len(tiles), padding=2), save_dir / "feature_pca_stages.png")
        # attention
        out: Dict[str, Any] = {"feature_stages": list(feats.keys())}
        for i, a in enumerate(attn_mods):
            A = a.last_attn
            if A is None:
                continue
            nW, heads, N, _ = A.shape
            dist = a.relative_distance.to(A.device)
            mean_dist = (A * dist).sum(-1).mean((0, 2))
            entropy = -(A * (A + 1e-12).log()).sum(-1).mean((0, 2))
            out[f"block{i}"] = {"mean_attention_distance": mean_dist.cpu().tolist(), "attention_entropy": entropy.cpu().tolist(),
                                "shifted": bool(any(net.trans.swin_blocks[i].shift_size))}
            wh, ww = a.window_size
            q = (wh // 2) * ww + ww // 2
            w_idx = nW // 2
            fig, axes = plt.subplots(1, heads + 2, figsize=(2.2 * (heads + 2), 2.6))
            for h_ in range(heads):
                axes[h_].imshow(A[w_idx, h_, q].view(wh, ww).cpu().numpy(), cmap="viridis")
                axes[h_].set_title(f"head {h_}", fontsize=8)
                axes[h_].axis("off")
            axes[heads].bar(range(heads), mean_dist.cpu().numpy(), color="#44aaff")
            axes[heads].set_title("mean distance", fontsize=8)
            axes[heads + 1].bar(range(heads), entropy.cpu().numpy(), color="#ffaa00")
            axes[heads + 1].set_title("entropy", fontsize=8)
            plt.suptitle(f"Swin block {i} attention (centre query, window {w_idx})", fontsize=10)
            plt.tight_layout()
            fig.savefig(save_dir / f"attention_block{i}.png", dpi=130)
            plt.close(fig)
        return out

    @staticmethod
    def _pca_rgb(feat: torch.Tensor) -> torch.Tensor:
        C, h, w = feat.shape
        X = feat.reshape(C, -1).T
        X = X - X.mean(0, keepdim=True)
        q = min(3, C)
        _, _, V = torch.pca_lowrank(X, q=q, center=False)
        P = (X @ V[:, :q]).T.reshape(q, h, w)
        if q < 3:
            P = torch.cat([P, P[:1].expand(3 - q, h, w)], 0)
        lo = torch.quantile(P.flatten(1), 0.01, dim=1).view(3, 1, 1)
        hi = torch.quantile(P.flatten(1), 0.99, dim=1).view(3, 1, 1)
        return ((P - lo) / (hi - lo).clamp_min(1e-6)).clamp(0, 1).cpu()

    def _spectral_gate_curves(self, tau, kind, hw, save_dir: Path) -> Dict[str, Any]:
        net = self.model.model
        gates = [("bottleneck H/8", getattr(net.trans, "gate", None)), ("decoder H/4", getattr(net.dec, "gate3", None))]
        gates = [(n, g) for n, g in gates if g is not None]
        if not gates:
            return {}
        sig_img = float(self.model.sigma_bar(tau, kind)[0])
        sweep = [0.0, 2.0, 5.0, 10.0, max(sig_img, 0.0)]
        fig, axes = plt.subplots(1, len(gates), figsize=(7 * len(gates), 4.5), squeeze=False)
        info = {"sigma_bar_px": sig_img}
        for ax, (name, gate) in zip(axes[0], gates):
            h, w = max(1, hw[0] // gate.downscale), max(1, hw[1] // gate.downscale)
            r = HeatKernel.omega_sq(h, w, self.device).sqrt().flatten()
            bins = torch.linspace(0, float(r.max()) + 1e-6, 33, device=self.device)
            idx = torch.bucketize(r, bins).clamp(1, 32) - 1
            centers = (0.5 * (bins[1:] + bins[:-1]) / math.pi).cpu().numpy()
            for s in sweep:
                lg = gate.log_gain(torch.tensor([s / gate.downscale], device=self.device), h, w)[0].flatten(1)  # (C, n)
                prof = torch.zeros(lg.shape[0], 32, device=self.device).index_add_(1, idx, lg)
                cnt = torch.zeros(32, device=self.device).index_add_(0, idx, torch.ones_like(r))
                valid = (cnt > 0).cpu().numpy()  # low feature resolutions leave some radial bins empty
                prof = (prof / cnt.clamp_min(1)).cpu().numpy()[:, valid]
                style = "-" if s != sweep[-1] else "k-"
                ax.plot(centers[valid], prof.mean(0), style, label=f"sigma={s:.1f}px" + (" (this image)" if s == sweep[-1] else ""))
                ax.fill_between(centers[valid], prof.mean(0) - prof.std(0), prof.mean(0) + prof.std(0), alpha=0.12)
            sf = sig_img / gate.downscale
            ax.plot(centers, 0.5 * sf ** 2 * (centers * math.pi) ** 2, "r:", label="full inverse heat (reference)")
            ax.set_ylim(-1.5, 4)
            ax.set_xlabel("|w| / pi (feature resolution)")
            ax.set_ylabel("log gain")
            ax.set_title(f"Clock-Aware Spectral Gate - {name}")
            ax.grid(True, alpha=0.3)
            ax.legend(fontsize=7)
            info[name] = {"mean_inverse_fraction": float(torch.sigmoid(gate.alpha).mean()),
                          "mean_log_ceiling": float(F.softplus(gate.ceiling).mean())}
        plt.tight_layout()
        fig.savefig(save_dir / "spectral_gate_gains.png", dpi=150)
        plt.close(fig)
        return info

    def _range_null_figure(self, x0, y, out, out_imp, tau, kind, save_dir: Path) -> Dict[str, Any]:
        deg = self.model.degradation
        lam = self.cfg.rn_lambda
        with autocast_off(out.device.type):
            h, w = out.shape[-2:]
            sig = deg.sigma(tau.flatten(1)).pow(2).mean(1).sqrt()
            K = HeatKernel.transfer(sig, h, w, out.device)
            P = K ** 2 / (K ** 2 + lam)
            rng = HeatKernel.inverse(HeatKernel.spectrum(out) * P, h, w)
        null = out - rng
        iso = deg.new_state(out, shape="iso")  # interpret() uses isotropic blur for the spectral analyses
        dc_srn = float((deg.apply(out, tau, kind, iso)[0] - y).abs().mean())
        dc_imp = float((deg.apply(out_imp, tau, kind, iso)[0] - y).abs().mean())
        info = {"range_energy": float(rng.pow(2).mean()), "null_energy": float(null.pow(2).mean()),
                "data_consistency_l1_srn": dc_srn, "data_consistency_l1_improved": dc_imp,
                "null_space_recovery_srn": float(null_space_recovery(out, x0, y, tau, kind, deg).mean()),
                "null_space_recovery_improved": float(null_space_recovery(out_imp, x0, y, tau, kind, deg).mean())}
        # clean | degraded | restored | range component | null component (x4) | |error|
        tiles = [to01(x0[0]), to01(y[0]), to01(out[0]), to01(rng[0]), to01(4 * null[0]),
                 colorize((out - x0)[0].abs().mean(0), "magma", 0, 0.3)]
        save_image(make_grid(torch.stack([t.float().cpu() for t in tiles]), nrow=len(tiles), padding=2),
                   save_dir / "range_null_decomposition.png")
        return info

    def _uncertainty_figure(self, x0_hat, x0, unc, save_dir: Path) -> Dict[str, float]:
        err = (x0_hat - x0).abs().flatten().cpu()
        b = unc.flatten().float().cpu()
        q = torch.quantile(b, torch.linspace(0, 1, 11))
        xs, ys = [], []
        for i in range(10):
            msk = (b >= q[i]) & (b <= q[i + 1])
            if msk.any():
                xs.append(float(b[msk].mean()))
                ys.append(float(err[msk].mean()))
        fig, axes = plt.subplots(1, 3, figsize=(15, 4.5))
        axes[0].imshow(unc[0].mean(0).cpu().numpy(), cmap="inferno")
        axes[0].set_title("predicted scale b(x)")
        axes[1].imshow((x0_hat - x0)[0].abs().mean(0).cpu().numpy(), cmap="magma")
        axes[1].set_title("|x0_hat - x0|")
        for a in axes[:2]:
            a.axis("off")
        axes[2].plot(xs, ys, "o-", label="model")
        lim = max(xs + ys + [1e-3])
        axes[2].plot([0, lim], [0, lim], "k--", label="calibrated (E|e| = b)")
        axes[2].set_xlabel("predicted b")
        axes[2].set_ylabel("mean |error|")
        axes[2].legend()
        axes[2].grid(True, alpha=0.3)
        r = pearson(b, err)
        axes[2].set_title(f"Reliability diagram (r = {r:.2f})")
        plt.tight_layout()
        fig.savefig(save_dir / "uncertainty.png", dpi=150)
        plt.close(fig)
        return {"pearson_error_uncertainty": r, "mean_b": float(b.mean()), "mean_abs_error": float(err.mean())}

    # ---- figures -------------------------------------------------------------------------------------
    def _trajectory_strip(self, res: Dict[str, Any], path: Path, idx: int = 0, n_frames: int = 8):
        traj, traj0 = res.get("trajectory") or [], res.get("x0_trajectory") or []
        if not traj:
            return
        sel = np.unique(np.linspace(0, len(traj) - 1, min(n_frames, len(traj))).round().astype(int))
        top = [to01(traj[i][idx]) for i in sel]
        bot = [to01(traj0[i][idx]) for i in sel]
        save_image(make_grid(torch.stack(top + bot), nrow=len(sel), padding=2), path)

    def _comparison_figure(self, panels: List[Tuple[str, torch.Tensor, str]], title: str, path: Path):
        fig, axes = plt.subplots(1, len(panels), figsize=(4.2 * len(panels), 4.6))
        axes = np.atleast_1d(axes)
        fig.patch.set_facecolor(DARK_BG)
        for ax, (t, img, color) in zip(axes, panels):
            ax.imshow(img.detach().float().cpu().permute(1, 2, 0).clamp(0, 1).numpy())
            ax.set_title(t, fontsize=12, fontweight="bold", color=color, pad=8)
            ax.set_xticks([])
            ax.set_yticks([])
            for spine in ax.spines.values():
                spine.set_color(color)
                spine.set_linewidth(3)
        fig.suptitle(title, fontsize=15, fontweight="bold", color="white")
        plt.tight_layout()
        fig.savefig(path, dpi=160, facecolor=DARK_BG, bbox_inches="tight")
        plt.close(fig)

    def _spectra_figure(self, images: Dict[str, torch.Tensor], path: Path):
        fig, ax = plt.subplots(figsize=(7, 4.5))
        for name, img in images.items():
            f, p = radial_power_spectrum(img)
            ax.plot(f, p, label=name)
        ax.set_xlabel("normalised radial frequency (1 = Nyquist)")
        ax.set_ylabel("log10 power")
        ax.set_title("Radially averaged power spectra")
        ax.grid(True, alpha=0.3)
        ax.legend()
        plt.tight_layout()
        fig.savefig(path, dpi=150)
        plt.close(fig)

    def visualize_results(self, results: Dict[str, Any], save_path: Optional[str] = None):
        """Overview figure: one row per sample with clean / degraded / restored / error / clock /
        (estimated clock) / uncertainty, plus a timeline of x0_hat along the trajectory."""
        x0, y, out = results["input"], results["degraded"], results["output"]
        n = min(4, x0.shape[0])
        cols = [("Clean", lambda i: to01(x0[i]), "#00ff88"),
                ("Degraded", lambda i: to01(y[i]), "#ff4444"),
                ("Restored", lambda i: to01(out[i]), "#ffaa00"),
                ("|Error|", lambda i: colorize((out[i] - x0[i]).abs().mean(0), "magma", 0, 0.3), "#ff66cc"),
                ("True clock" if results.get("blind") else "Clock tau(x)",
                 lambda i: colorize(results.get("tau_true", results["tau_obs"])[i, 0], "viridis", 0, 1), "#44aaff")]
        if results.get("blind"):
            cols.append(("Estimated clock", lambda i: colorize(results["tau_obs"][i, 0], "viridis", 0, 1), "#88ccff"))
        if results.get("uncertainty") is not None:
            cols.append(("Uncertainty", lambda i: colorize(results["uncertainty"][i].mean(0), "inferno"), "#ffdd44"))
        traj0 = results.get("x0_trajectory") or []
        tl = []
        if traj0:
            sel = np.unique(np.linspace(0, len(traj0) - 1, min(len(cols), len(traj0))).round().astype(int))
            tl = [(f"x0_hat step {i}", to01(traj0[i][0])) for i in sel]
        n_rows, n_cols = n + (1 if tl else 0), max(len(cols), len(tl))
        fig = plt.figure(figsize=(2.6 * n_cols, 2.8 * n_rows + 0.6), dpi=110)
        fig.patch.set_facecolor(DARK_BG)
        gs = fig.add_gridspec(n_rows, n_cols, hspace=0.18, wspace=0.04)
        for r in range(n):
            for c, (name, fn, color) in enumerate(cols):
                ax = fig.add_subplot(gs[r, c])
                ax.imshow(fn(r).detach().float().cpu().permute(1, 2, 0).clamp(0, 1).numpy())
                ax.axis("off")
                if r == 0:
                    ax.set_title(name, fontsize=10, fontweight="bold", color=color)
        for c, (name, img) in enumerate(tl):
            ax = fig.add_subplot(gs[n, c])
            ax.imshow(img.permute(1, 2, 0).clamp(0, 1).numpy())
            ax.axis("off")
            ax.set_title(name, fontsize=9, color="#bbbbbb")
        m = results.get("metrics", {})
        info = (f"Clock-Field Cold Diffusion | sampler: {results.get('sampler')} | steps: {results.get('steps')} | "
                f"degradation: {self.model.degradation_type} | schedule: {self.model.schedule_type} | "
                f"PSNR {m.get('psnr', float('nan')):.2f} dB (input {m.get('psnr_input', float('nan')):.2f}) | "
                f"SSIM {m.get('ssim', float('nan')):.3f} | NSR {m.get('nsr', float('nan')):.2f}")
        fig.text(0.5, 0.005, info, fontsize=9, color="#aaaaaa", ha="center")
        if save_path:
            fig.savefig(save_path, dpi=150, facecolor=DARK_BG, bbox_inches="tight")
            print(f"Visualization saved to {save_path}")
        plt.close(fig)
        return fig

    # ---- orchestration ----------------------------------------------------------------------------------
    def run_all(self, dataset: Dataset, real_image_paths: Optional[Sequence[Union[str, Path]]] = None,
                real_pairs: Optional[Sequence["PairedImageDataset"]] = None) -> Dict[str, Any]:
        """dataset: CLEAN test images (synthetic degradations); real_pairs: real blur/sharp benchmarks;
        real_image_paths: real blurred photos (ground truth from the sibling 'sharp' folder when present)."""
        cfg = self.cfg
        summary: Dict[str, Any] = {"checkpoint": self.loaded_from}
        eval_loader = DataLoader(dataset, batch_size=min(cfg.batch_size, 4), shuffle=False, num_workers=0)
        demo_loader = DataLoader(dataset, batch_size=min(cfg.infer_num_images, len(dataset)), shuffle=False, num_workers=0)
        demo = next(iter(demo_loader))["image"]

        summary["evaluation"] = self._safe("evaluate", lambda: self.evaluate(eval_loader))

        def _demo(blind: bool):
            d = self._dir("demo_blind" if blind else "demo_known_clock")
            res = self.infer(demo, tau="field", sampler=cfg.sampler, blind=blind, record=True, generator=self._gen(3))
            self.visualize_results(res, save_path=str(d / "inference_results.png"))
            save_image(make_grid(torch.cat([to01(res["input"]), to01(res["degraded"]), to01(res["output"])]).cpu(),
                                 nrow=res["input"].shape[0], padding=2), d / "clean_degraded_restored.png")
            save_json(res["metrics"], d / "metrics.json")
            print(f"[demo {'blind' if blind else 'known clock'}] {res['metrics']}")
            return res["metrics"]

        summary["demo_known_clock"] = self._safe("demo", lambda: _demo(False))
        summary["demo_blind"] = self._safe("demo_blind", lambda: _demo(True))
        summary["clock_estimator"] = self._safe("evaluate_clock", lambda: self.evaluate_clock(eval_loader))
        summary["interpretability"] = self._safe("interpret", lambda: self.interpret(demo[:1], tau="field"))
        summary["generation"] = self._safe("generate", lambda: (self.generate_samples(fit_loader=eval_loader) is not None))

        # "File" example: a clean test image with a spatially varying MOTION blur, written to disk and
        # restored *blindly* from the file, then compared with the ground truth.
        def _real_demo():
            d = self._dir("real_demo")
            g = self._gen(11)
            x0 = demo[:1].to(self.device).float()
            _, _, H, W = x0.shape
            ok = allowed_kinds(cfg)
            kind = torch.full((1,), BLUR if BLUR in ok else ok[0], dtype=torch.long, device=self.device)
            st = self.model.degradation.new_state(x0, g, shape="motion" if int(kind[0]) == BLUR else None)
            tau = self.model.degradation.effective_tau(self.model.sample_tau(1, H, W, self.device, g, force_field=True), kind, st)
            y, _ = self.model.degradation.apply(x0, tau, kind, st)
            y = self._observe(y, g)
            demo_path = d / "demo_degraded_image.png"
            tensor_to_pil(y).save(demo_path)
            tensor_to_pil(x0).save(d / "demo_ground_truth.png")
            save_image(colorize(tau[0, 0], "viridis", 0, 1), d / "demo_true_clock.png")
            print(f"Using demo image: {demo_path}")
            r = self.restore_real_image(demo_path, save_dir=d / "restoration", gt=d / "demo_ground_truth.png")
            self._safe("strength_sweep", lambda: self.strength_sweep(demo_path, save_dir=self._dir("real_demo", "strength_sweep")))
            return r["metrics"]

        summary["real_demo"] = self._safe("real_demo", _real_demo)
        # REAL benchmarks: blind restoration of real blurred photos vs their sharp frames
        for ds in (real_pairs or []):
            summary[f"real_benchmark_{ds.name}"] = self._safe(f"real_benchmark:{ds.name}",
                                                              lambda ds=ds: self.evaluate_real_pairs(ds))
        if real_image_paths:
            summary["real_images"] = [self._safe(f"real:{p}", lambda p=p: self.restore_real_image(p)["metrics"])
                                      for p in list(real_image_paths)[:cfg.infer_num_images]]
        save_json(summary, self.root / "inference_summary.json")
        print(f"\nAll inference outputs are in {self.root}")
        return summary

    # ---- capability 6: real paired benchmark (GoPro / HIDE / RealBlur test) ---------------------------------
    @torch.no_grad()
    def evaluate_real_pairs(self, dataset: "PairedImageDataset", samplers: Optional[Sequence[str]] = None,
                            max_images: Optional[int] = None, save_dir: Optional[Path] = None, n_examples: int = 4) -> Dict[str, Any]:
        """
        BLIND restoration of real blurred photos compared with their real sharp frames (PSNR / SSIM /
        LPIPS on [0, 1]), at native resolution unless real_eval_max_side is set (on out-of-memory the
        image is evaluated at 768 px). This is the benchmark that measures the actual goal.
        """
        cfg = self.cfg
        samplers = list(samplers or cfg.real_eval_samplers)
        n = len(dataset) if not (max_images or cfg.real_eval_max_images) else min(len(dataset), max_images or cfg.real_eval_max_images)
        idxs = [int(i) for i in np.linspace(0, len(dataset) - 1, n)] if n < len(dataset) else list(range(len(dataset)))
        save_dir = save_dir or self._dir("real_benchmark", dataset.name)
        rows = []
        for j, i in enumerate(tqdm(idxs, desc=f"Real benchmark {dataset.name}")):
            item = dataset[i]
            x0, y = item["image"][None].to(self.device), item["degraded"][None].to(self.device)
            if cfg.real_eval_max_side and max(x0.shape[-2:]) > cfg.real_eval_max_side:
                x0, y = self._resize_pair(x0, y, cfg.real_eval_max_side)
            row = {"image": Path(item["path"]).name, "psnr_input": psnr(y, x0).item(), "ssim_input": ssim(y, x0).item()}

            def run_samplers(x0, y, i=i):
                outs, vals = {}, {}
                for s in samplers:
                    t0 = time.time()
                    with self._infer_autocast():
                        r = self.model.restore(y, sampler=s, steps=cfg.val_sampler_steps, lam=cfg.rn_lambda_real,
                                               generator=self._gen(i))
                    out = r["output"].float()
                    outs[s] = out
                    vals[f"psnr_{s}"] = psnr(out, x0).item()
                    vals[f"ssim_{s}"] = ssim(out, x0).item()
                    vals[f"sec_{s}"] = time.time() - t0
                    if self.lpips is not None:
                        v = self.lpips(out, x0)
                        if v is not None:
                            vals[f"lpips_{s}"] = v.mean().item()
                    if "blur_shape" in r:
                        vals["blur_direction_deg"] = float(torch.rad2deg(r["blur_shape"]["theta"][0]))
                        vals["blur_axis_ratio"] = float(r["blur_shape"]["rho"][0])
                    vals["mean_tau"] = float(r["tau_obs"].mean())
                    vals["kind"] = KINDS[int(r["kind"][0])]
                    vals["is_blur"] = float(int(r["kind"][0]) == BLUR)
                return outs, vals

            try:
                outs, vals = run_samplers(x0, y)
            except RuntimeError as e:  # CUDA OOM at native resolution -> the WHOLE image (every sampler) at 768 px;
                if "out of memory" not in str(e).lower():  # before, samplers already run stayed at native size
                    raise  # (mixed-resolution metrics and a crash in the example grid)
                outs = None
                torch.cuda.empty_cache()
                x0, y = self._resize_pair(x0, y, 768)
                row.update({"psnr_input": psnr(y, x0).item(), "ssim_input": ssim(y, x0).item(), "resized": 768})
                outs, vals = run_samplers(x0, y)
            row.update(vals)
            rows.append(row)
            if j < n_examples:
                tiles = [to01(y[0]), to01(x0[0])] + [to01(outs[s][0]) for s in samplers]
                save_image(make_grid(torch.stack([t.float().cpu() for t in tiles]), nrow=len(tiles), padding=4),
                           save_dir / f"example_{j:02d}_blur_sharp_{'_'.join(samplers)}.png")
        keys = sorted({k for r in rows for k in r if k != "image" and isinstance(r[k], (int, float))})
        summ = {k: float(np.mean([r[k] for r in rows if k in r])) for k in keys}
        summ["n_images"] = len(rows)
        with open(save_dir / "per_image.csv", "w", newline="") as f:
            w = csv.DictWriter(f, fieldnames=["image", "kind"] + keys)
            w.writeheader()
            w.writerows(rows)
        save_json(summ, save_dir / "summary.json")
        line = " | ".join(f"{s}: {summ.get(f'psnr_{s}', float('nan')):.2f} dB / {summ.get(f'ssim_{s}', float('nan')):.4f}"
                          for s in samplers)
        print(f"[real benchmark {dataset.name}] {len(rows)} images | blurred input {summ['psnr_input']:.2f} dB / "
              f"{summ['ssim_input']:.4f} | {line} | treated as blur: {100 * summ.get('is_blur', 1.0):.0f}%")
        return summ

    def _infer_autocast(self):
        if self.cfg.infer_amp and self.device.type == "cuda":
            return torch.autocast("cuda", dtype=select_amp_dtype(self.device, self.cfg.amp_dtype))
        return contextlib.nullcontext()

    @staticmethod
    def _resize_pair(x0, y, max_side):
        H, W = x0.shape[-2:]
        s = max_side / max(H, W)
        size = (max(8, int(round(H * s / 8)) * 8), max(8, int(round(W * s / 8)) * 8))
        rs = lambda t: F.interpolate(t, size=size, mode="bicubic", align_corners=False, antialias=True).clamp(-1, 1)  # noqa: E731
        return rs(x0), rs(y)


# =======================================================================================
# SECTION 10: MAIN
# =======================================================================================


def build_model(cfg: Config) -> ColdDiffusionModel:
    return ColdDiffusionModel(ViTAL.from_config(cfg), cfg)


def _safe_save(trainer: "Trainer"):
    """Emergency checkpoint after an exception. A failure while saving (e.g. after a CUDA error) must not hide
    the original error, and nothing is written if not a single optimiser step was taken (the files on disk are
    then already the newest state - rewriting them only risks a truncated file)."""
    if trainer.global_step == getattr(trainer, "session_start_step", -1):
        print("  (no optimiser step in this session - existing checkpoints left untouched)")
        return
    try:
        trainer.save_checkpoint(epoch_complete=False)
    except Exception as e:  # noqa: BLE001
        print(f"  could not save the emergency checkpoint: {e}")


def main(cfg: Optional[Config] = None):
    """Train (auto-resuming), then run every inference / interpretability capability.
    No argparse / sys: edit `Config` (or pass a Config instance).
    Kaggle GPU T4 x2: run in a notebook cell (DataParallel) or with
    `torchrun --nproc_per_node=2 <this file>` (DDP)."""
    cfg = cfg or Config()
    setup_distributed(cfg)  # DDP under torchrun (sets cfg.device = cuda:<local_rank>); no-op otherwise
    if not dist_is_on() and int(os.environ.get("RANK", "0")) > 0:
        # torchrun with Config.multi_gpu=False: only rank 0 trains (two independent copies would overwrite each
        # other's checkpoints)
        print(f"[rank {os.environ.get('RANK')}] Config.multi_gpu=False -> this process exits; rank 0 runs alone.")
        return None, None, None
    print("=" * 78)
    print("ViTAL-CF  |  Clock-Field Cold Diffusion - Training & Inference Pipeline")
    print("=" * 78)
    print("Hardware:")
    print(describe_hardware(cfg))
    seed_everything(cfg.seed, cfg.deterministic)
    if is_main_process():
        cfg.save(Path(cfg.checkpoint_dir) / "config.json")
    print("\nConfiguration:")
    for k, v in cfg.to_dict().items():
        print(f"  {k}: {v}")

    print("\n" + "-" * 78)
    print("Creating ViTAL-CF model...")
    model = build_model(cfg)
    print(f"  backbone (ViTAL)          : {count_parameters(model.model):,} parameters")
    print(f"  spectral clock estimator  : {count_parameters(model.clock_estimator):,} parameters")
    print(f"  total                     : {count_parameters(model):,} parameters")
    if get_rank() > 0:  # identical initial weights (DDP also broadcasts them), different random streams per rank
        seed_everything(cfg.seed + 1000 * get_rank(), cfg.deterministic)

    print("\nCreating datasets...")
    audit_datasets(cfg)  # stops if a blurred folder is used as ground truth or blur/sharp look swapped
    train_dataset, val_dataset = build_datasets(cfg)
    print(f"Train dataset: {len(train_dataset)} CLEAN images | Val dataset: {len(val_dataset)} CLEAN images")

    print("\nCreating trainer (auto-resumes from the latest checkpoint if present)...")
    trainer = Trainer(model=model, train_dataset=train_dataset, val_dataset=val_dataset, config=cfg)

    print("\n" + "=" * 78)
    print("Starting Training...")
    print("=" * 78)
    try:
        trainer.train()
        if getattr(trainer, "status", "trained") == "trained":
            print("\nTraining completed successfully!" if trainer.training_complete else
                  "\nTraining stopped (time budget) - checkpoint saved, the next run resumes.")
    except KeyboardInterrupt:
        print("\nTraining interrupted by user - saving an 'interrupted' checkpoint (resume continues at the exact sample).")
        _safe_save(trainer)
    except Exception as e:  # noqa: BLE001
        print(f"\nTraining failed with error: {e}")
        traceback.print_exc()
        _safe_save(trainer)

    # DDP: training is over - rank 0 alone runs inference on cuda:0, the other ranks exit.
    is_main = is_main_process()
    cleanup_distributed()
    if not is_main:
        return model, trainer, None
    if cfg.run_inference == "never" or (cfg.run_inference == "when_done" and not trainer.training_complete):
        print(f"\nInference skipped (run_inference='{cfg.run_inference}', training "
              f"{'complete' if trainer.training_complete else 'not finished yet'}). Checkpoints are in {cfg.checkpoint_dir}; "
              f"the next run resumes training. Set Config.run_inference='always' to evaluate an intermediate model.")
        return model, trainer, None

    print("\n" + "=" * 78)
    print("Running Inference...")
    print("=" * 78)
    deploy = trainer.ema.model if trainer.ema is not None else trainer.model
    inferencer = Inferencer(model=deploy, config=cfg, checkpoint="auto", use_ema=True)
    test_dataset: Dataset = val_dataset  # CLEAN images only (synthetic degradations are applied on top)
    if cfg.test_data_dir and list_images(cfg.test_data_dir):
        test_dataset = ImageDataset(cfg.test_data_dir, cfg.image_size, "val", False, cfg.max_val_images)
    real_images = list_images(cfg.real_images_dir) if cfg.real_images_dir else []
    real_pairs = build_real_pairs(cfg, "test", "test", max_side=cfg.real_eval_max_side)
    inferencer.run_all(test_dataset, real_images, real_pairs)

    final_model_path = Path(cfg.checkpoint_dir) / "final_model.pt"
    example = next(iter(DataLoader(test_dataset, batch_size=2, shuffle=False)))["image"]
    torch.save({"model_state_dict": deploy.state_dict(), "config": cfg.to_dict(), "inference_examples": example.cpu()},
               final_model_path)
    print("\n" + "=" * 78)
    print("Pipeline completed successfully!")
    print("=" * 78)
    print(f"Final model saved to : {final_model_path}")
    print(f"Checkpoints          : {cfg.checkpoint_dir}")
    print(f"Training curves      : {Path(cfg.checkpoint_dir) / 'training_curves.png'}")
    print(f"Inference outputs    : {Path(cfg.output_dir) / 'inference'}")
    return model, trainer, inferencer


def deblur_image_pipeline(model_path: str, image_path: str, output_dir: Optional[str] = None, strength: float = 1.0,
                          device: Optional[str] = None) -> torch.Tensor:
    """Stand-alone blind restoration of one image with a trained checkpoint (best/latest/final)."""
    print("Starting Deblurring Pipeline...")
    ckpt = torch.load(model_path, map_location="cpu", weights_only=False)
    cfg = Config.from_dict(ckpt["config"], device=device or ("cuda" if torch.cuda.is_available() else "cpu"))
    model = build_model(cfg)
    inferencer = Inferencer(model, cfg, checkpoint=model_path, use_ema=True)
    save_dir = Path(output_dir) if output_dir else None
    return inferencer.restore_real_image(image_path, save_dir=save_dir, strength=strength)["output"]


if __name__ == "__main__":
    model, trainer, inferencer = main()
